export const DEX_INFO = {"cobblemon:p0001_bulbasaur": {"n": 1, "d": "Bulbasaur can be seen napping in bright sunlight. There is a seed on its back. By soaking up the sun's rays, the seed grows progressively larger.", "h": 7, "w": 69, "dr": ["0-1x Melon Seeds", "1x Miracle Seed 5%"]}, "cobblemon:p0002_ivysaur": {"n": 2, "d": "There is a bud on this Pokémon's back. To support its weight, Ivysaur's legs and trunk grow thick and strong. If it starts spending more time lying in the sunlight, it's a sign that the bud will bloom into a large flower soon.", "h": 10, "w": 130, "dr": ["0-2x Melon Seeds", "1x Miracle Seed 10%"]}, "cobblemon:p0003_venusaur": {"n": 3, "d": "There is a large flower on Venusaur's back. The flower is said to take on vivid colors if it gets plenty of nutrition and sunlight. The flower's aroma soothes the emotions of people.", "h": 20, "w": 1000, "dr": ["0-3x Melon Seeds", "1x Miracle Seed 25%"]}, "cobblemon:p0004_charmander": {"n": 4, "d": "The flame that burns at the tip of its tail is an indication of its emotions. The flame wavers when Charmander is enjoying itself. If the Pokémon becomes enraged, the flame burns fiercely.", "h": 6, "w": 85, "dr": ["0-1x Blaze Powder", "1x Charcoal Stick 5%"]}, "cobblemon:p0005_charmeleon": {"n": 5, "d": "Charmeleon mercilessly destroys its foes using its sharp claws. If it encounters a strong foe, it turns aggressive. In this excited state, the flame at the tip of its tail flares with a bluish white color.", "h": 11, "w": 190, "dr": ["0-2x Blaze Powder", "1x Charcoal Stick 10%"]}, "cobblemon:p0006_charizard": {"n": 6, "d": "Charizard flies around the sky in search of powerful opponents. It breathes fire of such great heat that it melts anything. However, it never turns its fiery breath on any opponent weaker than itself.", "h": 17, "w": 905, "dr": ["0-3x Blaze Powder", "1x Charcoal Stick 25%"]}, "cobblemon:p0007_squirtle": {"n": 7, "d": "Squirtle's shell is not merely used for protection. The shell's rounded shape and the grooves on its surface help minimize resistance in water, enabling this Pokémon to swim at high speeds.", "h": 5, "w": 90, "dr": ["0-1x Turtle Scute", "1x Mystic Water 5%"]}, "cobblemon:p0008_wartortle": {"n": 8, "d": "Its tail is large and covered with a rich, thick fur. The tail becomes increasingly deeper in color as Wartortle ages. The scratches on its shell are evidence of this Pokémon's toughness as a battler.", "h": 10, "w": 225, "dr": ["0-2x Turtle Scute", "1x Mystic Water 10%"]}, "cobblemon:p0009_blastoise": {"n": 9, "d": "Blastoise has water spouts that protrude from its shell. The water spouts are very accurate. They can shoot bullets of water with enough accuracy to strike empty cans from a distance of over 160 feet.", "h": 16, "w": 855, "dr": ["0-3x Turtle Scute", "1x Mystic Water 25%"]}, "cobblemon:p0010_caterpie": {"n": 10, "d": "Caterpie has a voracious appetite. It can devour leaves bigger than its body right before your eyes. From its antenna, this Pokémon releases a terrifically strong odor.", "h": 3, "w": 29, "dr": ["0-1x String", "1x Wepear Berry 2.5%"]}, "cobblemon:p0011_metapod": {"n": 11, "d": "The shell covering this Pokémon's body is as hard as an iron slab. Metapod does not move very much. It stays still because it is preparing its soft innards for evolution inside the hard shell.", "h": 7, "w": 99, "dr": ["0-2x String", "1x Wepear Berry 2.5%"]}, "cobblemon:p0012_butterfree": {"n": 12, "d": "Butterfree has a superior ability to search for delicious honey from flowers. It can even search out, extract, and carry honey from flowers that are blooming over six miles from its nest.", "h": 11, "w": 320, "dr": ["1x Silver Powder 5%", "1x Shed Shell 5%", "1x Wepear Berry 5%"]}, "cobblemon:p0013_weedle": {"n": 13, "d": "Weedle has an extremely acute sense of smell. It is capable of distinguishing its favorite kinds of leaves from those it dislikes just by sniffing with its big red proboscis (nose).", "h": 3, "w": 32, "dr": ["0-1x String", "1x Pinap Berry 2.5%"]}, "cobblemon:p0014_kakuna": {"n": 14, "d": "Kakuna remains virtually immobile as it clings to a tree. However, on the inside, it is extremely busy as it prepares for its coming evolution. This is evident from how hot the shell becomes to the touch.", "h": 6, "w": 100, "dr": ["0-2x String", "1x Pinap Berry 2.5%"]}, "cobblemon:p0015_beedrill": {"n": 15, "d": "Beedrill is extremely territorial. No one should ever approach its nest—this is for their own safety. If angered, they will attack in a furious swarm.", "h": 10, "w": 295, "dr": ["1x Poison Barb 5%", "1x Shed Shell 5%", "1x Pinap Berry 5%"]}, "cobblemon:p0016_pidgey": {"n": 16, "d": "Pidgey has an extremely sharp sense of direction. It is capable of unerringly returning home to its nest, however far it may be removed from its familiar surroundings.", "h": 3, "w": 18, "dr": ["0-1x Feather", "1x Chicken", "1x Chilan Berry 2.5%"]}, "cobblemon:p0017_pidgeotto": {"n": 17, "d": "Pidgeotto claims a large area as its own territory. This Pokémon flies around, patrolling its living space. If its territory is violated, it shows no mercy in thoroughly punishing the foe with its sharp claws.", "h": 11, "w": 300, "dr": ["0-2x Feather", "1x Chicken", "1x Sharp Beak 2.5%", "1x Chilan Berry 5%"]}, "cobblemon:p0018_pidgeot": {"n": 18, "d": "This Pokémon has a dazzling plumage of beautifully glossy feathers. Many Trainers are captivated by the striking beauty of the feathers on its head, compelling them to choose Pidgeot as their Pokémon.", "h": 15, "w": 395, "dr": ["0-3x Feather", "1x Chicken", "1x Sharp Beak 5%", "1x Chilan Berry 10%"]}, "cobblemon:p0019_rattata": {"n": 19, "d": "Rattata is cautious in the extreme. Even while it is asleep, it constantly listens by moving its ears around. It is not picky about where it lives—it will make its nest anywhere.", "h": 3, "w": 35, "dr": ["0-1x Rotten Flesh", "1x Chilan Berry 2.5%"]}, "cobblemon:p0020_raticate": {"n": 20, "d": "Raticate's sturdy fangs grow steadily. To keep them ground down, it gnaws on rocks and logs. It may even chew on the walls of houses.", "h": 7, "w": 185, "dr": ["0-2x Rotten Flesh", "1x Chilan Berry 5%"]}, "cobblemon:p0021_spearow": {"n": 21, "d": "Spearow has a very loud cry that can be heard over half a mile away. If its high, keening cry is heard echoing all around, it is a sign that they are warning each other of danger.", "h": 3, "w": 20, "dr": ["0-1x Feather", "1x Chicken", "1x Sharp Beak 2.5%", "1x Charti Berry 2.5%"]}, "cobblemon:p0022_fearow": {"n": 22, "d": "Fearow is recognized by its long neck and elongated beak. They are conveniently shaped for catching prey in soil or water. It deftly moves its long and skinny beak to pluck prey.", "h": 12, "w": 380, "dr": ["0-2x Feather", "1x Chicken", "1x Sharp Beak 5%", "1x Charti Berry 5%"]}, "cobblemon:p0023_ekans": {"n": 23, "d": "Ekans curls itself up in a spiral while it rests. Assuming this position allows it to quickly respond to a threat from any direction with a glare from its upraised head.", "h": 20, "w": 69, "dr": ["1x Razor Fang 2.5%"]}, "cobblemon:p0024_arbok": {"n": 24, "d": "This Pokémon is terrifically strong in order to constrict things with its body. It can even flatten steel oil drums. Once Arbok wraps its body around its foe, escaping its crunching embrace is impossible.", "h": 35, "w": 650, "dr": ["1x Razor Fang 5%"]}, "cobblemon:p0025_pikachu": {"n": 25, "d": "This Pokémon has electricity-storing pouches on its cheeks. These appear to become electrically charged during the night while Pikachu sleeps. It occasionally discharges electricity when it is dozy after waking up.", "h": 4, "w": 60, "dr": ["1x Light Ball 5%", "1x Thunder Stone 5%", "1x Oran Berry 5%"]}, "cobblemon:p0026_raichu": {"n": 26, "d": "This Pokémon exudes a weak electrical charge from all over its body that makes it take on a slight glow in darkness. Raichu plants its tail in the ground to discharge electricity.", "h": 8, "w": 300, "dr": ["1x Light Ball 10%", "1x Thunder Stone 10%", "1x Oran Berry 10%"]}, "cobblemon:p0027_sandshrew": {"n": 27, "d": "Sandshrew has a very dry hide that is extremely tough. The Pokémon can roll into a ball that repels any attack. At night, it burrows into the desert sand to sleep.", "h": 6, "w": 120, "dr": ["0-1x Armadillo Scute", "1x Grip Claw 2.5%", "1x Quick Claw 2.5%", "1x Soft Sand 2.5%"]}, "cobblemon:p0028_sandslash": {"n": 28, "d": "Sandslash can roll up its body as if it were a ball covered with large spikes. In battle, this Pokémon will try to make the foe flinch by jabbing it with its spines. It then leaps at the stunned foe to tear wildly with its sharp claws.", "h": 10, "w": 295, "dr": ["0-2x Armadillo Scute", "1x Grip Claw 5%", "1x Quick Claw 5%", "1x Soft Sand 5%"]}, "cobblemon:p0029_nidoranf": {"n": 29, "d": "Nidoran♀ has barbs that secrete a powerful poison. They are thought to have developed as protection for this small-bodied Pokémon. When enraged, it releases a horrible toxin from its horn.", "h": 4, "w": 70, "dr": ["1x Poison Barb 2.5%", "1x Pecha Berry 2.5%"]}, "cobblemon:p0030_nidorina": {"n": 30, "d": "When Nidorina are with their friends or family, they keep their barbs tucked away to prevent hurting each other. This Pokémon appears to become nervous if separated from the others.", "h": 8, "w": 200, "dr": ["1x Poison Barb 5%", "1x Pecha Berry 5%"]}, "cobblemon:p0031_nidoqueen": {"n": 31, "d": "Nidoqueen's body is encased in extremely hard scales. It is adept at sending foes flying with harsh tackles. This Pokémon is at its strongest when it is defending its young.", "h": 13, "w": 600, "dr": ["1x Poison Barb 10%", "1x Pecha Berry 10%"]}, "cobblemon:p0032_nidoranm": {"n": 32, "d": "Nidoran♂ has developed muscles for moving its ears. Thanks to them, the ears can be freely moved in any direction. Even the slightest sound does not escape this Pokémon's notice.", "h": 5, "w": 90, "dr": ["1x Poison Barb 2.5%", "1x Pecha Berry 2.5%"]}, "cobblemon:p0033_nidorino": {"n": 33, "d": "Nidorino has a horn that is harder than a diamond. If it senses a hostile presence, all the barbs on its back bristle up at once, and it challenges the foe with all its might.", "h": 9, "w": 195, "dr": ["1x Poison Barb 5%", "1x Pecha Berry 5%"]}, "cobblemon:p0034_nidoking": {"n": 34, "d": "Nidoking's thick tail packs enormously destructive power. With one swing, it can topple a metal transmission tower. Once this Pokémon goes on a rampage, there is no stopping it.", "h": 14, "w": 620, "dr": ["1x Poison Barb 10%", "1x Pecha Berry 10%"]}, "cobblemon:p0035_clefairy": {"n": 35, "d": "On every night of a full moon, groups of this Pokémon come out to play. When dawn arrives, the tired Clefairy return to their quiet mountain retreats and go to sleep nestled up against each other.", "h": 6, "w": 75, "dr": ["1x Moon Stone 5%", "1x Babiri Berry 5%", "1x Fairy Feather 5%"]}, "cobblemon:p0036_clefable": {"n": 36, "d": "Clefable moves by skipping lightly as if it were flying using its wings. Its bouncy step lets it even walk on water. It is known to take strolls on lakes on quiet, moonlit nights.", "h": 13, "w": 400, "dr": ["1x Moon Stone 10%", "1x Babiri Berry 10%", "1x Fairy Feather 10%"]}, "cobblemon:p0037_vulpix": {"n": 37, "d": "Inside Vulpix's body burns a flame that never goes out. During the daytime, when the temperatures rise, this Pokémon releases flames from its mouth to prevent its body from growing too hot.", "h": 6, "w": 99, "dr": ["1-3x Sweet Berries", "1x Charcoal 2.5%", "1x Rawst Berry 2.5%"]}, "cobblemon:p0038_ninetales": {"n": 38, "d": "Legend has it that Ninetales came into being when nine wizards possessing sacred powers merged into one. This Pokémon is highly intelligent—it can understand human speech.", "h": 11, "w": 199, "dr": ["2-4x Sweet Berries", "1x Charcoal 5%", "1x Rawst Berry 5%"]}, "cobblemon:p0039_jigglypuff": {"n": 39, "d": "When this Pokémon sings, it never pauses to breathe. If it is in a battle against an opponent that does not easily fall asleep, Jigglypuff cannot breathe, endangering its life.", "h": 5, "w": 55, "dr": ["1x Moon Stone 5%", "1x Air Balloon 5%", "1x Oran Berry 5%"]}, "cobblemon:p0040_wigglytuff": {"n": 40, "d": "Wigglytuff's body is very flexible. By inhaling deeply, this Pokémon can inflate itself seemingly without end. Once inflated, Wigglytuff bounces along lightly like a balloon.", "h": 10, "w": 120, "dr": ["1x Moon Stone 10%", "1x Air Balloon 10%", "1x Oran Berry 10%"]}, "cobblemon:p0041_zubat": {"n": 41, "d": "Zubat avoids sunlight because exposure causes it to become unhealthy. During the daytime, it stays in caves or under the eaves of old houses, sleeping while hanging upside down.", "h": 8, "w": 75, "dr": ["1x Phantom Membrane 2.5%", "1x Razor Fang 2.5%", "1x Persim Berry 2.5%"]}, "cobblemon:p0042_golbat": {"n": 42, "d": "Golbat bites down on prey with its four fangs and drinks the victim's blood. It becomes active on inky dark moonless nights, flying around to attack people and Pokémon.", "h": 16, "w": 550, "dr": ["1x Phantom Membrane 5%", "1x Razor Fang 5%", "1x Persim Berry 5%"]}, "cobblemon:p0043_oddish": {"n": 43, "d": "Oddish searches for fertile, nutrient-rich soil, then plants itself. During the daytime, while it is planted, this Pokémon's feet are thought to change shape and become similar to the roots of trees.", "h": 5, "w": 54, "dr": ["1x Absorb Bulb 2.5%", "1x Pecha Berry 2.5%"]}, "cobblemon:p0044_gloom": {"n": 44, "d": "From its mouth Gloom drips honey that smells absolutely horrible. Apparently, it loves the horrid stench. It sniffs the noxious fumes and then drools even more of its honey.", "h": 8, "w": 86, "dr": ["0-2x Honey Bottle", "1x Absorb Bulb 5%", "1x Pecha Berry 5%"]}, "cobblemon:p0045_vileplume": {"n": 45, "d": "Vileplume has the world's largest petals. They are used to attract prey that are then doused with toxic spores. Once the prey are immobilized, this Pokémon catches and devours them.", "h": 12, "w": 186, "dr": ["1x Absorb Bulb 10%", "1x Pecha Berry 10%"]}, "cobblemon:p0046_paras": {"n": 46, "d": "Paras has parasitic mushrooms growing on its back called tochukaso. They grow large by drawing nutrients from this Bug Pokémon host. They are highly valued as a medicine for extending life.", "h": 3, "w": 54, "dr": ["0-2x Red Mushroom", "1x Coba Berry 2.5%"]}, "cobblemon:p0047_parasect": {"n": 47, "d": "Parasect is known to infest large trees en masse and drain nutrients from the lower trunk and roots. When an infested tree dies, they move onto another tree all at once.", "h": 10, "w": 295, "dr": ["1x Red Mushroom", "1x Coba Berry 5%"]}, "cobblemon:p0048_venonat": {"n": 48, "d": "Venonat is said to have evolved with a coat of thin, stiff hair that covers its entire body for protection. It possesses large eyes that never fail to spot even minuscule prey.", "h": 10, "w": 300, "dr": ["0-1x String", "1x Persim Berry 2.5%"]}, "cobblemon:p0049_venomoth": {"n": 49, "d": "Venomoth is nocturnal—it is a Pokémon that only becomes active at night. Its favorite prey are small insects that gather around streetlights, attracted by the light in the darkness.", "h": 15, "w": 125, "dr": ["0-2x String", "1x Silver Powder 5%", "1x Shed Shell 5%", "1x Persim Berry 5%"]}, "cobblemon:p0050_diglett": {"n": 50, "d": "Diglett are raised in most farms. The reason is simple— wherever this Pokémon burrows, the soil is left perfectly tilled for planting crops. This soil is made ideal for growing delicious vegetables.", "h": 2, "w": 8, "dr": ["0-1x Dirt", "1x Potato 2.5%", "1x Big Root 2.5%", "1x Soft Sand 2.5%"]}, "cobblemon:p0051_dugtrio": {"n": 51, "d": "Dugtrio are actually triplets that emerged from one body. As a result, each triplet thinks exactly like the other two triplets. They work cooperatively to burrow endlessly.", "h": 7, "w": 333, "dr": ["0-2x Dirt", "1x Potato 5%", "1x Big Root 5%", "1x Soft Sand 5%"]}, "cobblemon:p0052_meowth": {"n": 52, "d": "Meowth withdraws its sharp claws into its paws to slinkily sneak about without making any incriminating footsteps. For some reason, this Pokémon loves shiny coins that glitter with light.", "h": 4, "w": 42, "dr": ["0-1x Gold Nugget", "1x Quick Claw 2.5%", "1x Pinap Berry 2.5%"]}, "cobblemon:p0053_persian": {"n": 53, "d": "Persian has six bold whiskers that give it a look of toughness. The whiskers sense air movements to determine what is in the Pokémon's surrounding vicinity. It becomes docile if grabbed by the whiskers.", "h": 10, "w": 320, "dr": ["0-2x Gold Nugget", "1x Quick Claw 5%", "1x Pinap Berry 5%"]}, "cobblemon:p0054_psyduck": {"n": 54, "d": "If it uses its mysterious power, Psyduck can't remember having done so. It apparently can't form a memory of such an event because it goes into an altered state that is much like deep sleep.", "h": 8, "w": 196, "dr": ["0-1x Feather", "1x Chicken", "1x Mystic Water 2.5%"]}, "cobblemon:p0055_golduck": {"n": 55, "d": "Golduck is the fastest swimmer among all Pokémon. It swims effortlessly, even in a rough, stormy sea. It sometimes rescues people from wrecked ships floundering in high seas.", "h": 17, "w": 766, "dr": ["0-2x Feather", "1x Chicken", "1x Mystic Water 5%"]}, "cobblemon:p0056_mankey": {"n": 56, "d": "When Mankey starts shaking and its nasal breathing turns rough, it's a sure sign that it is becoming angry. However, because it goes into a towering rage almost instantly, it is impossible for anyone to flee its wrath.", "h": 5, "w": 280, "dr": ["1x Muscle Band 2.5%", "1x Payapa Berry 2.5%"]}, "cobblemon:p0057_primeape": {"n": 57, "d": "When Primeape becomes furious, its blood circulation is boosted. In turn, its muscles are made even stronger. However, it also becomes much less intelligent at the same time.", "h": 10, "w": 320, "dr": ["1x Muscle Band 5%", "1x Payapa Berry 5%"]}, "cobblemon:p0058_growlithe": {"n": 58, "d": "Growlithe has a superb sense of smell. Once it smells anything, this Pokémon won't forget the scent, no matter what. It uses its advanced olfactory sense to determine the emotions of other living things.", "h": 7, "w": 190, "dr": ["0-1x Bone", "1x Rawst Berry 2.5%"]}, "cobblemon:p0059_arcanine": {"n": 59, "d": "Arcanine is known for its high speed. It is said to be capable of running over 6,200 miles in a single day and night. The fire that blazes wildly within this Pokémon's body is its source of power.", "h": 19, "w": 1550, "dr": ["0-2x Bone", "1x Rawst Berry 5%"]}, "cobblemon:p0060_poliwag": {"n": 60, "d": "Poliwag has a very thin skin. It is possible to see the Pokémon's spiral innards right through the skin. Despite its thinness, however, the skin is also very flexible. Even sharp fangs bounce right off it.", "h": 6, "w": 124, "dr": ["1x King's Rock 2.5%", "1x Chesto Berry 2.5%"]}, "cobblemon:p0061_poliwhirl": {"n": 61, "d": "The surface of Poliwhirl's body is always wet and slick with a slimy fluid. Because of this slippery covering, it can easily slip and slide out of the clutches of any enemy in battle.", "h": 10, "w": 200, "dr": ["1x King's Rock 5%", "1x Chesto Berry 5%"]}, "cobblemon:p0062_poliwrath": {"n": 62, "d": "Poliwrath's highly developed, brawny muscles never grow fatigued, however much it exercises. It is so tirelessly strong, this Pokémon can swim back and forth across the ocean without effort.", "h": 13, "w": 540, "dr": ["1x King's Rock 10%", "1x Chesto Berry 10%"]}, "cobblemon:p0063_abra": {"n": 63, "d": "Abra needs to sleep for eighteen hours a day. If it doesn't, this Pokémon loses its ability to use telekinetic powers. If it is attacked, Abra escapes using Teleport while it is still sleeping.", "h": 9, "w": 195, "dr": ["0-1x Ender Pearl", "1x Twisted Spoon 2.5%", "1x Kasib Berry 2.5%"]}, "cobblemon:p0064_kadabra": {"n": 64, "d": "Kadabra holds a silver spoon in its hand. The spoon is used to amplify the alpha waves in its brain. Without the spoon, the Pokémon is said to be limited to half the usual amount of its telekinetic powers.", "h": 13, "w": 565, "dr": ["0-2x Ender Pearl", "1x Twisted Spoon 5%", "1x Kasib Berry 5%"]}, "cobblemon:p0065_alakazam": {"n": 65, "d": "Alakazam's brain continually grows, infinitely multiplying brain cells. This amazing brain gives this Pokémon an astoundingly high IQ of 5,000. It has a thorough memory of everything that has occurred in the world.", "h": 15, "w": 480, "dr": ["0-3x Ender Pearl", "1x Twisted Spoon 10%", "1x Kasib Berry 10%"]}, "cobblemon:p0066_machop": {"n": 66, "d": "Machop exercises by hefting around a Graveler as if it were a barbell. There are some Machop that travel the world in a quest to master all kinds of martial arts.", "h": 8, "w": 195, "dr": ["1x Focus Band 2.5%", "1x Muscle Band 2.5%", "1x Wepear Berry 2.5%"]}, "cobblemon:p0067_machoke": {"n": 67, "d": "Machoke undertakes bodybuilding every day even as it helps people with tough, physically demanding labor. On its days off, this Pokémon heads to the fields and mountains to exercise and train.", "h": 15, "w": 705, "dr": ["1x Focus Band 5%", "1x Muscle Band 5%", "1x Wepear Berry 5%"]}, "cobblemon:p0068_machamp": {"n": 68, "d": "Machamp is known as the Pokémon that has mastered every kind of martial arts. If it grabs hold of the foe with its four arms, the battle is all but over. The hapless foe is thrown far over the horizon.", "h": 16, "w": 1300, "dr": ["1x Focus Band 10%", "1x Muscle Band 10%", "1x Wepear Berry 10%"]}, "cobblemon:p0069_bellsprout": {"n": 69, "d": "Bellsprout's thin and flexible body lets it bend and sway to avoid any attack, however strong it may be. From its mouth, this Pokémon spits a corrosive fluid that melts even iron.", "h": 7, "w": 40, "dr": ["1x Big Root 2.5%", "1x Pinap Berry 2.5%"]}, "cobblemon:p0070_weepinbell": {"n": 70, "d": "Weepinbell has a large hook on its rear end. At night, the Pokémon hooks on to a tree branch and goes to sleep. If it moves around in its sleep, it may wake up to find itself on the ground.", "h": 10, "w": 64, "dr": ["1x Big Root 5%", "1x Pinap Berry 5%"]}, "cobblemon:p0071_victreebel": {"n": 71, "d": "Victreebel has a long vine that extends from its head. This vine is waved and flicked about as if it were an animal to attract prey. When an unsuspecting prey draws near, this Pokémon swallows it whole.", "h": 17, "w": 155, "dr": ["1x Big Root 10%", "1x Pinap Berry 10%"]}, "cobblemon:p0072_tentacool": {"n": 72, "d": "Tentacool absorbs sunlight and refracts it using water inside its body to convert it into beam energy. This Pokémon shoots beams from the small round organ above its eyes.", "h": 9, "w": 455, "dr": ["1-3x Ink Sac", "1-3x Glow Ink Sac 10%", "1x Poison Barb 2.5%"]}, "cobblemon:p0073_tentacruel": {"n": 73, "d": "Tentacruel has tentacles that can be freely elongated and shortened at will. It ensnares prey with its tentacles and weakens the prey by dosing it with a harsh toxin. It can catch up to 80 prey at the same time.", "h": 16, "w": 550, "dr": ["2-4x Ink Sac", "2-4x Glow Ink Sac 10%", "1x Poison Barb 5%"]}, "cobblemon:p0074_geodude": {"n": 74, "d": "When Geodude sleeps deeply, it buries itself halfway into the ground. It will not awaken even if hikers step on it unwittingly. In the morning, this Pokémon rolls downhill in search of food.", "h": 4, "w": 200, "dr": ["0-1x Gravel", "1x Everstone 2.5%", "1x Black Augurite 2.5%", "1x Rindo Berry 2.5%"]}, "cobblemon:p0075_graveler": {"n": 75, "d": "Rocks are Graveler's favorite food. This Pokémon will climb a mountain from the base to the summit, crunchingly feasting on rocks all the while. Upon reaching the peak, it rolls back down to the bottom.", "h": 10, "w": 1050, "dr": ["0-2x Gravel", "1x Everstone 5%", "1x Black Augurite 5%", "1x Rindo Berry 5%"]}, "cobblemon:p0076_golem": {"n": 76, "d": "Golem is known for rolling down from mountains. To prevent them from rolling into the homes of people downhill, grooves have been dug into the sides of mountains to serve as guideways for diverting this Pokémon's course.", "h": 14, "w": 3000, "dr": ["0-3x Gravel", "1x Everstone 10%", "1x Black Augurite 10%", "1x Rindo Berry 10%"]}, "cobblemon:p0077_ponyta": {"n": 77, "d": "Ponyta is very weak at birth. It can barely stand up. This Pokémon becomes stronger by stumbling and falling to keep up with its parent.", "h": 10, "w": 300, "dr": ["0-1x Leather", "1x Blaze Powder 2.5%", "1x Shuca Berry 2.5%"]}, "cobblemon:p0078_rapidash": {"n": 78, "d": "Rapidash usually can be seen casually cantering in the fields and plains. However, when this Pokémon turns serious, its fiery manes flare and blaze as it gallops its way up to 150 mph.", "h": 17, "w": 950, "dr": ["0-2x Leather", "1x Blaze Powder 5%", "1x Shuca Berry 5%"]}, "cobblemon:p0079_slowpoke": {"n": 79, "d": "Slowpoke uses its tail to catch prey by dipping it in water at the side of a river. However, this Pokémon often forgets what it's doing and often spends entire days just loafing at water's edge.", "h": 12, "w": 360, "dr": ["1x King's Rock 2.5%", "1x Lagging Tail 2.5%", "1x Chesto Berry 2.5%"]}, "cobblemon:p0080_slowbro": {"n": 80, "d": "Slowbro's tail has a Shellder firmly attached with a bite. As a result, the tail can't be used for fishing anymore. This causes Slowbro to grudgingly swim and catch prey instead.", "h": 16, "w": 785, "dr": ["1x King's Rock 5%", "1x Lagging Tail 5%", "1x Chesto Berry 5%"]}, "cobblemon:p0081_magnemite": {"n": 81, "d": "Magnemite floats in the air by emitting electromagnetic waves from the units at its sides. These waves block gravity. This Pokémon becomes incapable of flight if its internal electrical supply is depleted.", "h": 3, "w": 60, "dr": ["0-1x Raw Iron", "1x Magnet 2.5%", "1x Metal Coat 2.5%", "1x Shuca Berry 2.5%"]}, "cobblemon:p0082_magneton": {"n": 82, "d": "Magneton emits a powerful magnetic force that is fatal to electronics and precision instruments. Because of this, it is said that some towns warn people to keep this Pokémon inside a Poké Ball.", "h": 10, "w": 600, "dr": ["0-2x Raw Iron", "1x Magnet 5%", "1x Metal Coat 5%", "1x Shuca Berry 5%"]}, "cobblemon:p0083_farfetchd": {"n": 83, "d": "Farfetch'd is always seen with a stalk from a plant of some sort. Apparently, there are good stalks and bad stalks. This Pokémon has been known to fight with others over stalks.", "h": 8, "w": 150, "dr": ["0-1x Feather", "1x Chicken", "0-1x Medicinal Leek", "1x Chilan Berry 5%"]}, "cobblemon:p0084_doduo": {"n": 84, "d": "Doduo's two heads contain completely identical brains. A scientific study reported that on rare occasions, there will be examples of this Pokémon possessing different sets of brains.", "h": 14, "w": 392, "dr": ["0-1x Feather", "1x Chicken", "1x Sharp Beak 2.5%", "1x Wacan Berry 2.5%"]}, "cobblemon:p0085_dodrio": {"n": 85, "d": "Apparently, the heads aren't the only parts of the body that Dodrio has three of. It has three sets of hearts and lungs as well, so it is capable of running long distances without rest.", "h": 18, "w": 852, "dr": ["0-2x Feather", "1x Chicken", "1x Sharp Beak 5%", "1x Wacan Berry 5%"]}, "cobblemon:p0086_seel": {"n": 86, "d": "Seel hunts for prey in the frigid sea underneath sheets of ice. When it needs to breathe, it punches a hole through the ice with the sharply protruding section of its head.", "h": 11, "w": 900, "dr": ["0-1x Cod", "1x Never-Melt Ice 2.5%", "1x Aspear Berry 2.5%"]}, "cobblemon:p0087_dewgong": {"n": 87, "d": "Dewgong loves to snooze on bitterly cold ice. The sight of this Pokémon sleeping on a glacier was mistakenly thought to be a mermaid by a mariner long ago.", "h": 17, "w": 1200, "dr": ["0-2x Cod", "1x Never-Melt Ice 5%", "1x Aspear Berry 5%"]}, "cobblemon:p0088_grimer": {"n": 88, "d": "Grimer emerged from the sludge that settled on a polluted seabed. This Pokémon loves anything filthy. It constantly leaks a horribly germ-infested fluid from all over its body.", "h": 9, "w": 300, "dr": ["0-1x Slime Ball", "1x Black Sludge 2.5%", "1x Toxic Orb 2.5%"]}, "cobblemon:p0089_muk": {"n": 89, "d": "This Pokémon's favorite food is anything that is repugnantly filthy. In dirty towns where people think nothing of throwing away litter on the streets, Muk are certain to gather.", "h": 12, "w": 300, "dr": ["0-2x Slime Ball", "1x Black Sludge 5%", "1x Toxic Orb 5%"]}, "cobblemon:p0090_shellder": {"n": 90, "d": "At night, this Pokémon uses its broad tongue to burrow a hole in the seafloor sand and then sleep in it. While it is sleeping, Shellder closes its shell, but leaves its tongue hanging out.", "h": 3, "w": 40, "dr": ["1x Aspear Berry 2.5%", "1x Shell Bell 2.5%"]}, "cobblemon:p0091_cloyster": {"n": 91, "d": "Cloyster is capable of swimming in the sea. It does so by swallowing water, then jetting it out toward the rear. This Pokémon shoots spikes from its shell using the same system.", "h": 15, "w": 1325, "dr": ["1x Aspear Berry 5%", "1x Shell Bell 5%"]}, "cobblemon:p0092_gastly": {"n": 92, "d": "Gastly is largely composed of gaseous matter. When exposed to a strong wind, the gaseous body quickly dwindles away. Groups of this Pokémon cluster under the eaves of houses to escape the ravages of wind.", "h": 13, "w": 1, "dr": ["1x Spell Tag 2.5%", "1x Payapa Berry 2.5%"]}, "cobblemon:p0093_haunter": {"n": 93, "d": "Haunter is a dangerous Pokémon. If one beckons you while floating in darkness, you must never approach it. This Pokémon will try to lick you with its tongue and steal your life away.", "h": 16, "w": 1, "dr": ["1x Spell Tag 5%", "1x Payapa Berry 5%"]}, "cobblemon:p0094_gengar": {"n": 94, "d": "Sometimes, on a dark night, your shadow thrown by a streetlight will suddenly and startlingly overtake you. It is actually a Gengar running past you, pretending to be your shadow.", "h": 15, "w": 405, "dr": ["1x Spell Tag 10%", "1x Payapa Berry 10%"]}, "cobblemon:p0095_onix": {"n": 95, "d": "Onix has a magnet in its brain. It acts as a compass so that this Pokémon does not lose direction while it is tunneling. As it grows older, its body becomes increasingly rounder and smoother.", "h": 88, "w": 2100, "dr": ["1-3x Stone", "1x Hard Stone 2.5%", "1x Lagging Tail 2.5%", "1x Passho Berry 2.5%"]}, "cobblemon:p0096_drowzee": {"n": 96, "d": "If your nose becomes itchy while you are sleeping, it's a sure sign that one of these Pokémon is standing above your pillow and trying to eat your dream through your nostrils.", "h": 10, "w": 324, "dr": ["1x Chesto Berry 2.5%"]}, "cobblemon:p0097_hypno": {"n": 97, "d": "Hypno holds a pendulum in its hand. The arcing movement and glitter of the pendulum lull the foe into a deep state of hypnosis. While this Pokémon searches for prey, it polishes the pendulum.", "h": 16, "w": 756, "dr": ["1x Chesto Berry 5%"]}, "cobblemon:p0098_krabby": {"n": 98, "d": "Krabby live on beaches, burrowed inside holes dug into the sand. On sandy beaches with little in the way of food, these Pokémon can be seen squabbling with each other over territory.", "h": 4, "w": 65, "dr": ["1x King's Rock 2.5%", "1x Pinap Berry 2.5%"]}, "cobblemon:p0099_kingler": {"n": 99, "d": "Kingler has an enormous, oversized claw. It waves this huge claw in the air to communicate with others. However, because the claw is so heavy, the Pokémon quickly tires.", "h": 13, "w": 600, "dr": ["1x King's Rock 5%", "1x Pinap Berry 5%"]}, "cobblemon:p0100_voltorb": {"n": 100, "d": "Voltorb is extremely sensitive—it explodes at the slightest of shocks. It is rumored that it was first created when a Poké Ball was exposed to a powerful pulse of energy.", "h": 5, "w": 104, "dr": ["0-1x Gunpowder"]}, "cobblemon:p0101_electrode": {"n": 101, "d": "One of Electrode's characteristics is its attraction to electricity. It is a problematical Pokémon that congregates mostly at electrical power plants to feed on electricity that has just been generated.", "h": 12, "w": 666, "dr": ["0-2x Gunpowder"]}, "cobblemon:p0102_exeggcute": {"n": 102, "d": "This Pokémon consists of six eggs that form a closely knit cluster. The six eggs attract each other and spin around. When cracks increasingly appear on the eggs, Exeggcute is close to evolution.", "h": 4, "w": 25, "dr": ["0-3x Egg", "1x Oval Stone 2.5%", "1x Psychic Seed 2.5%", "1x Tanga Berry 2.5%"]}, "cobblemon:p0103_exeggutor": {"n": 103, "d": "Exeggutor originally came from the tropics. Its heads steadily grow larger from exposure to strong sunlight. It is said that when the heads fall off, they group together to form Exeggcute.", "h": 20, "w": 1200, "dr": ["0-3x Egg", "1x Oval Stone 5%", "1x Psychic Seed 5%", "1x Tanga Berry 5%"]}, "cobblemon:p0104_cubone": {"n": 104, "d": "Cubone pines for the mother it will never see again. Seeing a likeness of its mother in the full moon, it cries. The stains on the skull the Pokémon wears are made by the tears it sheds.", "h": 4, "w": 65, "dr": ["0-1x Bone", "1x Nanab Berry 2.5%"]}, "cobblemon:p0105_marowak": {"n": 105, "d": "Marowak is the evolved form of a Cubone that has overcome its sadness at the loss of its mother and grown tough. This Pokémon's tempered and hardened spirit is not easily broken.", "h": 10, "w": 450, "dr": ["1x Bone", "1x Nanab Berry 5%"]}, "cobblemon:p0106_hitmonlee": {"n": 106, "d": "Hitmonlee's legs freely contract and stretch. Using these springlike legs, it bowls over foes with devastating kicks. After battle, it rubs down its legs and loosens the muscles to overcome fatigue.", "h": 15, "w": 498, "dr": ["1x Black Belt 5%", "1x Payapa Berry 5%"]}, "cobblemon:p0107_hitmonchan": {"n": 107, "d": "Hitmonchan is said to possess the spirit of a boxer who had been working toward a world championship. This Pokémon has an indomitable spirit and will never give up in the face of adversity.", "h": 14, "w": 502, "dr": ["1x Black Belt 5%", "1x Payapa Berry 5%"]}, "cobblemon:p0108_lickitung": {"n": 108, "d": "Whenever Lickitung comes across something new, it will unfailingly give it a lick. It does so because it memorizes things by texture and by taste. It is somewhat put off by sour things.", "h": 12, "w": 655, "dr": ["0-1x Slime Ball", "1x Lagging Tail 2.5%", "1x Oran Berry 2.5%"]}, "cobblemon:p0109_koffing": {"n": 109, "d": "Koffing embodies toxic substances. It mixes the toxins with raw garbage to set off a chemical reaction that results in a terribly powerful poison gas. The higher the temperature, the more gas is concocted by this Pokémon.", "h": 6, "w": 10, "dr": ["1x Black Sludge 2.5%", "1x Smoke Ball 2.5%"]}, "cobblemon:p0110_weezing": {"n": 110, "d": "Weezing alternately shrinks and inflates its twin bodies to mix together toxic gases inside. The more the gases are mixed, the more powerful the toxins become. The Pokémon also becomes more putrid.", "h": 12, "w": 95, "dr": ["1x Black Sludge 5%", "1x Smoke Ball 5%"]}, "cobblemon:p0111_rhyhorn": {"n": 111, "d": "Rhyhorn's brain is very small. It is so dense, while on a run it forgets why it started running in the first place. It apparently remembers sometimes if it demolishes something.", "h": 10, "w": 1150, "dr": ["1x Protector 2.5%", "1x Passho Berry 2.5%"]}, "cobblemon:p0112_rhydon": {"n": 112, "d": "Rhydon has a horn that serves as a drill. It is used for destroying rocks and boulders. This Pokémon occasionally rams into streams of magma, but the armor-like hide prevents it from feeling the heat.", "h": 19, "w": 1200, "dr": ["1x Protector 5%", "1x Passho Berry 5%"]}, "cobblemon:p0113_chansey": {"n": 113, "d": "Chansey lays nutritionally excellent eggs on an everyday basis. The eggs are so delicious, they are easily and eagerly devoured by even those people who have lost their appetite.", "h": 11, "w": 346, "dr": ["1x Lucky Egg 10%", "1x Oval Stone 10%", "1x Egg 50%"]}, "cobblemon:p0114_tangela": {"n": 114, "d": "Tangela's vines snap off easily if they are grabbed. This happens without pain, allowing it to make a quick getaway. The lost vines are replaced by newly grown vines the very next day.", "h": 10, "w": 350, "dr": ["0-1x Vine", "1x Big Root 2.5%"]}, "cobblemon:p0115_kangaskhan": {"n": 115, "d": "If you come across a young Kangaskhan playing by itself, you must never disturb it or attempt to catch it. The baby Pokémon's parent is sure to be in the area, and it will become violently enraged at you.", "h": 22, "w": 800, "dr": ["1x Chilan Berry 5%"]}, "cobblemon:p0116_horsea": {"n": 116, "d": "If Horsea senses danger, it will reflexively spray a dense black ink from its mouth and try to escape. This Pokémon swims by cleverly flapping the fin on its back.", "h": 4, "w": 80, "dr": ["0-1x Ink Sac", "0-1x Prismarine Shard", "1x Dragon Scale 2.5%"]}, "cobblemon:p0117_seadra": {"n": 117, "d": "Seadra generates whirlpools by spinning its body. The whirlpools are strong enough to swallow even fishing boats. This Pokémon weakens prey with these currents, then swallows it whole.", "h": 12, "w": 250, "dr": ["0-2x Ink Sac", "0-2x Prismarine Shard", "1x Dragon Scale 5%"]}, "cobblemon:p0118_goldeen": {"n": 118, "d": "Goldeen loves swimming wild and free in rivers and ponds. If one of these Pokémon is placed in an aquarium, it will shatter even the thickest glass with one ram of its horn and make its escape.", "h": 6, "w": 150, "dr": ["1x Salmon", "1x Bone Meal 5%", "1x Mystic Water 2.5%", "1x Wacan Berry 2.5%"]}, "cobblemon:p0119_seaking": {"n": 119, "d": "Seaking is very protective of its eggs. The male and female will take turns patrolling around their nest and eggs. The guarding of eggs by these Pokémon goes on for over a month.", "h": 13, "w": 390, "dr": ["1x Salmon", "1x Bone Meal 10%", "1x Mystic Water 5%", "1x Wacan Berry 5%"]}, "cobblemon:p0120_staryu": {"n": 120, "d": "Staryu apparently communicates with the stars in the night sky by flashing the red core at the center of its body. If parts of its body are torn, this Pokémon simply regenerates the missing pieces and limbs.", "h": 8, "w": 345, "dr": []}, "cobblemon:p0121_starmie": {"n": 121, "d": "Starmie swims through water by spinning its star-shaped body as if it were a propeller on a ship. The core at the center of this Pokémon's body glows in seven colors.", "h": 11, "w": 800, "dr": []}, "cobblemon:p0122_mrmime": {"n": 122, "d": "Mr. Mime is a master of pantomime. Its gestures and motions convince watchers that something unseeable actually exists. Once the watchers are convinced, the unseeable thing exists as if it were real.", "h": 13, "w": 545, "dr": ["1x Light Clay 5%", "1x Babiri Berry 5%"]}, "cobblemon:p0123_scyther": {"n": 123, "d": "Scyther is blindingly fast. Its blazing speed enhances the effectiveness of the twin scythes on its forearms. This Pokémon's scythes are so effective, they can slice through thick logs in one wicked stroke.", "h": 15, "w": 560, "dr": ["1x Wepear Berry 2.5%"]}, "cobblemon:p0124_jynx": {"n": 124, "d": "Jynx walks rhythmically, swaying and shaking its hips as if it were dancing. Its motions are so bouncingly alluring, people seeing it are compelled to shake their hips without giving any thought to what they are doing.", "h": 14, "w": 406, "dr": ["1x Aspear Berry 5%"]}, "cobblemon:p0125_electabuzz": {"n": 125, "d": "When a storm arrives, gangs of this Pokémon compete with each other to scale heights that are likely to be stricken by lightning bolts. Some towns use Electabuzz in place of lightning rods.", "h": 11, "w": 300, "dr": ["0-2x Redstone", "1x Electirizer 5%", "1x Cheri Berry 5%"]}, "cobblemon:p0126_magmar": {"n": 126, "d": "In battle, Magmar blows out intensely hot flames from all over its body to intimidate its opponent. This Pokémon's fiery bursts create heat waves that ignite grass and trees in its surroundings.", "h": 13, "w": 445, "dr": ["1x Blaze Powder 5%", "1x Magmarizer 5%", "1x Rawst Berry 5%"]}, "cobblemon:p0127_pinsir": {"n": 127, "d": "Pinsir has a pair of massive horns. Protruding from the surface of these horns are thorns. These thorns are driven deeply into the foe's body when the pincer closes, making it tough for the foe to escape.", "h": 15, "w": 550, "dr": ["1x Pinap Berry 5%"]}, "cobblemon:p0128_tauros": {"n": 128, "d": "This Pokémon is not satisfied unless it is rampaging at all times. If there is no opponent for Tauros to battle, it will charge at thick trees and knock them down to calm itself.", "h": 14, "w": 884, "dr": ["0-2x Leather", "1-3x Beef"]}, "cobblemon:p0129_magikarp": {"n": 129, "d": "Magikarp is virtually useless in battle as it can only splash around. As a result, it is considered to be weak. However, it is actually a very hardy Pokémon that can survive in any body of water no matter how polluted it is.", "h": 9, "w": 100, "dr": ["1x Salmon", "1x Bone Meal 5%", "1x Wacan Berry 2.5%"]}, "cobblemon:p0130_gyarados": {"n": 130, "d": "Once Gyarados goes on a rampage, its ferociously violent blood doesn't calm until it has burned everything down. There are records of this Pokémon's rampages lasting a whole month.", "h": 65, "w": 2350, "dr": ["1x Salmon", "1x Bone Meal 10%", "1x Wacan Berry 5%"]}, "cobblemon:p0131_lapras": {"n": 131, "d": "People have driven Lapras almost to the point of extinction. In the evenings, this Pokémon is said to sing plaintively as it seeks what few others of its kind still remain.", "h": 25, "w": 2200, "dr": ["1x Mystic Water 5%", "1x Never-Melt Ice 5%", "1x Heart Of The Sea 5%", "1x Aspear Berry 5%"]}, "cobblemon:p0132_ditto": {"n": 132, "d": "Ditto rearranges its cell structure to transform itself into other shapes. However, if it tries to transform itself into something by relying on its memory, this Pokémon manages to get details wrong.", "h": 3, "w": 40, "dr": ["0-1x Quick Powder", "1x Metal Powder 5%"]}, "cobblemon:p0133_eevee": {"n": 133, "d": "Eevee has an unstable genetic makeup that suddenly mutates due to the environment in which it lives. Radiation from various stones causes this Pokémon to evolve.", "h": 3, "w": 65, "dr": ["1x Silk Scarf 5%", "1x Eviolite 5%"]}, "cobblemon:p0134_vaporeon": {"n": 134, "d": "Vaporeon underwent a spontaneous mutation and grew fins and gills that allow it to live underwater. This Pokémon has the ability to freely control water.", "h": 10, "w": 290, "dr": ["1x Water Stone 25%", "1x Mystic Water 10%"]}, "cobblemon:p0135_jolteon": {"n": 135, "d": "Jolteon's cells generate a low level of electricity. This power is amplified by the static electricity of its fur, enabling the Pokémon to drop thunderbolts. The bristling fur is made of electrically charged needles.", "h": 8, "w": 245, "dr": ["1x Thunder Stone 25%", "1x Magnet 10%"]}, "cobblemon:p0136_flareon": {"n": 136, "d": "Flareon's fluffy fur has a functional purpose—it releases heat into the air so that its body does not get excessively hot. This Pokémon's body temperature can rise to a maximum of 1,650 degrees Fahrenheit.", "h": 9, "w": 250, "dr": ["1x Fire Stone 25%", "1x Charcoal Stick 10%"]}, "cobblemon:p0137_porygon": {"n": 137, "d": "Porygon is capable of reverting itself entirely back to program data and entering cyberspace. This Pokémon is copy protected so it cannot be duplicated by copying.", "h": 8, "w": 365, "dr": []}, "cobblemon:p0138_omanyte": {"n": 138, "d": "Omanyte is one of the ancient and long-since-extinct Pokémon that have been regenerated from fossils by people. If attacked by an enemy, it withdraws itself inside its hard shell.", "h": 4, "w": 75, "dr": ["1x Nautilus Shell", "1x Bone Meal 5%"]}, "cobblemon:p0139_omastar": {"n": 139, "d": "Omastar uses its tentacles to capture its prey. It is believed to have become extinct because its shell grew too large and heavy, causing its movements to become too slow and ponderous.", "h": 10, "w": 350, "dr": ["1x Nautilus Shell", "1x Bone Meal 10%"]}, "cobblemon:p0140_kabuto": {"n": 140, "d": "Kabuto is a Pokémon that has been regenerated from a fossil. However, in extremely rare cases, living examples have been discovered. The Pokémon has not changed at all for 300 million years.", "h": 5, "w": 115, "dr": ["1x Razor Claw 5%", "1x Bone Meal 5%"]}, "cobblemon:p0141_kabutops": {"n": 141, "d": "Kabutops swam underwater to hunt for its prey in ancient times. The Pokémon was apparently evolving from being a water dweller to living on land as evident from the beginnings of change in its gills and legs.", "h": 13, "w": 405, "dr": ["1x Razor Claw 10%", "1x Bone Meal 10%"]}, "cobblemon:p0142_aerodactyl": {"n": 142, "d": "Aerodactyl is a Pokémon from the age of dinosaurs. It was regenerated from genetic material extracted from amber. It is imagined to have been the king of the skies in ancient times.", "h": 18, "w": 590, "dr": ["0-3x Bone", "1x Rocky Helmet 10%"]}, "cobblemon:p0143_snorlax": {"n": 143, "d": "Snorlax's typical day consists of nothing more than eating and sleeping. It is such a docile Pokémon that there are children who use its expansive belly as a place to play.", "h": 21, "w": 4600, "dr": ["0-3x Apple", "0-3x Apple", "1x Chesto Berry 5%", "1x Leftovers 5%"]}, "cobblemon:p0144_articuno": {"n": 144, "d": "Articuno is a legendary bird Pokémon that can control ice. The flapping of its wings chills the air. As a result, it is said that when this Pokémon flies, snow will fall.", "h": 17, "w": 554, "dr": ["2-4x Feather", "1x Chicken", "1x Never-Melt Ice"]}, "cobblemon:p0145_zapdos": {"n": 145, "d": "Zapdos is a legendary bird Pokémon that has the ability to control electricity. It usually lives in thunderclouds. The Pokémon gains power if it is stricken by lightning bolts.", "h": 16, "w": 526, "dr": ["2-4x Feather", "1x Chicken", "1x Magnet"]}, "cobblemon:p0146_moltres": {"n": 146, "d": "Moltres is a legendary bird Pokémon that has the ability to control fire. If this Pokémon is injured, it is said to dip its body in the molten magma of a volcano to burn and heal itself.", "h": 20, "w": 600, "dr": ["2-4x Feather", "1x Cooked Chicken", "1x Charcoal Stick"]}, "cobblemon:p0147_dratini": {"n": 147, "d": "Dratini continually molts and sloughs off its old skin. It does so because the life energy within its body steadily builds to reach uncontrollable levels.", "h": 18, "w": 33, "dr": ["0-1x Dragon Breath", "1x Dragon Fang 2.5%", "1x Dragon Scale 2.5%", "1x Yache Berry 2.5%"]}, "cobblemon:p0148_dragonair": {"n": 148, "d": "Dragonair stores an enormous amount of energy inside its body. It is said to alter weather conditions in its vicinity by discharging energy from the crystals on its neck and tail.", "h": 40, "w": 165, "dr": ["0-2x Dragon Breath", "1x Dragon Fang 5%", "1x Dragon Scale 5%", "1x Yache Berry 5%"]}, "cobblemon:p0149_dragonite": {"n": 149, "d": "Dragonite is capable of circling the globe in just 16 hours. It is a kindhearted Pokémon that leads lost and foundering ships in a storm to the safety of land.", "h": 22, "w": 2100, "dr": ["0-3x Dragon Breath", "1x Dragon Fang 10%", "1x Dragon Scale 10%", "1x Yache Berry 10%"]}, "cobblemon:p0150_mewtwo": {"n": 150, "d": "Mewtwo is a Pokémon that was created by genetic manipulation. However, even though the scientific power of humans created this Pokémon's body, they failed to endow Mewtwo with a compassionate heart.", "h": 20, "w": 1220, "dr": ["1x Twisted Spoon"]}, "cobblemon:p0151_mew": {"n": 151, "d": "Mew is said to possess the genetic composition of all Pokémon. It is capable of making itself invisible at will, so it entirely avoids notice even if it approaches people.", "h": 4, "w": 40, "dr": []}, "cobblemon:p0152_chikorita": {"n": 152, "d": "In battle, Chikorita waves its leaf around to keep the foe at bay. However, a sweet fragrance also wafts from the leaf, becalming the battling Pokémon and creating a cozy, friendly atmosphere all around.", "h": 9, "w": 64, "dr": ["1x Miracle Seed 5%"]}, "cobblemon:p0153_bayleef": {"n": 153, "d": "Bayleef's neck is ringed by curled-up leaves. Inside each tubular leaf is a small shoot of a tree. The fragrance of this shoot makes people peppy.", "h": 12, "w": 158, "dr": ["1x Miracle Seed 10%"]}, "cobblemon:p0154_meganium": {"n": 154, "d": "The fragrance of Meganium's flower soothes and calms emotions. In battle, this Pokémon gives off more of its becalming scent to blunt the foe's fighting spirit.", "h": 18, "w": 1005, "dr": ["1x Miracle Seed 25%"]}, "cobblemon:p0155_cyndaquil": {"n": 155, "d": "Cyndaquil protects itself by flaring up the flames on its back. The flames are vigorous if the Pokémon is angry. However, if it is tired, the flames splutter fitfully with incomplete combustion.", "h": 5, "w": 79, "dr": ["1x Charcoal Stick 5%"]}, "cobblemon:p0156_quilava": {"n": 156, "d": "Quilava keeps its foes at bay with the intensity of its flames and gusts of superheated air. This Pokémon applies its outstanding nimbleness to dodge attacks even while scorching the foe with flames.", "h": 9, "w": 190, "dr": ["1x Charcoal Stick 10%"]}, "cobblemon:p0157_typhlosion": {"n": 157, "d": "Typhlosion obscures itself behind a shimmering heat haze that it creates using its intensely hot flames. This Pokémon creates blazing explosive blasts that burn everything to cinders.", "h": 17, "w": 795, "dr": ["1x Charcoal Stick 25%"]}, "cobblemon:p0158_totodile": {"n": 158, "d": "Despite the smallness of its body, Totodile's jaws are very powerful. While the Pokémon may think it is just playfully nipping, its bite has enough power to cause serious injury.", "h": 6, "w": 95, "dr": ["1x Mystic Water 5%"]}, "cobblemon:p0159_croconaw": {"n": 159, "d": "Once Croconaw has clamped its jaws on its foe, it will absolutely not let go. Because the tips of its fangs are forked back like barbed fishhooks, they become impossible to remove when they have sunk in.", "h": 11, "w": 250, "dr": ["1x Mystic Water 10%"]}, "cobblemon:p0160_feraligatr": {"n": 160, "d": "Feraligatr intimidates its foes by opening its huge mouth. In battle, it will kick the ground hard with its thick and powerful hind legs to charge at the foe at an incredible speed.", "h": 23, "w": 888, "dr": ["1x Mystic Water 25%"]}, "cobblemon:p0161_sentret": {"n": 161, "d": "When Sentret sleeps, it does so while another stands guard. The sentry wakes the others at the first sign of danger. When this Pokémon becomes separated from its pack, it becomes incapable of sleep due to fear.", "h": 8, "w": 60, "dr": ["1x Silk Scarf 2.5%", "1x Oran Berry 2.5%"]}, "cobblemon:p0162_furret": {"n": 162, "d": "Furret has a very slim build. When under attack, it can slickly squirm through narrow spaces and get away. In spite of its short limbs, this Pokémon is very nimble and fleet.", "h": 18, "w": 325, "dr": ["1x Silk Scarf 5%", "1x Oran Berry 5%"]}, "cobblemon:p0163_hoothoot": {"n": 163, "d": "Hoothoot has an internal organ that senses and tracks the earth's rotation. Using this special organ, this Pokémon begins hooting at precisely the same time every day.", "h": 7, "w": 212, "dr": ["0-1x Feather", "1x Chicken", "1x Wise Glasses 2.5%", "1x Chilan Berry 2.5%"]}, "cobblemon:p0164_noctowl": {"n": 164, "d": "Noctowl never fails at catching prey in darkness. This Pokémon owes its success to its superior vision that allows it to see in minimal light, and to its soft, supple wings that make no sound in flight.", "h": 16, "w": 408, "dr": ["0-2x Feather", "1x Chicken", "1x Wise Glasses 5%", "1x Chilan Berry 5%"]}, "cobblemon:p0165_ledyba": {"n": 165, "d": "Ledyba secretes an aromatic fluid from where its legs join its body. This fluid is used for communicating with others. This Pokémon conveys its feelings to others by altering the fluid's scent.", "h": 10, "w": 108, "dr": ["1x Charti Berry 2.5%"]}, "cobblemon:p0166_ledian": {"n": 166, "d": "It is said that in lands with clean air, where the stars fill the sky, there live Ledian in countless numbers. There is a good reason for this—the Pokémon uses the light of the stars as its energy.", "h": 14, "w": 356, "dr": ["1x Charti Berry 5%"]}, "cobblemon:p0167_spinarak": {"n": 167, "d": "The web spun by Spinarak can be considered its second nervous system. It is said that this Pokémon can determine what kind of prey is touching its web just by the tiny vibrations it feels through the web's strands.", "h": 5, "w": 85, "dr": ["0-1x String", "0-1x Spider Eye", "0-1x Rotten Flesh", "1x Poison Barb 2.5%"]}, "cobblemon:p0168_ariados": {"n": 168, "d": "Ariados's feet are tipped with tiny hooked claws that enable it to scuttle on ceilings and vertical walls. This Pokémon constricts the foe with thin and strong silk webbing.", "h": 11, "w": 335, "dr": ["0-2x String", "0-2x Spider Eye", "0-2x Rotten Flesh", "1x Poison Barb 5%"]}, "cobblemon:p0169_crobat": {"n": 169, "d": "Crobat sneaks up on its intended prey using wings that barely make a sound. This Pokémon rests by hanging on a tree branch with its rear legs that serve as wings.", "h": 18, "w": 750, "dr": ["1x Phantom Membrane 10%", "1x Razor Fang 10%", "1x Persim Berry 10%"]}, "cobblemon:p0170_chinchou": {"n": 170, "d": "Chinchou's two antennas are filled with cells that generate strong electricity. This Pokémon's cells create so much electrical power, it even makes itself tingle slightly.", "h": 5, "w": 120, "dr": ["0-1x Prismarine Crystals", "1x Deep Sea Scale 2.5%", "1x Persim Berry 2.5%"]}, "cobblemon:p0171_lanturn": {"n": 171, "d": "Lanturn is known to emit light. If you peer down into the dark sea from a ship at night, you can sometimes see this Pokémon's light rising from the depths where it swims. It gives the sea an appearance of a starlit night.", "h": 12, "w": 225, "dr": ["0-2x Prismarine Crystals", "1x Deep Sea Scale 5%", "1x Persim Berry 5%"]}, "cobblemon:p0172_pichu": {"n": 172, "d": "When Pichu plays with others, it may short out electricity with another Pichu, creating a shower of sparks. In that event, this Pokémon will begin crying, startled by the flash of sparks.", "h": 3, "w": 20, "dr": ["1x Light Ball 2.5%", "1x Thunder Stone 2.5%", "1x Oran Berry 2.5%"]}, "cobblemon:p0173_cleffa": {"n": 173, "d": "On nights with many shooting stars, Cleffa can be seen dancing in a ring. They dance through the night and stop only at the break of day, when these Pokémon quench their thirst with the morning dew.", "h": 3, "w": 30, "dr": ["1x Moon Stone 2.5%", "1x Babiri Berry 2.5%", "1x Fairy Feather 2.5%"]}, "cobblemon:p0174_igglybuff": {"n": 174, "d": "Igglybuff has a soft and plushy body that feels very much like a marshmallow. From this body wafts a gently sweet fragrance that soothes and calms the emotions of its foes.", "h": 3, "w": 10, "dr": ["1x Moon Stone 2.5%", "1x Air Balloon 2.5%", "1x Oran Berry 2.5%"]}, "cobblemon:p0175_togepi": {"n": 175, "d": "As its energy, Togepi uses the positive emotions of compassion and pleasure exuded by people and Pokémon. This Pokémon stores up feelings of happiness inside its shell, then shares them with others.", "h": 3, "w": 15, "dr": ["1x Lucky Egg 2.5%", "1x Shiny Stone 2.5%", "1x Fairy Feather 2.5%"]}, "cobblemon:p0176_togetic": {"n": 176, "d": "Togetic is said to be a Pokémon that brings good fortune. When the Pokémon spots someone who is pure of heart, it is said to appear and share its happiness with that person.", "h": 6, "w": 32, "dr": ["1x Lucky Egg 5%", "1x Shiny Stone 5%", "1x Fairy Feather 5%"]}, "cobblemon:p0177_natu": {"n": 177, "d": "Natu has a highly developed jumping ability. The Pokémon flaps and leaps onto tree branches that are taller than grown-up people to pick at the tree's new shoots.", "h": 2, "w": 20, "dr": ["0-1x Feather", "1x Chicken", "1x Wise Glasses 2.5%", "1x Persim Berry 2.5%"]}, "cobblemon:p0178_xatu": {"n": 178, "d": "Xatu is known to stand motionless while staring at the sun all day long. Some people revere it as a mystical Pokémon out of their belief that Xatu is in possession of the power to see into the future.", "h": 15, "w": 150, "dr": ["0-2x Feather", "1x Chicken", "1x Wise Glasses 5%", "1x Persim Berry 5%"]}, "cobblemon:p0179_mareep": {"n": 179, "d": "Mareep's fluffy coat of wool rubs together and builds a static charge. The more static electricity is charged, the more brightly the lightbulb at the tip of its tail glows.", "h": 6, "w": 78, "dr": ["1-2x Mutton", "1-2x White Wool", "1x Cheri Berry 2.5%"]}, "cobblemon:p0180_flaaffy": {"n": 180, "d": "Flaaffy's wool quality changes so that it can generate a high amount of static electricity with a small amount of wool. The bare and slick parts of its hide are shielded against electricity.", "h": 8, "w": 133, "dr": ["1-3x Mutton", "1x White Wool", "1x Cheri Berry 5%"]}, "cobblemon:p0181_ampharos": {"n": 181, "d": "Ampharos gives off so much light that it can be seen even from space. People in the old days used the light of this Pokémon to send signals back and forth with others far away.", "h": 14, "w": 615, "dr": ["2-4x Mutton", "1x Cheri Berry 10%"]}, "cobblemon:p0182_bellossom": {"n": 182, "d": "A Bellossom grows flowers more beautifully if it has evolved from a smelly Gloom—the more stinky the better. At night, this Pokémon closes its petals and goes to sleep.", "h": 4, "w": 58, "dr": ["1x Absorb Bulb 10%", "1x Pecha Berry 10%"]}, "cobblemon:p0183_marill": {"n": 183, "d": "When fishing for food at the edge of a fast-running stream, Marill wraps its tail around the trunk of a tree. This Pokémon's tail is flexible and configured to stretch.", "h": 4, "w": 85, "dr": ["1x Kebia Berry 5%"]}, "cobblemon:p0184_azumarill": {"n": 184, "d": "Azumarill can make balloons out of air. It makes these air balloons if it spots a drowning Pokémon. The air balloons enable the Pokémon in trouble to breathe.", "h": 8, "w": 285, "dr": ["1x Kebia Berry 10%"]}, "cobblemon:p0185_sudowoodo": {"n": 185, "d": "Sudowoodo camouflages itself as a tree to avoid being attacked by enemies. However, because its hands remain green throughout the year, the Pokémon is easily identified as a fake during the winter.", "h": 12, "w": 380, "dr": ["1x Hard Stone 5%", "1x Passho Berry 5%"]}, "cobblemon:p0186_politoed": {"n": 186, "d": "The curled hair on Politoed's head is proof of its status as a king. It is said that the longer and more curled the hair, the more respect this Pokémon earns from its peers.", "h": 11, "w": 339, "dr": ["1x Verdant Froglight", "1x King's Rock 10%", "1x Chesto Berry 10%"]}, "cobblemon:p0187_hoppip": {"n": 187, "d": "This Pokémon drifts and floats with the wind. If it senses the approach of strong winds, Hoppip links its leaves with other Hoppip to prepare against being blown away.", "h": 4, "w": 5, "dr": ["1x Yache Berry 2.5%"]}, "cobblemon:p0188_skiploom": {"n": 188, "d": "Skiploom's flower blossoms when the temperature rises above 64 degrees Fahrenheit. How much the flower opens depends on the temperature. For that reason, this Pokémon is sometimes used as a thermometer.", "h": 6, "w": 10, "dr": ["1x Dandelion", "1x Yache Berry 5%"]}, "cobblemon:p0189_jumpluff": {"n": 189, "d": "Jumpluff rides warm southern winds to cross the sea and fly to foreign lands. The Pokémon descends to the ground when it encounters cold air while it is floating.", "h": 8, "w": 30, "dr": ["1-3x White Wool", "1x Yache Berry 10%"]}, "cobblemon:p0190_aipom": {"n": 190, "d": "Aipom's tail ends in a hand-like appendage that can be cleverly manipulated. However, because the Pokémon uses its tail so much, its real hands have become rather clumsy.", "h": 8, "w": 115, "dr": ["1x Nanab Berry 2.5%"]}, "cobblemon:p0191_sunkern": {"n": 191, "d": "Sunkern tries to move as little as it possibly can. It does so because it tries to conserve all the nutrients it has stored in its body for its evolution. It will not eat a thing, subsisting only on morning dew.", "h": 3, "w": 18, "dr": ["1x Wheat Seeds", "1x Coba Berry 2.5%"]}, "cobblemon:p0192_sunflora": {"n": 192, "d": "Sunflora converts solar energy into nutrition. It moves around actively in the daytime when it is warm. It stops moving as soon as the sun goes down for the night.", "h": 8, "w": 85, "dr": ["1x Sunflower", "1x Coba Berry 5%"]}, "cobblemon:p0193_yanma": {"n": 193, "d": "Yanma is capable of seeing 360 degrees without having to move its eyes. It is a great flier that is adept at making sudden stops and turning midair. This Pokémon uses its flying ability to quickly chase down targeted prey.", "h": 12, "w": 380, "dr": ["1x Wide Lens 2.5%", "1x Charti Berry 2.5%"]}, "cobblemon:p0194_wooper": {"n": 194, "d": "Wooper usually lives in water. However, it occasionally comes out onto land in search of food. On land, it coats its body with a gooey, toxic film.", "h": 4, "w": 85, "dr": ["0-1x Clay Ball", "1x Rindo Berry 2.5%"]}, "cobblemon:p0195_quagsire": {"n": 195, "d": "Quagsire hunts for food by leaving its mouth wide open in water and waiting for its prey to blunder in unaware. Because the Pokémon does not move, it does not get very hungry.", "h": 14, "w": 750, "dr": ["0-2x Clay Ball", "1x Rindo Berry 5%"]}, "cobblemon:p0196_espeon": {"n": 196, "d": "Espeon is extremely loyal to any Trainer it considers to be worthy. It is said that this Pokémon developed its precognitive powers to protect its Trainer from harm.", "h": 9, "w": 265, "dr": ["1x Sun Stone 25%", "1x Twisted Spoon 10%"]}, "cobblemon:p0197_umbreon": {"n": 197, "d": "Umbreon evolved as a result of exposure to the moon's waves. It hides silently in darkness and waits for its foes to make a move. The rings on its body glow when it leaps to attack.", "h": 10, "w": 270, "dr": ["1x Moon Stone 25%", "1x Black Glasses 10%"]}, "cobblemon:p0198_murkrow": {"n": 198, "d": "Murkrow was feared and loathed as the alleged bearer of ill fortune. This Pokémon shows strong interest in anything that sparkles or glitters. It will even try to steal rings from women.", "h": 5, "w": 21, "dr": ["0-1x Feather", "1x Chicken", "1x Bluk Berry 2.5%"]}, "cobblemon:p0199_slowking": {"n": 199, "d": "Slowking undertakes research every day in an effort to solve the mysteries of the world. However, this Pokémon apparently forgets everything it has learned if the Shellder on its head comes off.", "h": 20, "w": 795, "dr": ["1x King's Rock 10%", "1x Lagging Tail 10%", "1x Chesto Berry 10%"]}, "cobblemon:p0200_misdreavus": {"n": 200, "d": "Misdreavus frightens people with a creepy, sobbing cry. The Pokémon apparently uses its red spheres to absorb the fearful feelings of foes and turn them into nutrition.", "h": 7, "w": 10, "dr": ["1x Phantom Membrane 2.5%", "1x Spell Tag 2.5%", "1x Kasib Berry 2.5%"]}, "cobblemon:p0201_unown": {"n": 201, "d": "This Pokémon is shaped like ancient writing. It is a mystery as to which came first, the ancient writings or the various Unown. Research into this topic is ongoing but nothing is known.", "h": 5, "w": 50, "dr": ["0-1x Ender Pearl"]}, "cobblemon:p0202_wobbuffet": {"n": 202, "d": "Wobbuffet does nothing but endure attacks—it won't attack on its own. However, it won't endure an attack on its tail. When that happens, the Pokémon will try to take the foe with it using Destiny Bond.", "h": 13, "w": 285, "dr": ["1x Colbur Berry 5%"]}, "cobblemon:p0203_girafarig": {"n": 203, "d": "Girafarig's rear head contains a tiny brain that is too small for thinking. However, the rear head doesn't need to sleep, so it can keep watch over its surroundings 24 hours a day.", "h": 15, "w": 415, "dr": ["0-1x Leather", "1x Razor Fang 2.5%", "1x Persim Berry 2.5%"]}, "cobblemon:p0204_pineco": {"n": 204, "d": "Pineco hangs from a tree branch and patiently waits for prey to come along. If the Pokémon is disturbed while eating by someone shaking its tree, it drops down to the ground and explodes with no warning.", "h": 6, "w": 72, "dr": ["0-1x String", "1x Occa Berry 2.5%", "1x Iron Ball 2.5%"]}, "cobblemon:p0205_forretress": {"n": 205, "d": "Forretress conceals itself inside its hardened steel shell. The shell is opened when the Pokémon is catching prey, but it does so at such a quick pace that the shell's inside cannot be seen.", "h": 12, "w": 1258, "dr": ["0-2x String", "1x Occa Berry 5%", "1x Iron Ball 5%"]}, "cobblemon:p0206_dunsparce": {"n": 206, "d": "Dunsparce has a drill for its tail. It uses this tail to burrow into the ground backward. This Pokémon is known to make its nest in complex shapes deep under the ground.", "h": 15, "w": 140, "dr": ["1x Rocky Helmet 2.5%", "1x Cheri Berry 2.5%"]}, "cobblemon:p0207_gligar": {"n": 207, "d": "Gligar glides through the air without a sound as if it were sliding. This Pokémon hangs on to the face of its foe using its clawed hind legs and the large pincers on its forelegs, then injects the prey with its poison barb.", "h": 11, "w": 648, "dr": ["1x Phantom Membrane 2.5%", "1x Razor Fang 2.5%", "1x Poison Barb 2.5%", "1x Yache Berry 2.5%"]}, "cobblemon:p0208_steelix": {"n": 208, "d": "Steelix lives even further underground than Onix. This Pokémon is known to dig toward the earth's core. There are records of this Pokémon reaching a depth of over six-tenths of a mile underground.", "h": 92, "w": 4000, "dr": ["2-4x Raw Iron", "1x Lagging Tail 5%", "1x Metal Coat 5%", "1x Passho Berry 5%"]}, "cobblemon:p0209_snubbull": {"n": 209, "d": "By baring its fangs and making a scary face, Snubbull sends smaller Pokémon scurrying away in terror. However, this Pokémon seems a little sad at making its foes flee.", "h": 6, "w": 78, "dr": ["0-1x Bone", "1x Babiri Berry 2.5%"]}, "cobblemon:p0210_granbull": {"n": 210, "d": "Granbull has a particularly well-developed lower jaw. The enormous fangs are heavy, causing the Pokémon to tip its head back for balance. Unless it is startled, it will not try to bite indiscriminately.", "h": 14, "w": 487, "dr": ["0-2x Bone", "1x Babiri Berry 5%"]}, "cobblemon:p0211_qwilfish": {"n": 211, "d": "Qwilfish sucks in water, inflating itself. This Pokémon uses the pressure of the water it swallowed to shoot toxic quills all at once from all over its body. It finds swimming somewhat challenging.", "h": 5, "w": 39, "dr": ["1x Pufferfish", "0-1x Prismarine Shard", "1x Poison Barb 2.5%"]}, "cobblemon:p0212_scizor": {"n": 212, "d": "Scizor has a body with the hardness of steel. It is not easily fazed by ordinary sorts of attacks. This Pokémon flaps its wings to regulate its body temperature.", "h": 18, "w": 1180, "dr": ["1x Wepear Berry 5%"]}, "cobblemon:p0213_shuckle": {"n": 213, "d": "Shuckle quietly hides itself under rocks, keeping its body concealed inside its hard shell while eating berries it has stored away. The berries mix with its body fluids to become a juice.", "h": 6, "w": 205, "dr": ["1x Berry Juice", "1x Luminous Moss 5%"]}, "cobblemon:p0214_heracross": {"n": 214, "d": "Heracross has sharp claws on its feet. These are planted firmly into the ground or the bark of a tree, giving the Pokémon a secure and solid footing to forcefully fling away foes with its proud horn.", "h": 15, "w": 540, "dr": ["1x Coba Berry 5%"]}, "cobblemon:p0215_sneasel": {"n": 215, "d": "Sneasel scales trees by punching its hooked claws into the bark. This Pokémon seeks out unguarded nests and steals eggs for food while the parents are away.", "h": 9, "w": 280, "dr": ["1x Razor Claw 2.5%", "1x Grip Claw 2.5%", "1x Quick Claw 2.5%", "1x Chople Berry 2.5%"]}, "cobblemon:p0216_teddiursa": {"n": 216, "d": "This Pokémon likes to lick its palms that are sweetened by being soaked in honey. Teddiursa concocts its own honey by blending fruits and pollen collected by Beedrill.", "h": 6, "w": 88, "dr": ["1-3x Sweet Berries", "1x Honey Bottle 2.5%", "1x Peat Block 2.5%", "1x Oran Berry 2.5%"]}, "cobblemon:p0217_ursaring": {"n": 217, "d": "In the forests inhabited by Ursaring, it is said that there are many streams and towering trees where they gather food. This Pokémon walks through its forest gathering food every day.", "h": 18, "w": 1258, "dr": ["2-4x Sweet Berries", "1x Honey Bottle 5%", "1x Peat Block 5%", "1x Oran Berry 5%"]}, "cobblemon:p0218_slugma": {"n": 218, "d": "Slugma does not have any blood in its body. Instead, intensely hot magma circulates throughout this Pokémon's body, carrying essential nutrients and oxygen to its organs.", "h": 7, "w": 350, "dr": ["0-1x Magma Cream", "1x Passho Berry 2.5%"]}, "cobblemon:p0219_magcargo": {"n": 219, "d": "Magcargo's body temperature is approximately 18,000 degrees Fahrenheit. Water is vaporized on contact. If this Pokémon is caught in the rain, the raindrops instantly turn into steam, cloaking the area in a thick fog.", "h": 8, "w": 550, "dr": ["0-2x Magma Cream", "1x Basalt", "1x Passho Berry 5%"]}, "cobblemon:p0220_swinub": {"n": 220, "d": "Swinub roots for food by rubbing its snout against the ground. Its favorite food is a mushroom that grows under the cover of dead grass. This Pokémon occasionally roots out hot springs.", "h": 4, "w": 65, "dr": ["1x Porkchop", "1x Brown Wool", "1x Never-Melt Ice 2.5%", "1x Aspear Berry 2.5%"]}, "cobblemon:p0221_piloswine": {"n": 221, "d": "Piloswine is covered by a thick coat of long hair that enables it to endure the freezing cold. This Pokémon uses its tusks to dig up food that has been buried under ice.", "h": 11, "w": 558, "dr": ["1-2x Porkchop", "1-2x Brown Wool", "1x Never-Melt Ice 5%", "1x Aspear Berry 5%"]}, "cobblemon:p0222_corsola": {"n": 222, "d": "Clusters of Corsola congregate in warm seas where they serve as ideal hiding places for smaller Pokémon. When the water temperature falls, this Pokémon migrates to the southern seas.", "h": 6, "w": 50, "dr": ["1x Luminous Moss 5%", "1x Rindo Berry 5%"]}, "cobblemon:p0223_remoraid": {"n": 223, "d": "Remoraid sucks in water, then expels it at high velocity using its abdominal muscles to shoot down flying prey. When evolution draws near, this Pokémon travels downstream from rivers.", "h": 6, "w": 120, "dr": ["1x Cod", "1x Bone Meal 5%", "1x Aspear Berry 2.5%"]}, "cobblemon:p0224_octillery": {"n": 224, "d": "Octillery grabs onto its foe using its tentacles. This Pokémon tries to immobilize it before delivering the finishing blow. If the foe turns out to be too strong, Octillery spews ink to escape.", "h": 9, "w": 285, "dr": ["1-3x Ink Sac", "1x Aspear Berry 5%"]}, "cobblemon:p0225_delibird": {"n": 225, "d": "Delibird carries its food bundled up in its tail. There once was a famous explorer who managed to reach the peak of the world's highest mountain, thanks to one of these Pokémon sharing its food.", "h": 9, "w": 160, "dr": ["0-2x Feather", "1x Chicken", "1x Charti Berry 5%"]}, "cobblemon:p0226_mantine": {"n": 226, "d": "On sunny days, schools of Mantine can be seen elegantly leaping over the sea's waves. This Pokémon is not bothered by the Remoraid that hitches rides.", "h": 21, "w": 2200, "dr": ["0-2x Cod", "1x Wacan Berry 5%"]}, "cobblemon:p0227_skarmory": {"n": 227, "d": "Skarmory's steel wings become tattered and bashed in from repeated battles. Once a year, the battered wings grow back completely, restoring the cutting edges to their pristine state.", "h": 17, "w": 505, "dr": ["1x Sharp Beak 5%", "1x Metal Coat 5%", "1x Pinap Berry 5%"]}, "cobblemon:p0228_houndour": {"n": 228, "d": "Houndour hunt as a coordinated pack. They communicate with each other using a variety of cries to corner their prey. This Pokémon's remarkable teamwork is unparalleled.", "h": 6, "w": 108, "dr": ["0-1x Bone", "0-1x Rotten Flesh", "1x Blaze Powder 2.5%", "1x Rawst Berry 2.5%"]}, "cobblemon:p0229_houndoom": {"n": 229, "d": "In a Houndoom pack, the one with its horns raked sharply toward the back serves a leadership role. These Pokémon choose their leader by fighting among themselves.", "h": 14, "w": 350, "dr": ["0-2x Bone", "0-2x Rotten Flesh", "1x Blaze Powder 5%", "1x Rawst Berry 5%"]}, "cobblemon:p0230_kingdra": {"n": 230, "d": "Kingdra sleeps on the seafloor where it is otherwise devoid of life. When a storm arrives, the Pokémon is said to awaken and wander about in search of prey.", "h": 18, "w": 1520, "dr": ["0-3x Ink Sac", "0-3x Prismarine Shard", "1x Dragon Scale 10%"]}, "cobblemon:p0231_phanpy": {"n": 231, "d": "Phanpy uses its long nose to shower itself. When others gather around, they thoroughly douse each other with water. These Pokémon can be seen drying their soaking-wet bodies at the edge of water.", "h": 5, "w": 335, "dr": ["0-1x Clay Ball", "1x Passho Berry 2.5%"]}, "cobblemon:p0232_donphan": {"n": 232, "d": "If Donphan were to tackle with its hard body, even a house could be destroyed. Using its massive strength, the Pokémon helps clear rock and mud slides that block mountain trails.", "h": 11, "w": 1200, "dr": ["0-2x Clay Ball", "1x Protector 5%", "1x Passho Berry 5%"]}, "cobblemon:p0233_porygon2": {"n": 233, "d": "Porygon2 was created by humans using the power of science. The man-made Pokémon has been endowed with artificial intelligence that enables it to learn new gestures and emotions on its own.", "h": 6, "w": 325, "dr": ["1x Upgrade 25%"]}, "cobblemon:p0234_stantler": {"n": 234, "d": "Stantler's magnificent antlers were traded at high prices as works of art. As a result, this Pokémon was hunted close to extinction by those who were after the priceless antlers.", "h": 14, "w": 712, "dr": ["0-1x Leather", "1x Persim Berry 2.5%"]}, "cobblemon:p0235_smeargle": {"n": 235, "d": "Smeargle marks the boundaries of its territory using a body fluid that leaks out from the tip of its tail. Over 5,000 different marks left by this Pokémon have been found.", "h": 12, "w": 580, "dr": []}, "cobblemon:p0236_tyrogue": {"n": 236, "d": "Tyrogue becomes stressed out if it does not get to train every day. When raising this Pokémon, the Trainer must establish and uphold various training methods.", "h": 7, "w": 210, "dr": ["1x Black Belt 2.5%", "1x Payapa Berry 2.5%"]}, "cobblemon:p0237_hitmontop": {"n": 237, "d": "Hitmontop spins on its head at high speed, all the while delivering kicks. This technique is a remarkable mix of both offense and defense at the same time. The Pokémon travels faster spinning than it does walking.", "h": 14, "w": 480, "dr": ["1x Black Belt 5%", "1x Payapa Berry 5%"]}, "cobblemon:p0238_smoochum": {"n": 238, "d": "Smoochum actively runs about, but also falls quite often. Whenever the chance arrives, it will look for its reflection to make sure its face hasn't become dirty.", "h": 4, "w": 60, "dr": ["1x Aspear Berry 2.5%"]}, "cobblemon:p0239_elekid": {"n": 239, "d": "Elekid stores electricity in its body. If it touches metal and accidentally discharges all its built-up electricity, this Pokémon begins swinging its arms in circles to recharge itself.", "h": 6, "w": 235, "dr": ["0-1x Redstone", "1x Electirizer 2.5%", "1x Cheri Berry 2.5%"]}, "cobblemon:p0240_magby": {"n": 240, "d": "Magby's state of health is determined by observing the fire it breathes. If the Pokémon is spouting yellow flames from its mouth, it is in good health. When it is fatigued, black smoke will be mixed in with the flames.", "h": 7, "w": 214, "dr": ["1x Blaze Powder 2.5%", "1x Magmarizer 2.5%", "1x Rawst Berry 2.5%"]}, "cobblemon:p0241_miltank": {"n": 241, "d": "Miltank gives over five gallons of milk on a daily basis. Its sweet milk is enjoyed by children and grown-ups alike. People who can't drink milk turn it into yogurt and eat it instead.", "h": 12, "w": 755, "dr": ["0-2x Leather", "1-3x Beef", "1x Oran Berry 5%"]}, "cobblemon:p0242_blissey": {"n": 242, "d": "Blissey senses sadness with its fluffy coat of fur. If it does so, this Pokémon will rush over to a sad person, no matter how far away, to share a Lucky Egg that brings a smile to any face.", "h": 15, "w": 468, "dr": ["1x Lucky Egg 25%", "1x Oval Stone 25%", "1x Egg 50%"]}, "cobblemon:p0246_larvitar": {"n": 246, "d": "Larvitar is born deep under the ground. To come up to the surface, this Pokémon must eat its way through the soil above. Until it does so, Larvitar cannot see its parents.", "h": 6, "w": 720, "dr": ["1x Hard Stone 2.5%", "1x Chople Berry 2.5%"]}, "cobblemon:p0247_pupitar": {"n": 247, "d": "Pupitar creates a gas inside its body that it compresses and forcefully ejects to propel itself like a jet. The body is very durable—it avoids damage even if it hits solid steel.", "h": 12, "w": 1520, "dr": ["1x Hard Stone 5%", "1x Chople Berry 5%"]}, "cobblemon:p0248_tyranitar": {"n": 248, "d": "Tyranitar is so overwhelmingly powerful, it can bring down a whole mountain to make its nest. This Pokémon wanders about in mountains seeking new opponents to fight.", "h": 20, "w": 2020, "dr": ["1x Hard Stone 10%", "1x Chople Berry 10%"]}, "cobblemon:p0249_lugia": {"n": 249, "d": "Lugia's wings pack devastating power—a light fluttering of its wings can blow apart regular houses. As a result, this Pokémon chooses to live out of sight deep under the sea.", "h": 52, "w": 2160, "dr": ["2-4x Feather"]}, "cobblemon:p0250_hooh": {"n": 250, "d": "Ho-Oh's feathers glow in seven colors depending on the angle at which they are struck by light. These feathers are said to bring happiness to the bearers. This Pokémon is said to live at the foot of a rainbow.", "h": 38, "w": 1990, "dr": ["2-4x Feather", "1x Sacred Ash"]}, "cobblemon:p0252_treecko": {"n": 252, "d": "Treecko is cool, calm, and collected—it never panics under any situation. If a bigger foe were to glare at this Pokémon, it would glare right back without conceding an inch of ground.", "h": 5, "w": 50, "dr": ["0-1x Stick", "1x Miracle Seed 5%"]}, "cobblemon:p0253_grovyle": {"n": 253, "d": "This Pokémon adeptly flies from branch to branch in trees. In a forest, no Pokémon can ever hope to catch a fleeing Grovyle however fast they may be.", "h": 9, "w": 216, "dr": ["0-2x Stick", "1x Miracle Seed 10%"]}, "cobblemon:p0254_sceptile": {"n": 254, "d": "Sceptile has seeds growing on its back. They are said to be bursting with nutrients that revitalize trees. This Pokémon raises the trees in a forest with loving care.", "h": 17, "w": 522, "dr": ["0-3x Stick", "1x Miracle Seed 25%"]}, "cobblemon:p0255_torchic": {"n": 255, "d": "Torchic has a place inside its body where it keeps its flame. Give it a hug—it will be glowing with warmth. This Pokémon is covered all over by a fluffy coat of down.", "h": 4, "w": 25, "dr": ["0-1x Feather", "1x Chicken", "1x Charcoal Stick 5%"]}, "cobblemon:p0256_combusken": {"n": 256, "d": "Combusken battles with the intensely hot flames it spews from its beak and with outstandingly destructive kicks. This Pokémon's cry is very loud and distracting.", "h": 9, "w": 195, "dr": ["0-2x Feather", "1x Chicken", "1x Charcoal Stick 10%"]}, "cobblemon:p0257_blaziken": {"n": 257, "d": "Blaziken has incredibly strong legs—it can easily clear a 30-story building in one leap. This Pokémon's blazing punches leave its foes scorched and blackened.", "h": 19, "w": 520, "dr": ["0-3x Feather", "1x Chicken", "1x Charcoal Stick 25%"]}, "cobblemon:p0258_mudkip": {"n": 258, "d": "In water, Mudkip breathes using the gills on its cheeks. If it is faced with a tight situation in battle, this Pokémon will unleash its amazing power—it can crush rocks bigger than itself.", "h": 4, "w": 76, "dr": ["0-1x Clay Ball", "1x Mystic Water 5%"]}, "cobblemon:p0259_marshtomp": {"n": 259, "d": "Marshtomp is much faster at traveling through mud than it is at swimming. This Pokémon's hindquarters exhibit obvious development, giving it the ability to walk on just its hind legs.", "h": 7, "w": 280, "dr": ["0-2x Clay Ball", "1x Mystic Water 10%"]}, "cobblemon:p0260_swampert": {"n": 260, "d": "Swampert predicts storms by sensing subtle differences in the sounds of waves and tidal winds with its fins. If a storm is approaching, it piles up boulders to protect itself.", "h": 15, "w": 819, "dr": ["0-3x Clay Ball", "1x Mystic Water 25%"]}, "cobblemon:p0261_poochyena": {"n": 261, "d": "Poochyena is an omnivore—it will eat anything. A distinguishing feature is how large its fangs are compared to its body. This Pokémon tries to intimidate its foes by making the hair on its tail bristle out.", "h": 5, "w": 136, "dr": ["0-1x Bone", "0-1x Rotten Flesh", "1x Pecha Berry 2.5%"]}, "cobblemon:p0262_mightyena": {"n": 262, "d": "Mightyena travel and act as a pack in the wild. The memory of its life in the wild compels the Pokémon to obey only those Trainers that it recognizes to possess superior skill.", "h": 10, "w": 370, "dr": ["0-2x Bone", "0-2x Rotten Flesh", "1x Pecha Berry 5%"]}, "cobblemon:p0263_zigzagoon": {"n": 263, "d": "The hair on Zigzagoon's back is bristly. It rubs the hard back hair against trees to leave its territorial markings. This Pokémon may play dead to fool foes in battle.", "h": 4, "w": 175, "dr": ["1x Oran Berry 2.5%"]}, "cobblemon:p0264_linoone": {"n": 264, "d": "When hunting, Linoone will make a beeline straight for the prey at a full run. While this Pokémon is capable of topping 60 mph, it has to come to a screeching halt before it can turn.", "h": 5, "w": 325, "dr": ["1x Oran Berry 5%"]}, "cobblemon:p0265_wurmple": {"n": 265, "d": "Wurmple is targeted by Swellow as prey. This Pokémon will try to resist by pointing the spikes on its rear at the attacking predator. It will weaken the foe by leaking poison from the spikes.", "h": 3, "w": 36, "dr": ["0-1x String", "1x Pecha Berry 2.5%"]}, "cobblemon:p0266_silcoon": {"n": 266, "d": "Silcoon was thought to endure hunger and not consume anything before its evolution. However, it is now thought that this Pokémon slakes its thirst by drinking rainwater that collects on its silk.", "h": 6, "w": 100, "dr": ["0-2x String", "1x Pecha Berry 2.5%"]}, "cobblemon:p0267_beautifly": {"n": 267, "d": "Beautifly has a long mouth like a coiled needle, which is very convenient for collecting pollen from flowers. This Pokémon rides the spring winds as it flits around gathering pollen.", "h": 10, "w": 284, "dr": ["1x Bright Powder 5%", "1x Shed Shell 5%", "1x Pecha Berry 5%"]}, "cobblemon:p0268_cascoon": {"n": 268, "d": "If it is attacked, Cascoon remains motionless however badly it may be hurt. It does so because if it were to move, its body would be weak upon evolution. This Pokémon will also not forget the pain it endured.", "h": 7, "w": 115, "dr": ["0-2x String", "1x Pecha Berry 2.5%"]}, "cobblemon:p0269_dustox": {"n": 269, "d": "When Dustox flaps its wings, a fine dust is scattered all over. This dust is actually a powerful poison that will even make a pro wrestler sick. This Pokémon searches for food using its antennae like radar.", "h": 12, "w": 316, "dr": ["1x Silver Powder 5%", "1x Shed Shell 5%", "1x Pecha Berry 5%"]}, "cobblemon:p0270_lotad": {"n": 270, "d": "Lotad is said to have dwelled on land before. However, this Pokémon is thought to have returned to water because the leaf on its head grew large and heavy. It now lives by floating atop the water.", "h": 5, "w": 26, "dr": ["0-1x Lily Pad", "1x Mental Herb 2.5%", "1x Kebia Berry 2.5%"]}, "cobblemon:p0271_lombre": {"n": 271, "d": "Lombre's entire body is covered by a slippery, slimy film. It feels horribly unpleasant to be touched by this Pokémon's hands. Lombre is often mistaken for a human child.", "h": 12, "w": 325, "dr": ["0-2x Lily Pad", "1x Mental Herb 5%", "1x Kebia Berry 5%"]}, "cobblemon:p0272_ludicolo": {"n": 272, "d": "Upon hearing an upbeat and cheerful rhythm, the cells in Ludicolo's body become very energetic and active. Even in battle, this Pokémon will exhibit an amazing amount of power.", "h": 15, "w": 550, "dr": ["0-3x Lily Pad", "1x Mental Herb 10%", "1x Kebia Berry 10%"]}, "cobblemon:p0273_seedot": {"n": 273, "d": "Seedot looks exactly like an acorn when it is dangling from a tree branch. It startles other Pokémon by suddenly moving. This Pokémon polishes its body once a day using leaves.", "h": 5, "w": 40, "dr": ["0-1x Dark Oak Sapling", "1x Tanga Berry 2.5%"]}, "cobblemon:p0274_nuzleaf": {"n": 274, "d": "This Pokémon pulls out the leaf on its head and makes a flute with it. The sound of Nuzleaf's flute strikes fear and uncertainty in the hearts of people lost in a forest.", "h": 10, "w": 280, "dr": ["0-2x Dark Oak Sapling", "1x Tanga Berry 5%"]}, "cobblemon:p0275_shiftry": {"n": 275, "d": "Shiftry's large fans generate awesome gusts of wind at a speed close to 100 feet per second. The whipped-up wind blows anything away. This Pokémon chooses to live quietly deep in forests.", "h": 13, "w": 596, "dr": ["0-3x Dark Oak Sapling", "1x Tanga Berry 10%"]}, "cobblemon:p0276_taillow": {"n": 276, "d": "Taillow is young—it has only just left its nest. As a result, it sometimes becomes lonesome and cries at night. This Pokémon feeds on Wurmple that live in forests.", "h": 3, "w": 23, "dr": ["0-1x Feather", "1x Chicken", "1x Charti Berry 2.5%"]}, "cobblemon:p0277_swellow": {"n": 277, "d": "Swellow is very conscientious about the upkeep of its glossy wings. Once two Swellow are gathered, they diligently take care of cleaning each other's wings.", "h": 7, "w": 198, "dr": ["0-2x Feather", "1x Chicken", "1x Sharp Beak 2.5%", "1x Charti Berry 5%"]}, "cobblemon:p0278_wingull": {"n": 278, "d": "Wingull rides updrafts rising from the sea by extending its long and narrow wings to glide. This Pokémon's long beak is useful for catching prey.", "h": 6, "w": 95, "dr": ["0-1x Feather", "1x Chicken", "1x Wacan Berry 2.5%"]}, "cobblemon:p0279_pelipper": {"n": 279, "d": "Pelipper searches for food while in flight by skimming the wave tops. This Pokémon dips its large bill in the sea to scoop up food, then swallows everything in one big gulp.", "h": 12, "w": 280, "dr": ["0-2x Feather", "1x Chicken", "1x Wacan Berry 5%"]}, "cobblemon:p0280_ralts": {"n": 280, "d": "Ralts has the ability to sense the emotions of people. If its Trainer is in a cheerful mood, this Pokémon grows cheerful and joyous in the same way.", "h": 4, "w": 66, "dr": ["0-1x Ender Pearl", "1x Dawn Stone 2.5%", "1x Twisted Spoon 2.5%", "1x Kasib Berry 2.5%"]}, "cobblemon:p0281_kirlia": {"n": 281, "d": "Kirlia uses the horns on its head to amplify its psychokinetic power. When the Pokémon uses its power, the air around it becomes distorted, creating mirages of nonexistent scenery.", "h": 8, "w": 202, "dr": ["0-2x Ender Pearl", "1x Dawn Stone 5%", "1x Twisted Spoon 5%", "1x Kasib Berry 5%"]}, "cobblemon:p0282_gardevoir": {"n": 282, "d": "Gardevoir has the psychokinetic power to distort the dimensions and create a small black hole. This Pokémon will try to protect its Trainer even at the risk of its own life.", "h": 16, "w": 484, "dr": ["0-3x Ender Pearl", "1x Dawn Stone 10%", "1x Twisted Spoon 10%", "1x Kasib Berry 10%"]}, "cobblemon:p0283_surskit": {"n": 283, "d": "If Surskit senses danger, it secretes a thick, sugary syrup from the tip of its head. There are some Pokémon that love eating this syrup.", "h": 5, "w": 17, "dr": ["0-1x Honey Bottle", "1x Wacan Berry 2.5%"]}, "cobblemon:p0284_masquerain": {"n": 284, "d": "Masquerain's antennas have eyelike patterns that usually give it an angry look. If the \"eyes\" are droopy and appear sad, it is said to be a sign that a heavy rainfall is on its way.", "h": 8, "w": 36, "dr": ["1x Silver Powder 5%", "1x Wacan Berry 5%"]}, "cobblemon:p0285_shroomish": {"n": 285, "d": "If Shroomish senses danger, it shakes its body and scatters spores from the top of its head. This Pokémon's spores are so toxic, they make trees and weeds wilt.", "h": 4, "w": 45, "dr": ["0-1x Brown Mushroom", "1x Kebia Berry 2.5%"]}, "cobblemon:p0286_breloom": {"n": 286, "d": "The seeds ringing Breloom's tail are made of hardened toxic spores. It is horrible to eat the seeds. Just taking a bite of this Pokémon's seed will cause your stomach to rumble.", "h": 12, "w": 392, "dr": ["0-2x Brown Mushroom", "1x Kebia Berry 5%"]}, "cobblemon:p0287_slakoth": {"n": 287, "d": "Slakoth's heart beats just once a minute. Whatever happens, it is content to loaf around motionless. It is rare to see this Pokémon in motion.", "h": 8, "w": 240, "dr": ["1x Chesto Berry 2.5%"]}, "cobblemon:p0288_vigoroth": {"n": 288, "d": "Vigoroth is simply incapable of remaining still. Even when it tries to sleep, the blood in its veins grows agitated, compelling this Pokémon to run wild throughout the jungle before it can settle down.", "h": 14, "w": 465, "dr": ["1x Chesto Berry 5%"]}, "cobblemon:p0289_slaking": {"n": 289, "d": "Wherever Slaking live, rings of over a yard in diameter appear in grassy fields. They are made by the Pokémon as it eats all the grass within reach while lying prone on the ground.", "h": 20, "w": 1305, "dr": ["1x Chesto Berry 10%"]}, "cobblemon:p0290_nincada": {"n": 290, "d": "Nincada lives underground. It uses its sharp claws to carve the roots of trees and absorb moisture and nutrients. This Pokémon can't withstand bright sunlight so avoids it.", "h": 5, "w": 55, "dr": ["1x Soft Sand 2.5%"]}, "cobblemon:p0291_ninjask": {"n": 291, "d": "If Ninjask is not trained properly, it will refuse to obey the Trainer and cry loudly continuously. Because of this quality, this Pokémon is said to be one that puts the Trainer's abilities to the test.", "h": 8, "w": 120, "dr": ["1x Shed Shell 5%"]}, "cobblemon:p0292_shedinja": {"n": 292, "d": "Shedinja is a peculiar Pokémon. It seems to appear unsought in a Poké Ball after a Nincada evolves. This bizarre Pokémon is entirely immobile—it doesn't even breathe.", "h": 8, "w": 12, "dr": ["1x Shed Shell 5%"]}, "cobblemon:p0293_whismur": {"n": 293, "d": "Whismur is very timid. If it starts to cry loudly, it becomes startled by its own crying and cries even harder. When it finally stops crying, the Pokémon goes to sleep, all tired out.", "h": 6, "w": 163, "dr": ["1x Throat Spray 2.5%", "1x Chesto Berry 2.5%"]}, "cobblemon:p0294_loudred": {"n": 294, "d": "Loudred shouts while stamping its feet. After it finishes shouting, this Pokémon becomes incapable of hearing anything for a while. This is considered to be a weak point.", "h": 10, "w": 405, "dr": ["1x Throat Spray 5%", "1x Chesto Berry 5%"]}, "cobblemon:p0295_exploud": {"n": 295, "d": "Exploud communicates its feelings to the others by emitting whistle-like sounds from the tubes on its body. This Pokémon only raises its voice when it is in battle.", "h": 15, "w": 840, "dr": ["1x Throat Spray 10%", "1x Chesto Berry 10%"]}, "cobblemon:p0296_makuhita": {"n": 296, "d": "Makuhita has a tireless spirit—it will never give up hope. It eats a lot of food, gets plenty of sleep, and it trains very rigorously. By living that way, this Pokémon packs its body with energy.", "h": 10, "w": 864, "dr": ["1x Black Belt 2.5%", "1x King's Rock 2.5%", "1x Payapa Berry 2.5%"]}, "cobblemon:p0297_hariyama": {"n": 297, "d": "Hariyama's thick body may appear fat, but it is actually a hunk of solid muscle. If this Pokémon bears down and tightens all its muscles, its body becomes as hard as a rock.", "h": 23, "w": 2538, "dr": ["1x Black Belt 5%", "1x King's Rock 5%", "1x Payapa Berry 5%"]}, "cobblemon:p0298_azurill": {"n": 298, "d": "Azurill's tail is large and bouncy. It is packed full of the nutrients this Pokémon needs to grow. Azurill can be seen bouncing and playing on its big, rubbery tail.", "h": 2, "w": 20, "dr": ["1x Kebia Berry 2.5%"]}, "cobblemon:p0299_nosepass": {"n": 299, "d": "Nosepass had been said to be completely unmoving, with its magnetic nose pointed due north. However, close observation has revealed that the Pokémon actually moves by a little over 3/8 of an inch every year.", "h": 10, "w": 970, "dr": ["0-1x Flint", "1x Hard Stone 2.5%", "1x Magnet 2.5%", "1x Chople Berry 2.5%"]}, "cobblemon:p0300_skitty": {"n": 300, "d": "Skitty is known to chase around playfully after its own tail. In the wild, this Pokémon lives in holes in the trees of forests. It is very popular as a pet because of its adorable looks.", "h": 6, "w": 110, "dr": ["1x Silk Scarf 2.5%", "1x Pecha Berry 2.5%"]}, "cobblemon:p0301_delcatty": {"n": 301, "d": "Delcatty sleeps anywhere it wants without keeping a permanent nest. If other Pokémon approach it as it sleeps, this Pokémon will never fight—it will just move away somewhere else.", "h": 11, "w": 326, "dr": ["1x Silk Scarf 5%", "1x Pecha Berry 5%"]}, "cobblemon:p0302_sableye": {"n": 302, "d": "Sableye digs the ground with sharpened claws to find rocks that it eats. Substances in the eaten rocks crystallize and rise up to the Pokémon's body surface.", "h": 5, "w": 110, "dr": ["0-2x Amethyst Shard", "1x Wide Lens 5%", "1x Diamond 5%", "1x Emerald 5%", "1x Roseli Berry 5%"]}, "cobblemon:p0303_mawile": {"n": 303, "d": "Don't be taken in by this Pokémon's cute face—it's very dangerous. Mawile fools the foe into letting down its guard, then chomps down with its massive jaws. The steel jaws are really horns that have been transformed.", "h": 6, "w": 115, "dr": ["1x Razor Fang 5%", "1x Occa Berry 5%", "1x Iron Ball 5%"]}, "cobblemon:p0304_aron": {"n": 304, "d": "Aron has a body of steel. With one all-out charge, this Pokémon can demolish even a heavy dump truck. The destroyed dump truck then becomes a handy meal for the Pokémon.", "h": 4, "w": 600, "dr": ["0-1x Raw Iron", "1x Hard Stone 2.5%", "1x Chople Berry 2.5%"]}, "cobblemon:p0305_lairon": {"n": 305, "d": "Lairon feeds on iron contained in rocks and water. It makes its nest on mountains where iron ore is buried. As a result, the Pokémon often clashes with humans mining the iron ore.", "h": 9, "w": 1200, "dr": ["0-2x Raw Iron", "1x Hard Stone 5%", "1x Chople Berry 5%"]}, "cobblemon:p0306_aggron": {"n": 306, "d": "Aggron is protective of its environment. If its mountain is ravaged by a landslide or a fire, this Pokémon will haul topsoil to the area, plant trees, and beautifully restore its own territory.", "h": 21, "w": 3600, "dr": ["0-3x Raw Iron", "1x Hard Stone 10%", "1x Chople Berry 10%"]}, "cobblemon:p0307_meditite": {"n": 307, "d": "Meditite heightens its inner energy through meditation. It survives on just one berry a day. Minimal eating is another aspect of this Pokémon's training.", "h": 6, "w": 112, "dr": ["1x Wise Glasses 2.5%", "1x Black Belt 2.5%", "1x Nanab Berry 2.5%"]}, "cobblemon:p0308_medicham": {"n": 308, "d": "Through the power of meditation, Medicham developed its sixth sense. It gained the ability to use psychokinetic powers. This Pokémon is known to meditate for a whole month without eating.", "h": 13, "w": 315, "dr": ["1x Wise Glasses 5%", "1x Black Belt 5%", "1x Nanab Berry 5%"]}, "cobblemon:p0309_electrike": {"n": 309, "d": "Electrike runs faster than the human eye can follow. The friction from running is converted into electricity, which is then stored in this Pokémon's fur.", "h": 6, "w": 152, "dr": ["0-1x Bone", "0-1x Rotten Flesh", "1x Cheri Berry 2.5%"]}, "cobblemon:p0310_manectric": {"n": 310, "d": "Manectric discharges strong electricity from its mane. The mane is used for collecting electricity in the atmosphere. This Pokémon creates thunderclouds above its head.", "h": 15, "w": 402, "dr": ["0-2x Bone", "0-2x Rotten Flesh", "1x Cheri Berry 5%"]}, "cobblemon:p0311_plusle": {"n": 311, "d": "When Plusle is cheering on its partner, it flashes with electric sparks from all over its body. If its partner loses, this Pokémon cries loudly.", "h": 4, "w": 42, "dr": ["1x Magnet 5%", "1x Cell Battery 5%", "1x Cheri Berry 5%"]}, "cobblemon:p0312_minun": {"n": 312, "d": "Minun loves to cheer on its partner in battle. It gives off sparks from its body while it is doing so. If its partner is in trouble, this Pokémon gives off increasing amounts of sparks.", "h": 4, "w": 42, "dr": ["1x Magnet 5%", "1x Cell Battery 5%", "1x Cheri Berry 5%"]}, "cobblemon:p0313_volbeat": {"n": 313, "d": "Volbeat's tail glows like a lightbulb. With other Volbeat, it uses its tail to draw geometric shapes in the night sky. This Pokémon loves the sweet aroma given off by Illumise.", "h": 7, "w": 177, "dr": ["1x Bright Powder 5%", "1x Razz Berry 5%"]}, "cobblemon:p0314_illumise": {"n": 314, "d": "Illumise leads a flight of illuminated Volbeat to draw signs in the night sky. This Pokémon is said to earn greater respect from its peers by composing more complex designs in the sky.", "h": 6, "w": 177, "dr": ["1x Bright Powder 5%", "1x Bluk Berry 5%"]}, "cobblemon:p0315_roselia": {"n": 315, "d": "On extremely rare occasions, a Roselia is said to appear with its flowers in unusual colors. The thorns on this Pokémon's head contain a vicious poison.", "h": 3, "w": 20, "dr": ["0-1x Rose Bush", "1x Poison Barb 5%", "1x Absorb Bulb 5%", "1x Pecha Berry 5%"]}, "cobblemon:p0318_carvanha": {"n": 318, "d": "If anything invades Carvanha's territory, it will swarm and tear at the intruder with its pointed fangs. On its own, however, this Pokémon turns suddenly timid.", "h": 8, "w": 208, "dr": ["1x Deep Sea Tooth 2.5%", "1x Aspear Berry 2.5%"]}, "cobblemon:p0319_sharpedo": {"n": 319, "d": "Sharpedo can swim at speeds of up to 75 mph by jetting seawater out of its backside. This Pokémon's drawback is its inability to swim long distances.", "h": 18, "w": 888, "dr": ["1x Deep Sea Tooth 5%", "1x Aspear Berry 5%"]}, "cobblemon:p0320_wailmer": {"n": 320, "d": "Wailmer can store water inside its body to transform itself into a ball for bouncing around on the ground. By filling itself up with more water, this Pokémon can elevate the height of its bounces.", "h": 20, "w": 1300, "dr": ["0-1x Bone Block", "1x Chesto Berry 2.5%"]}, "cobblemon:p0321_wailord": {"n": 321, "d": "When chasing prey, Wailord herds them by leaping out of the water and making a humongous splash. It is breathtaking to see this Pokémon leaping out of the sea with others in its pod.", "h": 145, "w": 3980, "dr": ["0-2x Bone Block", "1x Chesto Berry 5%"]}, "cobblemon:p0322_numel": {"n": 322, "d": "Numel stores magma of almost 2,200 degrees Fahrenheit within its body. If it gets wet, the magma cools and hardens. In that event, the Pokémon's body grows heavy and its movements become sluggish.", "h": 7, "w": 240, "dr": ["1x Magma Cream 2.5%", "1x Rawst Berry 2.5%"]}, "cobblemon:p0323_camerupt": {"n": 323, "d": "The humps on Camerupt's back are formed by a transformation of its bones. They sometimes blast out molten magma. This Pokémon apparently erupts often when it is enraged.", "h": 19, "w": 2200, "dr": ["1x Magma Cream 5%", "1x Rawst Berry 5%"]}, "cobblemon:p0324_torkoal": {"n": 324, "d": "Torkoal generates energy by burning coal. It grows weaker as the fire dies down. When it is preparing for battle, this Pokémon burns more coal.", "h": 5, "w": 804, "dr": ["0-2x Coal", "1x Charcoal Stick 5%", "1x Smoke Ball 5%", "1x Charti Berry 5%"]}, "cobblemon:p0325_spoink": {"n": 325, "d": "Spoink keeps a pearl on top of its head. The pearl functions to amplify this Pokémon's psychokinetic powers. It is therefore on a constant search for a bigger pearl.", "h": 7, "w": 306, "dr": ["1-2x Porkchop", "0-1x Ender Pearl", "1x Tanga Berry 2.5%"]}, "cobblemon:p0326_grumpig": {"n": 326, "d": "Grumpig uses the black pearls on its body to wield its fantastic powers. When it is doing so, it dances bizarrely. This Pokémon's black pearls are valuable as works of art.", "h": 9, "w": 715, "dr": ["1-3x Porkchop", "0-2x Ender Pearl", "1x Tanga Berry 5%"]}, "cobblemon:p0327_spinda": {"n": 327, "d": "No two Spinda are said to have identical spot patterns on their hides. This Pokémon moves in a curious manner as if it is stumbling in dizziness. Its lurching movements can cause the opponent to become confused.", "h": 11, "w": 50, "dr": ["0-2x Bamboo", "1x Chesto Berry 5%"]}, "cobblemon:p0328_trapinch": {"n": 328, "d": "Trapinch is a patient hunter. It digs an inescapable pit in a desert and waits for its prey to come tumbling down. This Pokémon can go a whole week without access to any water.", "h": 7, "w": 150, "dr": ["1x Soft Sand 2.5%", "1x Yache Berry 2.5%"]}, "cobblemon:p0329_vibrava": {"n": 329, "d": "Vibrava's wings have not yet completed the process of growing. Rather than flying long distances, they are more useful for generating ultrasonic waves by vibrating.", "h": 11, "w": 153, "dr": ["1x Soft Sand 5%", "1x Yache Berry 5%"]}, "cobblemon:p0330_flygon": {"n": 330, "d": "Flygon whips up a sandstorm by flapping its wings. The wings create a series of notes that sound like singing. Because the \"singing\" is the only thing that can be heard in a sandstorm, this Pokémon is said to be the desert spirit.", "h": 20, "w": 820, "dr": ["1x Soft Sand 10%", "1x Yache Berry 10%"]}, "cobblemon:p0331_cacnea": {"n": 331, "d": "The more arid and harsh the environment, the more pretty and fragrant a flower Cacnea grows. This Pokémon battles by wildly swinging its thorny arms.", "h": 4, "w": 513, "dr": ["0-1x Cactus", "1x Poison Barb 2.5%", "1x Tanga Berry 2.5%", "1x Sticky Barb 2.5%"]}, "cobblemon:p0332_cacturne": {"n": 332, "d": "If a traveler is going through a desert in the thick of night, Cacturne will follow in a ragtag group. The Pokémon are biding their time, waiting for the traveler to tire and become incapable of moving.", "h": 13, "w": 774, "dr": ["0-2x Cactus", "1x Poison Barb 5%", "1x Tanga Berry 5%", "1x Sticky Barb 5%"]}, "cobblemon:p0333_swablu": {"n": 333, "d": "Swablu loves to make things clean. If it spots something dirty, it will wipe and polish it with its cottony wings. If its wings become dirty, this Pokémon finds a stream and showers itself.", "h": 4, "w": 12, "dr": ["0-1x White Wool", "1x Chicken", "1x Yache Berry 2.5%"]}, "cobblemon:p0334_altaria": {"n": 334, "d": "Altaria sings in a gorgeous soprano. Its wings are like cotton clouds. This Pokémon catches updrafts with its buoyant wings and soars way up into the wild blue yonder.", "h": 11, "w": 206, "dr": ["0-2x White Wool", "1x Chicken", "1x Yache Berry 5%"]}, "cobblemon:p0335_zangoose": {"n": 335, "d": "Zangoose usually stays on all fours, but when angered, it gets up on its hind legs and extends its claws. This Pokémon shares a bitter rivalry with Seviper that dates back over generations.", "h": 13, "w": 403, "dr": ["1x Razor Claw 5%", "1x Quick Claw 5%", "1x Pecha Berry 5%"]}, "cobblemon:p0336_seviper": {"n": 336, "d": "Seviper's swordlike tail serves two purposes—it slashes foes and douses them with secreted poison. This Pokémon will not give up its long-running blood feud with Zangoose.", "h": 27, "w": 525, "dr": ["1x Razor Fang 5%", "1x Poison Barb 5%", "1x Shed Shell 5%", "1x Persim Berry 5%"]}, "cobblemon:p0337_lunatone": {"n": 337, "d": "Lunatone becomes active around the time of the full moon. Instead of walking, it moves by floating in midair. The Pokémon's intimidating red eyes cause all those who see it to become transfixed with fear.", "h": 10, "w": 1680, "dr": ["1x Moon Stone 5%", "1x Colbur Berry 5%"]}, "cobblemon:p0338_solrock": {"n": 338, "d": "Sunlight is the source of Solrock's power. It is said to possess the ability to read the emotions of others. This Pokémon gives off intense heat while rotating its body.", "h": 12, "w": 1540, "dr": ["1x Sun Stone 5%", "1x Colbur Berry 5%"]}, "cobblemon:p0339_barboach": {"n": 339, "d": "Barboach's body is covered with a slimy film. If a foe grabs it, this Pokémon just slips out of the enemy's grip. This Pokémon grows weak if the slimy coating dries up.", "h": 4, "w": 19, "dr": ["0-1x Clay Ball", "1x Rindo Berry 2.5%"]}, "cobblemon:p0340_whiscash": {"n": 340, "d": "If Whiscash goes on a wild rampage, it sets off a quake-like tremor with a radius of over three miles. This Pokémon has the ability to predict real earthquakes.", "h": 9, "w": 236, "dr": ["0-2x Clay Ball", "1x Rindo Berry 5%"]}, "cobblemon:p0341_corphish": {"n": 341, "d": "Corphish catches prey with its sharp claws. It has no likes or dislikes when it comes to food—it will eat anything. This Pokémon has no trouble living in filthy water.", "h": 6, "w": 115, "dr": []}, "cobblemon:p0342_crawdaunt": {"n": 342, "d": "Crawdaunt molts (sheds) its shell regularly. Immediately after molting, its shell is soft and tender. Until the shell hardens, this Pokémon hides in its streambed burrow to avoid attack from its foes.", "h": 11, "w": 328, "dr": []}, "cobblemon:p0343_baltoy": {"n": 343, "d": "As soon as it spots others of its kind, Baltoy congregates with them and then begins crying noisily in unison. This Pokémon sleeps while cleverly balancing itself on its one foot.", "h": 5, "w": 215, "dr": ["0-1x Clay Ball", "1x Light Clay 2.5%", "1x Colbur Berry 2.5%"]}, "cobblemon:p0344_claydol": {"n": 344, "d": "Claydol is an enigma that appeared from a clay statue made by an ancient civilization dating back 20,000 years. This Pokémon shoots beams from both its hands.", "h": 15, "w": 1080, "dr": ["0-2x Clay Ball", "1x Light Clay 5%", "1x Colbur Berry 5%"]}, "cobblemon:p0345_lileep": {"n": 345, "d": "Lileep is an ancient Pokémon that was regenerated from a fossil. It remains permanently anchored to a rock. From its immobile perch, this Pokémon intently scans for prey with its two eyes.", "h": 10, "w": 238, "dr": ["1x Big Root 5%"]}, "cobblemon:p0346_cradily": {"n": 346, "d": "Cradily's body serves as an anchor, preventing it from being washed away in rough seas. This Pokémon secretes a strong digestive fluid from its tentacles.", "h": 15, "w": 604, "dr": ["1x Big Root 10%"]}, "cobblemon:p0347_anorith": {"n": 347, "d": "Anorith is said to be a type of Pokémon predecessor, with eight wings at the sides of its body. This Pokémon swam in the primordial sea by undulating these eight wings.", "h": 7, "w": 125, "dr": ["1x Quick Claw 5%"]}, "cobblemon:p0348_armaldo": {"n": 348, "d": "Armaldo is a Pokémon species that became extinct in prehistoric times. This Pokémon is said to have walked on its hind legs, which would have been more convenient for life on land.", "h": 15, "w": 682, "dr": ["1x Quick Claw 10%"]}, "cobblemon:p0349_feebas": {"n": 349, "d": "While Feebas's body is in tatters, it has a hardy and tenacious life force that enables it to live anywhere. However, this Pokémon is also slow and dimwitted, making it an easy catch.", "h": 6, "w": 74, "dr": ["1x Salmon", "1x Bone Meal 5%", "1x Prism Scale 2.5%"]}, "cobblemon:p0350_milotic": {"n": 350, "d": "Milotic live at the bottom of large lakes. When this Pokémon's body glows a vivid pink, it releases a pulsing wave of energy that brings soothing calm to troubled hearts.", "h": 62, "w": 1620, "dr": ["1x Bone Meal 10%", "1x Prism Scale 5%"]}, "cobblemon:p0352_kecleon": {"n": 352, "d": "Kecleon alters its body coloration to blend in with its surroundings, allowing it to sneak up on its prey unnoticed. Then it lashes out with its long, stretchy tongue to instantly ensnare the unsuspecting target.", "h": 10, "w": 220, "dr": ["1x Persim Berry 5%"]}, "cobblemon:p0353_shuppet": {"n": 353, "d": "Shuppet grows by feeding on dark emotions, such as vengefulness and envy, in the hearts of people. It roams through cities in search of grudges that taint people.", "h": 6, "w": 23, "dr": ["1x Phantom Membrane 2.5%", "1x Spell Tag 2.5%"]}, "cobblemon:p0354_banette": {"n": 354, "d": "A cursed energy permeated the stuffing of a discarded and forgotten plush doll, giving it new life as Banette. The Pokémon's energy would escape if it were to ever open its mouth.", "h": 11, "w": 125, "dr": ["1x Phantom Membrane 5%", "1x Spell Tag 5%"]}, "cobblemon:p0355_duskull": {"n": 355, "d": "Duskull wanders lost among the deep darkness of midnight. There is an oft-told admonishment given to misbehaving children that this Pokémon will spirit away bad children who earn scoldings from their mothers.", "h": 8, "w": 150, "dr": ["1x Phantom Membrane 2.5%", "1x Reaper Cloth 2.5%", "1x Kasib Berry 2.5%"]}, "cobblemon:p0356_dusclops": {"n": 356, "d": "Dusclops absorbs anything, however large the object may be. This Pokémon hypnotizes its foe by waving its hands in a macabre manner and by bringing its single eye to bear. The hypnotized foe is made to do Dusclops's bidding.", "h": 16, "w": 306, "dr": ["1x Phantom Membrane 5%", "1x Reaper Cloth 5%", "1x Kasib Berry 5%"]}, "cobblemon:p0357_tropius": {"n": 357, "d": "Children of the southern tropics eat as snacks the fruit that grows in bunches around the neck of Tropius. This Pokémon flies by flapping the leaves on its back as if they were wings.", "h": 20, "w": 1000, "dr": ["0-2x Nanab Berry"]}, "cobblemon:p0358_chimecho": {"n": 358, "d": "In high winds, Chimecho cries as it hangs from a tree branch or the eaves of a building using a suction cup on its head. This Pokémon plucks berries with its long tail and eats them.", "h": 6, "w": 10, "dr": ["1x Colbur Berry 5%", "1x Cleanse Tag 5%", "1x Soothe Bell 5%"]}, "cobblemon:p0359_absol": {"n": 359, "d": "Absol has the ability to foretell the coming of natural disasters. It lives in a harsh, rugged mountain environment. This Pokémon very rarely ventures down from the mountains.", "h": 12, "w": 470, "dr": ["1x Razor Claw 5%", "1x Life Orb 5%", "1x Roseli Berry 5%"]}, "cobblemon:p0360_wynaut": {"n": 360, "d": "Wynaut gather on moonlit nights to play by squeezing up against each other. By being squeezed, this Pokémon gains endurance and is trained to dole out powerful counterattacks.", "h": 6, "w": 140, "dr": ["1x Colbur Berry 2.5%"]}, "cobblemon:p0361_snorunt": {"n": 361, "d": "Snorunt survives by eating only snow and ice. Old folklore claims that a house visited by this Pokémon is sure to prosper for many generations to come.", "h": 7, "w": 168, "dr": ["0-1x Snowball", "1x Dawn Stone 2.5%", "1x Never-Melt Ice 2.5%", "1x Babiri Berry 2.5%"]}, "cobblemon:p0362_glalie": {"n": 362, "d": "Glalie has the ability to freely control ice. For example, it can instantly freeze its prey solid. After immobilizing its prey in ice, this Pokémon enjoys eating it in leisurely fashion.", "h": 15, "w": 2565, "dr": ["0-2x Snowball", "1x Dawn Stone 5%", "1x Never-Melt Ice 5%", "1x Babiri Berry 5%"]}, "cobblemon:p0363_spheal": {"n": 363, "d": "Spheal always travels by rolling around on its ball-like body. When the season for ice floes arrives, this Pokémon can be seen rolling about on ice and crossing the sea.", "h": 8, "w": 395, "dr": ["0-1x Cod", "1x Chesto Berry 2.5%"]}, "cobblemon:p0364_sealeo": {"n": 364, "d": "Sealeo often balances and rolls things on the tip of its nose. While the Pokémon is rolling something, it checks the object's aroma and texture to determine whether it likes the object or not.", "h": 11, "w": 876, "dr": ["0-2x Cod", "1x Chesto Berry 5%"]}, "cobblemon:p0365_walrein": {"n": 365, "d": "Walrein swims all over in frigid seawater while crushing icebergs with its grand, imposing tusks. Its thick layer of blubber makes enemy attacks bounce off harmlessly.", "h": 14, "w": 1506, "dr": ["0-3x Cod", "1x Chesto Berry 10%"]}, "cobblemon:p0366_clamperl": {"n": 366, "d": "Clamperl grows while being protected by its rock-hard shell. When its body becomes too large to fit inside the shell, it is sure evidence that this Pokémon is getting close to evolution.", "h": 4, "w": 525, "dr": ["1x Shell Bell 2.5%"]}, "cobblemon:p0367_huntail": {"n": 367, "d": "Huntail's tail is shaped like a fish. It uses the tail to attract prey, then swallows the prey whole with its large, gaping mouth. This Pokémon swims by wiggling its slender body like a snake.", "h": 17, "w": 270, "dr": ["1x Deep Sea Tooth 5%"]}, "cobblemon:p0368_gorebyss": {"n": 368, "d": "Although Gorebyss is the very picture of elegance and beauty while swimming, it is also cruel. When it spots prey, this Pokémon inserts its thin mouth into the prey's body and drains the prey of its body fluids.", "h": 18, "w": 226, "dr": ["1x Deep Sea Scale 5%"]}, "cobblemon:p0369_relicanth": {"n": 369, "d": "Relicanth is a rare species that was discovered in deep-sea explorations. This Pokémon's body withstands the enormous water pressure of the ocean depths. Its body is covered in tough scales that are like craggy rocks.", "h": 10, "w": 234, "dr": ["1x Deep Sea Scale 5%", "1x Rindo Berry 5%"]}, "cobblemon:p0370_luvdisc": {"n": 370, "d": "Luvdisc's heart-shaped body is a symbol of love and romance. It is said that any couple meeting this Pokémon is promised a loving relationship that never ends.", "h": 6, "w": 87, "dr": ["1x Deep Sea Scale 2.5%"]}, "cobblemon:p0371_bagon": {"n": 371, "d": "Bagon harbors a never-ending dream of one day soaring high among the clouds. As if trying to dispel its frustration over its inability to fly, this Pokémon slams its hard head against huge rocks and shatters them into pebbles.", "h": 6, "w": 421, "dr": ["1x Dragon Fang 2.5%", "1x Dragon Scale 2.5%", "1x Yache Berry 2.5%"]}, "cobblemon:p0372_shelgon": {"n": 372, "d": "Covering Shelgon's body are outgrowths much like bones. The shell is very hard and bounces off enemy attacks. When awaiting evolution, this Pokémon hides away in a cavern.", "h": 11, "w": 1105, "dr": ["1x Dragon Fang 5%", "1x Dragon Scale 5%", "1x Yache Berry 5%"]}, "cobblemon:p0373_salamence": {"n": 373, "d": "By evolving into Salamence, this Pokémon finally realizes its long-held dream of growing wings. To express its joy, it flies and wheels all over the sky while spouting flames from its mouth.", "h": 15, "w": 1026, "dr": ["1x Dragon Fang 10%", "1x Dragon Scale 10%", "1x Yache Berry 10%"]}, "cobblemon:p0374_beldum": {"n": 374, "d": "Beldum keeps itself floating by generating a magnetic force that repels earth's natural magnetism. When it sleeps, this Pokémon anchors itself to a cliff using the hooks on its rear.", "h": 6, "w": 952, "dr": ["0-1x Ender Pearl", "1x Metal Coat 2.5%"]}, "cobblemon:p0375_metang": {"n": 375, "d": "When two Beldum fuse together, Metang is formed. The brains of the Beldum are joined by a magnetic nervous system. This Pokémon turns its arms to the rear for traveling at high speed.", "h": 12, "w": 2025, "dr": ["0-2x Ender Pearl", "1x Metal Coat 5%"]}, "cobblemon:p0376_metagross": {"n": 376, "d": "Metagross is the result of two Metang achieving fusion. When hunting, this Pokémon pins the prey to the ground under its massive body. It then eats the helpless victim using the large mouth on its stomach.", "h": 16, "w": 5500, "dr": ["0-3x Ender Pearl", "1x Metal Coat 10%"]}, "cobblemon:p0377_regirock": {"n": 377, "d": "Regirock's body is composed entirely of rocks. Recently, a study made the startling discovery that the rocks were all unearthed from different locations.", "h": 17, "w": 2300, "dr": ["1x Hard Stone"]}, "cobblemon:p0378_regice": {"n": 378, "d": "Regice cloaks itself with frigid air of -328 degrees Fahrenheit. Things will freeze solid just by going near this Pokémon. Its icy body is so cold, it will not melt even if it is immersed in magma.", "h": 18, "w": 1750, "dr": ["1x Never-Melt Ice"]}, "cobblemon:p0379_registeel": {"n": 379, "d": "Registeel was imprisoned by people in ancient times. The metal composing its body is thought to be a curious substance that is not of this earth.", "h": 19, "w": 2050, "dr": ["1x Metal Coat"]}, "cobblemon:p0380_latias": {"n": 380, "d": "Latias is highly intelligent and capable of understanding human speech. It is covered with a glass-like down. The Pokémon enfolds its body with its down and refracts light to alter its appearance.", "h": 14, "w": 400, "dr": ["2-4x Feather"]}, "cobblemon:p0381_latios": {"n": 381, "d": "Latios will only open its heart to a Trainer with a compassionate spirit. This Pokémon can fly faster than a jet plane by folding its forelegs to minimize air resistance.", "h": 20, "w": 600, "dr": ["2-4x Feather"]}, "cobblemon:p0384_rayquaza": {"n": 384, "d": "Rayquaza is said to have lived for hundreds of millions of years. Legends remain of how it put to rest the clash between Kyogre and Groudon.", "h": 70, "w": 2065, "dr": ["3-5x Dragon Breath"]}, "cobblemon:p0387_turtwig": {"n": 387, "d": "It undertakes photosynthesis with its body, making oxygen. The leaf on its head wilts if it is thirsty.", "h": 4, "w": 102, "dr": ["1x Oak Sapling", "1x Miracle Seed 5%"]}, "cobblemon:p0388_grotle": {"n": 388, "d": "It knows where pure water wells up. It carries fellow Pokémon there on its back.", "h": 11, "w": 970, "dr": ["2-4x Sweet Berries", "1x Miracle Seed 10%"]}, "cobblemon:p0389_torterra": {"n": 389, "d": "Small Pokémon occasionally gather on its unmoving back to begin building their nests.", "h": 22, "w": 3100, "dr": ["0-3x Apple", "1x Miracle Seed 25%"]}, "cobblemon:p0390_chimchar": {"n": 390, "d": "The gas made in its belly burns from its rear end. The fire burns weakly when it feels sick.", "h": 5, "w": 62, "dr": ["1x Charcoal Stick 5%"]}, "cobblemon:p0391_monferno": {"n": 391, "d": "It uses ceilings and walls to launch aerial attacks. Its fiery tail is but one weapon.", "h": 9, "w": 220, "dr": ["1x Charcoal Stick 10%"]}, "cobblemon:p0392_infernape": {"n": 392, "d": "It tosses its enemies around with agility. It uses all its limbs to fight in its own unique style.", "h": 12, "w": 550, "dr": ["1x Charcoal Stick 25%"]}, "cobblemon:p0393_piplup": {"n": 393, "d": "Because it is very proud, it hates accepting food from people. Its thick down guards it from cold.", "h": 4, "w": 52, "dr": ["0-1x Feather", "1x Chicken", "1x Mystic Water 5%"]}, "cobblemon:p0394_prinplup": {"n": 394, "d": "It lives a solitary life. Its wings deliver wicked blows that can snap even the thickest of trees.", "h": 8, "w": 230, "dr": ["0-2x Feather", "1x Chicken", "1x Mystic Water 10%"]}, "cobblemon:p0395_empoleon": {"n": 395, "d": "The three horns that extend from its beak attest to its power. The leader has the biggest horns.", "h": 17, "w": 845, "dr": ["0-3x Feather", "1x Chicken", "1x Mystic Water 25%"]}, "cobblemon:p0396_starly": {"n": 396, "d": "They flock around mountains and fields, chasing after bug Pokémon. Their singing is noisy and annoying.", "h": 3, "w": 20, "dr": ["0-1x Feather", "1x Chicken", "1x Yache Berry 2.5%"]}, "cobblemon:p0397_staravia": {"n": 397, "d": "It lives in forests and fields. Squabbles over territory occur when flocks collide.", "h": 6, "w": 155, "dr": ["0-2x Feather", "1x Chicken", "1x Sharp Beak 2.5%", "1x Yache Berry 5%"]}, "cobblemon:p0398_staraptor": {"n": 398, "d": "When Staravia evolve into Staraptor, they leave the flock to live alone. They have sturdy wings.", "h": 12, "w": 249, "dr": ["0-3x Feather", "1x Chicken", "1x Sharp Beak 5%", "1x Yache Berry 10%"]}, "cobblemon:p0399_bidoof": {"n": 399, "d": "It constantly gnaws on logs and rocks to whittle down its front teeth. It nests alongside water.", "h": 5, "w": 200, "dr": ["0-1x Stick", "1x Oran Berry 2.5%"]}, "cobblemon:p0400_bibarel": {"n": 400, "d": "It makes its nest by damming streams with bark and mud. It is known as an industrious worker.", "h": 10, "w": 315, "dr": ["0-2x Stick", "1x Oran Berry 5%"]}, "cobblemon:p0401_kricketot": {"n": 401, "d": "When its antennae hit each other, it sounds like the music of a xylophone.", "h": 3, "w": 22, "dr": ["1x Metronome 2.5%", "1x Coba Berry 2.5%"]}, "cobblemon:p0402_kricketune": {"n": 402, "d": "It signals its emotions with its melodies. Scientists are studying these melodic patterns.", "h": 10, "w": 255, "dr": ["1x Metronome 5%", "1x Coba Berry 5%"]}, "cobblemon:p0403_shinx": {"n": 403, "d": "All of its fur dazzles if danger is sensed. It flees while the foe is momentarily blinded.", "h": 5, "w": 95, "dr": ["1x Quick Claw 2.5%", "1x Shuca Berry 2.5%"]}, "cobblemon:p0404_luxio": {"n": 404, "d": "Strong electricity courses through the tips of its sharp claws. A light scratch causes fainting in foes.", "h": 9, "w": 305, "dr": ["1x Quick Claw 5%", "1x Shuca Berry 5%"]}, "cobblemon:p0405_luxray": {"n": 405, "d": "Luxray's ability to see through objects comes in handy when it's scouting for danger.", "h": 14, "w": 420, "dr": ["1x Quick Claw 10%", "1x Shuca Berry 10%"]}, "cobblemon:p0406_budew": {"n": 406, "d": "Over the winter, it closes its bud and endures the cold. In spring, the bud opens and releases pollen.", "h": 2, "w": 12, "dr": ["1x Poison Barb 2.5%", "1x Absorb Bulb 2.5%", "1x Pecha Berry 2.5%"]}, "cobblemon:p0407_roserade": {"n": 407, "d": "With the movements of a dancer, it strikes with whips that are densely lined with poison thorns.", "h": 9, "w": 145, "dr": ["1-2x Rose Bush", "1x Poison Barb 10%", "1x Absorb Bulb 10%", "1x Pecha Berry 10%"]}, "cobblemon:p0408_cranidos": {"n": 408, "d": "A lifelong jungle dweller from 100 million years ago, it would snap obstructing trees with headbutts.", "h": 9, "w": 315, "dr": ["0-1x Bone"]}, "cobblemon:p0409_rampardos": {"n": 409, "d": "Its skull is as hard as iron. It is a brute that tears down jungle trees while catching prey.", "h": 16, "w": 1025, "dr": ["0-2x Bone"]}, "cobblemon:p0410_shieldon": {"n": 410, "d": "It was generated from a fossil dug out of a layer of clay that was older than anyone knows. It has a sturdy face.", "h": 5, "w": 570, "dr": ["0-1x Bone"]}, "cobblemon:p0411_bastiodon": {"n": 411, "d": "Any frontal attack is repulsed. It is a docile Pokémon that feeds on grass and berries.", "h": 13, "w": 1495, "dr": ["0-2x Bone"]}, "cobblemon:p0412_burmy": {"n": 412, "d": "If its cloak is broken in battle, it quickly remakes the cloak with materials nearby.", "h": 2, "w": 34, "dr": ["0-1x String", "1x Occa Berry 2.5%"]}, "cobblemon:p0413_wormadam": {"n": 413, "d": "When Burmy evolved, its cloak became a part of this Pokémon's body. The cloak is never shed.", "h": 5, "w": 65, "dr": ["0-2x String", "1x Occa Berry 5%"]}, "cobblemon:p0414_mothim": {"n": 414, "d": "It flutters around at night and steals honey from the Combee hive.", "h": 9, "w": 233, "dr": ["1x Silver Powder 5%", "1x Occa Berry 5%"]}, "cobblemon:p0415_combee": {"n": 415, "d": "It collects and delivers honey to its colony. At night, they cluster to form a beehive and sleep.", "h": 3, "w": 55, "dr": ["0-1x Honey Bottle", "0-1x Honeycomb", "1x Poison Barb 2.5%", "1x Charti Berry 2.5%"]}, "cobblemon:p0416_vespiquen": {"n": 416, "d": "Its abdomen is a honeycomb for grubs. It raises its grubs on honey collected by Combee.", "h": 12, "w": 385, "dr": ["0-3x Honey Bottle", "0-3x Honeycomb", "1x Poison Barb 10%", "1x Charti Berry 10%"]}, "cobblemon:p0417_pachirisu": {"n": 417, "d": "A pair may be seen rubbing their cheek pouches together in an effort to share stored electricity.", "h": 4, "w": 39, "dr": ["1x Cheri Berry 5%"]}, "cobblemon:p0418_buizel": {"n": 418, "d": "It inflates the flotation sac around its neck and pokes its head out of the water to see what is going on.", "h": 7, "w": 295, "dr": ["0-1x Salmon", "1x Wacan Berry 2.5%"]}, "cobblemon:p0419_floatzel": {"n": 419, "d": "Its flotation sac developed as a result of pursuing aquatic prey. It can double as a rubber raft.", "h": 11, "w": 335, "dr": ["0-2x Salmon", "1x Wacan Berry 5%"]}, "cobblemon:p0420_cherubi": {"n": 420, "d": "It evolves by sucking the energy out of the small ball where it had been storing nutrients.", "h": 4, "w": 33, "dr": ["1-3x Sweet Berries", "1x Miracle Seed 2.5%", "1x Cheri Berry 2.5%"]}, "cobblemon:p0421_cherrim": {"n": 421, "d": "If it senses strong sunlight, it opens its folded petals to absorb the sun's rays with its whole body.", "h": 5, "w": 93, "dr": ["2-4x Sweet Berries", "1x Miracle Seed 5%", "1x Cheri Berry 5%"]}, "cobblemon:p0422_shellos": {"n": 422, "d": "Its shape and coloration vary, depending on its habitat.", "h": 3, "w": 63, "dr": ["0-1x Clay Ball", "1x Rindo Berry 2.5%"]}, "cobblemon:p0423_gastrodon": {"n": 423, "d": "It apparently had a huge shell for protection in ancient times. It lives in shallow tidal pools.", "h": 9, "w": 299, "dr": ["0-2x Clay Ball", "1x Rindo Berry 5%"]}, "cobblemon:p0424_ambipom": {"n": 424, "d": "To eat, it deftly shucks nuts with its two tails. It rarely uses its arms now.", "h": 12, "w": 203, "dr": ["1x Nanab Berry 5%"]}, "cobblemon:p0425_drifloon": {"n": 425, "d": "These Pokémon are called the \"Signpost for Wandering Spirits.\" Children holding them sometimes vanish.", "h": 4, "w": 12, "dr": ["1x Phantom Membrane 2.5%", "1x Kasib Berry 2.5%", "1x Air Balloon 2.5%"]}, "cobblemon:p0426_drifblim": {"n": 426, "d": "It's drowsy in daytime, but flies off in the evening in big groups. No one knows where they go.", "h": 12, "w": 150, "dr": ["1x Phantom Membrane 5%", "1x Kasib Berry 5%", "1x Air Balloon 5%"]}, "cobblemon:p0427_buneary": {"n": 427, "d": "When it senses danger, it perks up its ears. On cold nights, it sleeps with its head tucked into its fur.", "h": 4, "w": 55, "dr": ["1x Rabbit", "0-1x Rabbit Hide", "1x Rabbit Foot 2.5%", "1x Carrot 2.5%", "1x Chople Berry 2.5%"]}, "cobblemon:p0428_lopunny": {"n": 428, "d": "The ears appear to be delicate. If they are touched roughly, it kicks with its graceful legs.", "h": 12, "w": 333, "dr": ["1x Rabbit", "0-2x Rabbit Hide", "1x Rabbit Foot 5%", "1x Carrot 5%", "1x Chople Berry 5%"]}, "cobblemon:p0429_mismagius": {"n": 429, "d": "Its cries sound like incantations to torment the foe. It appears where you least expect it.", "h": 9, "w": 44, "dr": ["1x Phantom Membrane 5%", "1x Spell Tag 5%", "1x Kasib Berry 5%"]}, "cobblemon:p0430_honchkrow": {"n": 430, "d": "Becoming active at night, it is known to swarm with numerous Murkrow in tow.", "h": 9, "w": 273, "dr": ["0-3x Feather", "1x Chicken", "1x Bluk Berry 5%"]}, "cobblemon:p0431_glameow": {"n": 431, "d": "When it's happy, Glameow demonstrates beautiful movements of its tail, like a dancing ribbon.", "h": 5, "w": 39, "dr": ["1x Cheri Berry 2.5%"]}, "cobblemon:p0432_purugly": {"n": 432, "d": "To make itself appear intimidatingly beefy, it tightly cinches its waist with its twin tails.", "h": 10, "w": 438, "dr": ["1x Cheri Berry 5%"]}, "cobblemon:p0433_chingling": {"n": 433, "d": "There is an orb inside its mouth. When it hops, the orb bounces all over and makes a ringing sound.", "h": 2, "w": 6, "dr": ["1x Colbur Berry 2.5%", "1x Soothe Bell 2.5%", "1x Cleanse Tag 2.5%"]}, "cobblemon:p0434_stunky": {"n": 434, "d": "It protects itself by spraying a noxious fluid from its rear. The stench lingers for 24 hours.", "h": 4, "w": 192, "dr": ["1x Pecha Berry 2.5%"]}, "cobblemon:p0435_skuntank": {"n": 435, "d": "It sprays a stinky fluid from its tail. The fluid smells worse the longer it is allowed to fester.", "h": 10, "w": 380, "dr": ["1x Pecha Berry 5%"]}, "cobblemon:p0436_bronzor": {"n": 436, "d": "Implements shaped like it were discovered in ancient tombs. It is unknown if they are related.", "h": 5, "w": 605, "dr": ["0-1x Raw Iron", "1x Mental Herb 2.5%", "1x Light Clay 2.5%", "1x Occa Berry 2.5%"]}, "cobblemon:p0437_bronzong": {"n": 437, "d": "Ancient people believed that petitioning Bronzong for rain was the way to make crops grow.", "h": 13, "w": 1870, "dr": ["0-2x Raw Iron", "1x Mental Herb 5%", "1x Light Clay 5%", "1x Occa Berry 5%"]}, "cobblemon:p0438_bonsly": {"n": 438, "d": "It prefers an arid atmosphere. It leaks water that looks like tears when adjusting its moisture level.", "h": 5, "w": 150, "dr": ["1x Hard Stone 2.5%", "1x Passho Berry 2.5%"]}, "cobblemon:p0439_mimejr": {"n": 439, "d": "It habitually mimics foes. Once mimicked, the foe cannot take its eyes off this Pokémon.", "h": 6, "w": 130, "dr": ["1x Light Clay 2.5%", "1x Babiri Berry 2.5%"]}, "cobblemon:p0440_happiny": {"n": 440, "d": "It carefully carries a round, white rock that it thinks is an egg. It's bothered by how curly its hair looks.", "h": 6, "w": 244, "dr": ["1x Oval Stone 25%"]}, "cobblemon:p0441_chatot": {"n": 441, "d": "It can learn and speak human words. If they gather, they all learn the same saying.", "h": 5, "w": 19, "dr": ["0-2x Feather", "1x Chicken", "1x Metronome 5%", "1x Persim Berry 5%"]}, "cobblemon:p0442_spiritomb": {"n": 442, "d": "It was bound to a fissure in an odd keystone as punishment for misdeeds 500 years ago.", "h": 10, "w": 1080, "dr": ["1x Spell Tag 5%", "1x Smoke Ball 5%"]}, "cobblemon:p0443_gible": {"n": 443, "d": "It nests in small, horizontal holes in cave walls. It pounces to catch prey that stray too close.", "h": 7, "w": 205, "dr": ["1x Dragon Fang 2.5%", "1x Haban Berry 2.5%"]}, "cobblemon:p0444_gabite": {"n": 444, "d": "As it digs to expand its nest, it habitually digs up gems that it then hoards in its nest.", "h": 14, "w": 560, "dr": ["1x Dragon Fang 5%", "1x Haban Berry 5%"]}, "cobblemon:p0445_garchomp": {"n": 445, "d": "It flies at speeds equal to a jet fighter plane. It never allows its prey to escape.", "h": 19, "w": 950, "dr": ["1x Dragon Fang 10%", "1x Haban Berry 10%"]}, "cobblemon:p0446_munchlax": {"n": 446, "d": "It conceals food under the long fur on its body. It carts around this food stash and swallows it without chewing.", "h": 6, "w": 1050, "dr": ["0-3x Apple", "1x Leftovers 2.5%", "1x Chesto Berry 2.5%"]}, "cobblemon:p0447_riolu": {"n": 447, "d": "The aura that emanates from its body intensifies to alert others if it is afraid or sad.", "h": 7, "w": 202, "dr": ["1x Chople Berry 2.5%", "1x Expert Belt 2.5%"]}, "cobblemon:p0448_lucario": {"n": 448, "d": "By reading the auras of all things, it can tell how others are feeling from over half a mile away.", "h": 12, "w": 540, "dr": ["1x Chople Berry 5%", "1x Expert Belt 5%"]}, "cobblemon:p0449_hippopotas": {"n": 449, "d": "It enshrouds itself with sand to protect itself from germs. It does not enjoy getting wet.", "h": 8, "w": 495, "dr": ["0-1x Sand", "1x Soft Sand 2.5%", "1x Chesto Berry 2.5%"]}, "cobblemon:p0450_hippowdon": {"n": 450, "d": "It blasts internally stored sand from ports on its body to create a towering twister for attack.", "h": 20, "w": 3000, "dr": ["0-2x Sand", "1x Soft Sand 5%", "1x Chesto Berry 5%"]}, "cobblemon:p0451_skorupi": {"n": 451, "d": "It burrows under the sand to lie in wait for prey. Its tail claws can inject its prey with a savage poison.", "h": 8, "w": 120, "dr": ["1x Poison Barb 2.5%", "1x Bluk Berry 2.5%"]}, "cobblemon:p0452_drapion": {"n": 452, "d": "It has the power in its clawed arms to make scrap of a car. The tips of its claws release poison.", "h": 13, "w": 615, "dr": ["1x Poison Barb 5%", "1x Bluk Berry 5%"]}, "cobblemon:p0453_croagunk": {"n": 453, "d": "Inflating its poison sacs, it fills the area with an odd sound and hits flinching opponents with a poison jab.", "h": 7, "w": 230, "dr": ["1x Black Sludge 2.5%", "1x Payapa Berry 2.5%"]}, "cobblemon:p0454_toxicroak": {"n": 454, "d": "Its knuckle claws secrete a toxin so vile that even a scratch could prove fatal.", "h": 13, "w": 444, "dr": ["1x Black Sludge 5%", "1x Payapa Berry 5%"]}, "cobblemon:p0455_carnivine": {"n": 455, "d": "It binds itself to trees in marshes. It attracts prey with its sweet-smelling drool and gulps them down.", "h": 14, "w": 270, "dr": ["1x Miracle Seed 5%", "1x Big Root 5%", "1x Kebia Berry 5%"]}, "cobblemon:p0456_finneon": {"n": 456, "d": "After long exposure to sunlight, the patterns on its tail fins shine vividly when darkness arrives.", "h": 4, "w": 70, "dr": ["1x Cod", "1x Bone Meal 5%", "1x Rindo Berry 2.5%", "1x Prism Scale 2.5%"]}, "cobblemon:p0457_lumineon": {"n": 457, "d": "To avoid detection by predators, it crawls along the seafloor using the two fins on its chest.", "h": 12, "w": 240, "dr": ["1x Cod", "1x Bone Meal 10%", "1x Rindo Berry 5%", "1x Prism Scale 5%"]}, "cobblemon:p0458_mantyke": {"n": 458, "d": "When it swims close to the surface of the ocean, people aboard ships are able to observe the pattern on its back.", "h": 10, "w": 650, "dr": ["0-1x Cod", "1x Wacan Berry 2.5%"]}, "cobblemon:p0459_snover": {"n": 459, "d": "In the spring, it grows berries with the texture of frozen treats around its belly.", "h": 10, "w": 505, "dr": ["0-1x Snowball", "1-3x Sweet Berries", "1x Never-Melt Ice 2.5%", "1x Occa Berry 2.5%"]}, "cobblemon:p0460_abomasnow": {"n": 460, "d": "It lives a quiet life on mountains that are perpetually covered in snow. It hides itself by whipping up blizzards.", "h": 22, "w": 1355, "dr": ["0-2x Snowball", "2-4x Sweet Berries", "1x Never-Melt Ice 5%", "1x Occa Berry 5%"]}, "cobblemon:p0461_weavile": {"n": 461, "d": "They live in cold regions, forming groups of four or five that hunt prey with impressive coordination.", "h": 11, "w": 340, "dr": ["1x Razor Claw 5%", "1x Grip Claw 5%", "1x Quick Claw 5%", "1x Chople Berry 5%"]}, "cobblemon:p0462_magnezone": {"n": 462, "d": "It evolved from exposure to a special magnetic field. Three units generate magnetism.", "h": 12, "w": 1800, "dr": ["0-3x Raw Iron", "1x Magnet 10%", "1x Metal Coat 10%", "1x Shuca Berry 10%"]}, "cobblemon:p0463_lickilicky": {"n": 463, "d": "Their saliva contains lots of components that can dissolve anything. The numbness caused by their lick does not dissipate.", "h": 17, "w": 1400, "dr": ["0-2x Slime Ball", "1x Lagging Tail 5%", "1x Oran Berry 5%"]}, "cobblemon:p0464_rhyperior": {"n": 464, "d": "It puts rocks in holes in its palms and uses its muscles to shoot them. Geodude are shot at rare times.", "h": 24, "w": 2828, "dr": ["1x Protector 10%", "1x Passho Berry 10%"]}, "cobblemon:p0465_tangrowth": {"n": 465, "d": "Its vines grow so profusely that, in the warm season, you can't even see its eyes.", "h": 20, "w": 1286, "dr": ["0-2x Vine", "1x Big Root 5%"]}, "cobblemon:p0466_electivire": {"n": 466, "d": "It pushes the tips of its two tails against the foe, then lets loose with over 20,000 volts of power.", "h": 18, "w": 1386, "dr": ["0-3x Redstone", "1x Electirizer 10%", "1x Cheri Berry 10%"]}, "cobblemon:p0467_magmortar": {"n": 467, "d": "It blasts fireballs of over 3,600 degrees Fahrenheit out of its arms. Its breath also sears and sizzles.", "h": 16, "w": 680, "dr": ["1x Blaze Powder 10%", "1x Magmarizer 10%", "1x Rawst Berry 10%"]}, "cobblemon:p0468_togekiss": {"n": 468, "d": "It shares many blessings with people who respect one another's rights and avoid needless strife.", "h": 15, "w": 380, "dr": ["1x Lucky Egg 10%", "1x Shiny Stone 10%", "1x Fairy Feather 10%"]}, "cobblemon:p0469_yanmega": {"n": 469, "d": "This six-legged Pokémon is easily capable of transporting an adult in flight. The wings on its tail help it stay balanced.", "h": 19, "w": 515, "dr": ["1x Wide Lens 5%", "1x Charti Berry 5%"]}, "cobblemon:p0470_leafeon": {"n": 470, "d": "Just like a plant, it uses photosynthesis. As a result, it is always enveloped in clear air.", "h": 10, "w": 255, "dr": ["1x Leaf Stone 25%", "1x Miracle Seed 10%"]}, "cobblemon:p0471_glaceon": {"n": 471, "d": "It lowers its body heat to freeze its fur. The hairs then become like needles it can fire.", "h": 8, "w": 259, "dr": ["1x Ice Stone 25%", "1x Never-Melt Ice 10%"]}, "cobblemon:p0472_gliscor": {"n": 472, "d": "Its flight is soundless. It uses its lengthy tail to carry off its prey... Then its elongated fangs do the rest.", "h": 20, "w": 425, "dr": ["1x Phantom Membrane 5%", "1x Razor Fang 5%", "1x Poison Barb 5%", "1x Yache Berry 5%"]}, "cobblemon:p0473_mamoswine": {"n": 473, "d": "Its impressive tusks are made of ice. The population thinned when it turned warm after the ice age.", "h": 25, "w": 2910, "dr": ["2-3x Porkchop", "2-3x Brown Wool", "1x Never-Melt Ice 10%", "1x Aspear Berry 10%"]}, "cobblemon:p0474_porygonz": {"n": 474, "d": "Its programming was modified to enable it to travel through alien dimensions. Seems there might have been an error...", "h": 9, "w": 340, "dr": ["1x Dubious Disc 25%"]}, "cobblemon:p0475_gallade": {"n": 475, "d": "A master of courtesy and swordsmanship, it fights using extending swords on its elbows.", "h": 16, "w": 520, "dr": ["0-3x Ender Pearl", "1x Dawn Stone 10%", "1x Twisted Spoon 10%", "1x Kasib Berry 10%"]}, "cobblemon:p0476_probopass": {"n": 476, "d": "It freely controls three small units called Mini-Noses using magnetic force.", "h": 14, "w": 3400, "dr": ["0-3x Flint", "1x Hard Stone 5%", "1x Magnet 5%", "1x Chople Berry 5%"]}, "cobblemon:p0477_dusknoir": {"n": 477, "d": "The antenna on its head captures radio waves from the world of spirits that command it to take people there.", "h": 22, "w": 1066, "dr": ["1x Phantom Membrane 10%", "1x Reaper Cloth 10%", "1x Kasib Berry 10%"]}, "cobblemon:p0478_froslass": {"n": 478, "d": "Legends in snowy regions say that a woman who was lost on an icy mountain was reborn as Froslass.", "h": 13, "w": 266, "dr": ["0-2x Snowball", "1x Dawn Stone 5%", "1x Never-Melt Ice 5%", "1x Babiri Berry 5%"]}, "cobblemon:p0479_rotom": {"n": 479, "d": "Its body is composed of plasma. It is known to infiltrate electronic devices and wreak havoc.", "h": 3, "w": 3, "dr": []}, "cobblemon:p0486_regigigas": {"n": 486, "d": "There is an enduring legend that states this Pokémon towed continents with ropes.", "h": 37, "w": 4200, "dr": []}, "cobblemon:p0495_snivy": {"n": 495, "d": "They photosynthesize by bathing their tails in sunlight. When they are not feeling well, their tails droop.", "h": 6, "w": 81, "dr": ["1x Miracle Seed 5%"]}, "cobblemon:p0496_servine": {"n": 496, "d": "When it gets dirty, its leaves can't be used in photosynthesis, so it always keeps itself clean.", "h": 8, "w": 160, "dr": ["1x Miracle Seed 10%"]}, "cobblemon:p0497_serperior": {"n": 497, "d": "It can stop its opponents' movements with just a glare. It takes in solar energy and boosts it internally.", "h": 33, "w": 630, "dr": ["1x Miracle Seed 25%"]}, "cobblemon:p0498_tepig": {"n": 498, "d": "It loves to eat roasted berries, but sometimes it gets too excited and burns them to a crisp.", "h": 5, "w": 99, "dr": ["1-2x Porkchop", "1x Charcoal Stick 5%"]}, "cobblemon:p0499_pignite": {"n": 499, "d": "When its internal fire flares up, its movements grow sharper and faster. When in trouble, it emits smoke.", "h": 10, "w": 555, "dr": ["1-3x Porkchop", "1x Charcoal Stick 10%"]}, "cobblemon:p0500_emboar": {"n": 500, "d": "It has mastered fast and powerful fighting moves. It grows a beard of fire.", "h": 16, "w": 1500, "dr": ["2-4x Porkchop", "1x Charcoal Stick 25%"]}, "cobblemon:p0501_oshawott": {"n": 501, "d": "It fights using the scalchop on its stomach. In response to an attack, it retaliates immediately by slashing.", "h": 5, "w": 59, "dr": ["1x Mystic Water 5%", "1x Shell Bell 5%"]}, "cobblemon:p0502_dewott": {"n": 502, "d": "As a result of strict training, each Dewott learns different forms for using the scalchops.", "h": 8, "w": 245, "dr": ["1x Mystic Water 10%", "1x Shell Bell 10%"]}, "cobblemon:p0503_samurott": {"n": 503, "d": "One swing of the sword incorporated in its armor can fell an opponent. A simple glare from one of them quiets everybody.", "h": 15, "w": 946, "dr": ["1x Mystic Water 25%", "1x Shell Bell 25%"]}, "cobblemon:p0504_patrat": {"n": 504, "d": "Extremely cautious, one of them will always be on the lookout, but it won't notice a foe coming from behind.", "h": 5, "w": 116, "dr": ["1x Babiri Berry 2.5%"]}, "cobblemon:p0505_watchog": {"n": 505, "d": "When they see an enemy, their tails stand high, and they spit the seeds of berries stored in their cheek pouches.", "h": 11, "w": 270, "dr": ["1x Babiri Berry 5%"]}, "cobblemon:p0506_lillipup": {"n": 506, "d": "Though it is a very brave Pokémon, it's also smart enough to check its foe's strength and avoid battle.", "h": 4, "w": 41, "dr": ["0-1x Bone", "1x Blue Wool", "1x Chilan Berry 2.5%"]}, "cobblemon:p0507_herdier": {"n": 507, "d": "It has black, cape-like fur that is very hard and decreases the amount of damage it receives.", "h": 9, "w": 147, "dr": ["0-2x Bone", "1-2x Blue Wool", "1x Chilan Berry 5%"]}, "cobblemon:p0508_stoutland": {"n": 508, "d": "Being wrapped in its long fur is so comfortable that a person would be fine even overnight on a wintry mountain.", "h": 12, "w": 610, "dr": ["0-3x Bone", "2-3x Blue Wool", "1x Chilan Berry 10%"]}, "cobblemon:p0509_purrloin": {"n": 509, "d": "They steal from people for fun, but their victims can't help but forgive them. Their deceptively cute act is perfect.", "h": 4, "w": 101, "dr": ["0-1x Rotten Flesh", "1x Bluk Berry 2.5%"]}, "cobblemon:p0510_liepard": {"n": 510, "d": "Stealthily, it sneaks up on its target, striking from behind before its victim has a chance to react.", "h": 11, "w": 375, "dr": ["0-2x Rotten Flesh", "1x Bluk Berry 5%"]}, "cobblemon:p0511_pansage": {"n": 511, "d": "It's good at finding berries and gathers them from all over. It's kind enough to share them with friends.", "h": 6, "w": 105, "dr": ["1x Leaf Stone 2.5%", "1x Miracle Seed 2.5%", "1x Occa Berry 2.5%"]}, "cobblemon:p0512_simisage": {"n": 512, "d": "Ill tempered, it fights by swinging its barbed tail around wildly. The leaf growing on its head is very bitter.", "h": 11, "w": 305, "dr": ["1x Leaf Stone 5%", "1x Miracle Seed 5%", "1x Occa Berry 5%"]}, "cobblemon:p0513_pansear": {"n": 513, "d": "This Pokémon lives in caves in volcanoes. The fire within the tuft on its head can reach 600 degrees Fahrenheit.", "h": 6, "w": 110, "dr": ["1x Fire Stone 2.5%", "1x Charcoal Stick 2.5%", "1x Passho Berry 2.5%"]}, "cobblemon:p0514_simisear": {"n": 514, "d": "When it gets excited, embers rise from its head and tail and it gets hot. For some reason, it loves sweets.", "h": 10, "w": 280, "dr": ["1x Fire Stone 5%", "1x Charcoal Stick 5%", "1x Passho Berry 5%"]}, "cobblemon:p0515_panpour": {"n": 515, "d": "The water stored inside the tuft on its head is full of nutrients. Plants that receive its water grow large.", "h": 6, "w": 135, "dr": ["1x Water Stone 2.5%", "1x Mystic Water 2.5%", "1x Rindo Berry 2.5%"]}, "cobblemon:p0516_simipour": {"n": 516, "d": "It prefers places with clean water. When its tuft runs low, it replenishes it by siphoning up water with its tail.", "h": 10, "w": 290, "dr": ["1x Water Stone 5%", "1x Mystic Water 5%", "1x Rindo Berry 5%"]}, "cobblemon:p0517_munna": {"n": 517, "d": "It eats the dreams of people and Pokémon. When it eats a pleasant dream, it expels pink-colored mist.", "h": 6, "w": 233, "dr": ["1x Chesto Berry 2.5%"]}, "cobblemon:p0518_musharna": {"n": 518, "d": "The dream mist coming from its forehead changes into many different colors depending on the dream that was eaten.", "h": 11, "w": 605, "dr": ["1x Chesto Berry 5%"]}, "cobblemon:p0519_pidove": {"n": 519, "d": "These Pokémon live in cities. They are accustomed to people. Flocks often gather in parks and plazas.", "h": 3, "w": 21, "dr": ["0-1x Feather", "1x Chicken", "1x Razz Berry 2.5%"]}, "cobblemon:p0520_tranquill": {"n": 520, "d": "No matter where in the world it goes, it knows where its nest is, so it never gets separated from its Trainer.", "h": 6, "w": 150, "dr": ["0-2x Feather", "1x Chicken", "1x Sharp Beak 2.5%", "1x Razz Berry 5%"]}, "cobblemon:p0521_unfezant": {"n": 521, "d": "Males have plumage on their heads. They will never let themselves feel close to anyone other than their Trainers.", "h": 12, "w": 290, "dr": ["0-3x Feather", "1x Chicken", "1x Sharp Beak 5%", "1x Razz Berry 10%"]}, "cobblemon:p0522_blitzle": {"n": 522, "d": "Its mane shines when it discharges electricity. They use the frequency and rhythm of these flashes to communicate.", "h": 8, "w": 298, "dr": ["0-1x Leather", "1x Cheri Berry 2.5%"]}, "cobblemon:p0523_zebstrika": {"n": 523, "d": "They have lightning-like movements. When Zebstrika run at full speed, the sound of thunder reverberates.", "h": 16, "w": 795, "dr": ["0-2x Leather", "1x Cheri Berry 5%"]}, "cobblemon:p0524_roggenrola": {"n": 524, "d": "They were discovered a hundred years ago in an earthquake fissure. Inside each one is an energy core.", "h": 4, "w": 180, "dr": ["0-1x Raw Copper", "1x Hard Stone 2.5%", "1x Everstone 2.5%", "1x Black Augurite 2.5%"]}, "cobblemon:p0525_boldore": {"n": 525, "d": "When it is healthy, its core sticks out. Always facing the same way, it swiftly moves front to back and left to right.", "h": 9, "w": 1020, "dr": ["0-2x Raw Copper", "1x Hard Stone 5%", "1x Everstone 5%", "1x Black Augurite 5%"]}, "cobblemon:p0526_gigalith": {"n": 526, "d": "Compressing the energy from its internal core lets it fire off an attack capable of blowing away a mountain.", "h": 17, "w": 2600, "dr": ["0-3x Raw Copper", "1x Hard Stone 10%", "1x Everstone 10%", "1x Black Augurite 10%"]}, "cobblemon:p0527_woobat": {"n": 527, "d": "The heart-shaped mark left on a body after a Woobat has been attached to it is said to bring good fortune.", "h": 4, "w": 21, "dr": ["1x Light Blue Wool", "1x Colbur Berry 2.5%"]}, "cobblemon:p0528_swoobat": {"n": 528, "d": "Anyone who comes into contact with the ultrasonic waves emitted by a courting male experiences a positive mood shift.", "h": 9, "w": 105, "dr": ["1-2x Light Blue Wool", "1x Colbur Berry 5%"]}, "cobblemon:p0529_drilbur": {"n": 529, "d": "By spinning its body, it can dig straight through the ground at a speed of 30 mph.", "h": 3, "w": 85, "dr": ["0-1x Dirt", "1x Soft Sand 2.5%", "1x Pinap Berry 2.5%"]}, "cobblemon:p0530_excadrill": {"n": 530, "d": "More than 300 feet below the surface, they build mazelike nests. Their activity can be destructive to subway tunnels.", "h": 7, "w": 404, "dr": ["0-2x Dirt", "1x Soft Sand 5%", "1x Pinap Berry 5%"]}, "cobblemon:p0531_audino": {"n": 531, "d": "It touches others with the feelers on its ears, using the sound of their heartbeats to tell how they are feeling.", "h": 11, "w": 310, "dr": ["1x Oran Berry 5%", "1x Fairy Feather 5%"]}, "cobblemon:p0532_timburr": {"n": 532, "d": "Always carrying squared logs, they help out with construction. As they grow, they carry bigger logs.", "h": 6, "w": 125, "dr": ["1x Muscle Band 2.5%", "1x Razz Berry 2.5%"]}, "cobblemon:p0533_gurdurr": {"n": 533, "d": "This Pokémon is so muscular and strongly built that even a group of wrestlers could not make it budge an inch.", "h": 12, "w": 400, "dr": ["1x Muscle Band 5%", "1x Razz Berry 5%"]}, "cobblemon:p0534_conkeldurr": {"n": 534, "d": "Rather than rely on force, they master moves that utilize the centrifugal force of spinning concrete.", "h": 14, "w": 870, "dr": ["1x Muscle Band 10%", "1x Razz Berry 10%"]}, "cobblemon:p0535_tympole": {"n": 535, "d": "By vibrating its cheeks, it emits sound waves imperceptible to humans. It uses the rhythm of these sounds to talk.", "h": 5, "w": 45, "dr": ["0-1x Clay Ball", "1x Persim Berry 2.5%"]}, "cobblemon:p0536_palpitoad": {"n": 536, "d": "It lives in the water and on land. It uses its long, sticky tongue to immobilize its opponents.", "h": 8, "w": 170, "dr": ["0-2x Clay Ball", "1x Persim Berry 5%"]}, "cobblemon:p0537_seismitoad": {"n": 537, "d": "They shoot paralyzing liquid from their head bumps. They use vibration to hurt their opponents.", "h": 15, "w": 620, "dr": ["0-3x Clay Ball", "1x Persim Berry 10%"]}, "cobblemon:p0538_throh": {"n": 538, "d": "When it encounters a foe bigger than itself, it wants to throw it. It changes belts as it gets stronger.", "h": 13, "w": 555, "dr": ["1x Black Belt 5%", "1x Razz Berry 5%", "1x Expert Belt 5%"]}, "cobblemon:p0539_sawk": {"n": 539, "d": "Tying their belts gets them pumped and makes their punches more destructive. Disturbing their training angers them.", "h": 14, "w": 510, "dr": ["1x Black Belt 5%", "1x Bluk Berry 5%", "1x Expert Belt 5%"]}, "cobblemon:p0540_sewaddle": {"n": 540, "d": "Since this Pokémon makes its own clothes out of leaves, it is a popular mascot for fashion designers.", "h": 3, "w": 25, "dr": ["0-1x String", "1x Mental Herb 2.5%", "1x Revival Herb 2.5%", "1x Coba Berry 2.5%"]}, "cobblemon:p0541_swadloon": {"n": 541, "d": "It protects itself from the cold by wrapping up in leaves. It stays on the move, eating leaves in forests.", "h": 5, "w": 73, "dr": ["0-2x String", "1x Mental Herb 5%", "1x Revival Herb 5%", "1x Coba Berry 5%"]}, "cobblemon:p0542_leavanny": {"n": 542, "d": "It keeps its eggs warm with heat from fermenting leaves. It also uses leaves to make warm wrappings for Sewaddle.", "h": 12, "w": 205, "dr": ["0-3x String", "1x Mental Herb 10%", "1x Revival Herb 10%", "1x Coba Berry 10%"]}, "cobblemon:p0543_venipede": {"n": 543, "d": "Its bite injects a potent poison, enough to paralyze large bird Pokémon that try to prey on it.", "h": 4, "w": 53, "dr": ["1x Poison Barb 2.5%", "1x Pecha Berry 2.5%"]}, "cobblemon:p0544_whirlipede": {"n": 544, "d": "It is usually motionless, but when attacked, it rotates at high speed and then crashes into its opponent.", "h": 12, "w": 585, "dr": ["1x Poison Barb 5%", "1x Pecha Berry 5%"]}, "cobblemon:p0545_scolipede": {"n": 545, "d": "With quick movements, it chases down its foes, attacking relentlessly with its horns until it prevails.", "h": 25, "w": 2005, "dr": ["1x Poison Barb 10%", "1x Pecha Berry 10%"]}, "cobblemon:p0546_cottonee": {"n": 546, "d": "Perhaps because they feel more at ease in a group, they stick to others they find. They end up looking like a cloud.", "h": 3, "w": 6, "dr": ["1x White Wool", "1x Kebia Berry 2.5%", "1x Absorb Bulb 2.5%"]}, "cobblemon:p0547_whimsicott": {"n": 547, "d": "Like the wind, it can slip through any gap, no matter how small. It leaves balls of white fluff behind.", "h": 7, "w": 66, "dr": ["1-2x White Wool", "1x Kebia Berry 5%", "1x Absorb Bulb 5%"]}, "cobblemon:p0548_petilil": {"n": 548, "d": "Since they prefer moist, nutrient-rich soil, the areas where Petilil live are known to be good for growing plants.", "h": 5, "w": 66, "dr": ["1x Revival Herb 2.5%", "1x Persim Berry 2.5%", "1x Absorb Bulb 2.5%"]}, "cobblemon:p0549_lilligant": {"n": 549, "d": "Even veteran Trainers face a challenge in getting its beautiful flower to bloom. This Pokémon is popular with celebrities.", "h": 11, "w": 163, "dr": ["1x Revival Herb 5%", "1x Persim Berry 5%", "1x Absorb Bulb 5%"]}, "cobblemon:p0550_basculin": {"n": 550, "d": "Its temperament is vicious and aggressive. This Pokémon is also full of vitality and can multiply rapidly before anyone notices.", "h": 10, "w": 180, "dr": ["1x Salmon", "1x Bone Meal 5%", "1x Deep Sea Tooth 5%"]}, "cobblemon:p0551_sandile": {"n": 551, "d": "They live buried in the sands of the desert. The sun-warmed sands prevent their body temperature from dropping.", "h": 7, "w": 152, "dr": ["1x Black Glasses 2.5%", "1x Tanga Berry 2.5%"]}, "cobblemon:p0552_krokorok": {"n": 552, "d": "The special membrane covering its eyes can sense the heat of objects, so it can see its surroundings even in darkness.", "h": 10, "w": 334, "dr": ["1x Black Glasses 5%", "1x Tanga Berry 5%"]}, "cobblemon:p0553_krookodile": {"n": 553, "d": "They never allow prey to escape. Their jaws are so powerful, they can crush the body of an automobile.", "h": 15, "w": 963, "dr": ["1x Black Glasses 10%", "1x Tanga Berry 10%"]}, "cobblemon:p0554_darumaka": {"n": 554, "d": "When it sleeps, it pulls its limbs into its body and its internal fire goes down to 1,100 degrees Fahrenheit.", "h": 6, "w": 375, "dr": ["1x Rawst Berry 2.5%"]}, "cobblemon:p0555_darmanitan": {"n": 555, "d": "Its internal fire burns at 2,500 degrees Fahrenheit, making enough power that it can destroy a dump truck with one punch.", "h": 13, "w": 929, "dr": ["1x Rawst Berry 5%"]}, "cobblemon:p0556_maractus": {"n": 556, "d": "Arid regions are their habitat. They move rhythmically, making a sound similar to maracas.", "h": 10, "w": 280, "dr": ["0-2x Cactus", "1x Grassy Seed 5%", "1x Miracle Seed 5%", "1x Sticky Barb 5%"]}, "cobblemon:p0557_dwebble": {"n": 557, "d": "When it finds a stone of a suitable size, it secretes a liquid from its mouth to open up a hole to crawl into.", "h": 3, "w": 145, "dr": ["0-1x Terracotta", "1x Hard Stone 2.5%"]}, "cobblemon:p0558_crustle": {"n": 558, "d": "Competing for territory, Crustle fight viciously. The one whose boulder is broken is the loser of the battle.", "h": 14, "w": 2000, "dr": ["0-2x Terracotta", "1x Hard Stone 5%"]}, "cobblemon:p0559_scraggy": {"n": 559, "d": "Proud of its sturdy skull, it suddenly headbutts everything, but its weight makes it unstable, too.", "h": 6, "w": 118, "dr": ["1x Black Belt 2.5%", "1x Shed Shell 2.5%", "1x Roseli Berry 2.5%"]}, "cobblemon:p0560_scrafty": {"n": 560, "d": "It can smash concrete blocks with its kicking attacks. The one with the biggest crest is the group leader.", "h": 11, "w": 300, "dr": ["1x Black Belt 5%", "1x Shed Shell 5%", "1x Roseli Berry 5%"]}, "cobblemon:p0561_sigilyph": {"n": 561, "d": "The guardians of an ancient city, they always fly the same route while keeping watch for invaders.", "h": 14, "w": 140, "dr": ["0-1x Ender Pearl", "1x Light Clay 5%", "1x Colbur Berry 5%"]}, "cobblemon:p0562_yamask": {"n": 562, "d": "Each of them carries a mask that used to be its face when it was human. Sometimes they look at it and cry.", "h": 5, "w": 15, "dr": ["1x Spell Tag 2.5%"]}, "cobblemon:p0563_cofagrigus": {"n": 563, "d": "Grave robbers who mistake them for real coffins and get too close end up trapped inside their bodies.", "h": 17, "w": 765, "dr": ["1x Spell Tag 5%"]}, "cobblemon:p0564_tirtouga": {"n": 564, "d": "Restored from a fossil, this Pokémon can dive to depths beyond half a mile.", "h": 7, "w": 165, "dr": ["0-2x Turtle Scute"]}, "cobblemon:p0565_carracosta": {"n": 565, "d": "It could knock out a foe with a slap from one of its developed front appendages and chew it up, shell or bones and all.", "h": 12, "w": 810, "dr": ["0-3x Turtle Scute"]}, "cobblemon:p0566_archen": {"n": 566, "d": "Said to be an ancestor of bird Pokémon, they were unable to fly and moved about by hopping from one branch to another.", "h": 5, "w": 95, "dr": ["0-2x Feather"]}, "cobblemon:p0567_archeops": {"n": 567, "d": "It runs better than it flies. It takes off into the sky by running at a speed of 25 mph.", "h": 14, "w": 320, "dr": ["0-3x Feather"]}, "cobblemon:p0568_trubbish": {"n": 568, "d": "Inhaling the gas they belch will make you sleep for a week. They prefer unsanitary places.", "h": 6, "w": 310, "dr": ["1x Black Sludge 2.5%", "1x Leftovers 2.5%", "1x Silk Scarf 2.5%", "1x Pecha Berry 2.5%"]}, "cobblemon:p0569_garbodor": {"n": 569, "d": "Consuming garbage makes new kinds of poison gases and liquids inside their bodies.", "h": 19, "w": 1073, "dr": ["1x Black Sludge 5%", "1x Leftovers 5%", "1x Silk Scarf 5%", "1x Pecha Berry 5%"]}, "cobblemon:p0570_zorua": {"n": 570, "d": "To protect themselves from danger, they hide their true identities by transforming into people and Pokémon.", "h": 7, "w": 125, "dr": ["1-3x Sweet Berries", "1x Colbur Berry 2.5%"]}, "cobblemon:p0571_zoroark": {"n": 571, "d": "Bonds between these Pokémon are very strong. It protects the safety of its pack by tricking its opponents.", "h": 16, "w": 811, "dr": ["2-4x Sweet Berries", "1x Roseli Berry 5%"]}, "cobblemon:p0572_minccino": {"n": 572, "d": "These Pokémon prefer a tidy habitat. They are always sweeping and dusting, using their tails as brooms.", "h": 4, "w": 58, "dr": ["1x Silk Scarf 2.5%", "1x Chesto Berry 2.5%"]}, "cobblemon:p0573_cinccino": {"n": 573, "d": "Cinccino's body is coated in a special oil that helps it deflect attacks, such as punches.", "h": 5, "w": 75, "dr": ["1x Silk Scarf 5%", "1x Chesto Berry 5%"]}, "cobblemon:p0574_gothita": {"n": 574, "d": "They intently observe both Trainers and Pokémon. Apparently, they are looking at something that only Gothita can see.", "h": 4, "w": 58, "dr": ["0-1x Ender Pearl", "1x Twisted Spoon 2.5%", "1x Persim Berry 2.5%"]}, "cobblemon:p0575_gothorita": {"n": 575, "d": "According to many old tales, it creates friends for itself by controlling sleeping children on starry nights.", "h": 7, "w": 180, "dr": ["0-2x Ender Pearl", "1x Twisted Spoon 5%", "1x Persim Berry 5%"]}, "cobblemon:p0576_gothitelle": {"n": 576, "d": "They can predict the future from the placement and movement of the stars. They can see Trainers' life spans.", "h": 15, "w": 440, "dr": ["0-3x Ender Pearl", "1x Twisted Spoon 10%", "1x Persim Berry 10%"]}, "cobblemon:p0577_solosis": {"n": 577, "d": "They drive away attackers by unleashing psychic power. They can use telepathy to talk with others.", "h": 3, "w": 10, "dr": ["0-1x Slime Ball", "1x Persim Berry 2.5%"]}, "cobblemon:p0578_duosion": {"n": 578, "d": "When their two divided brains think the same thoughts, their psychic power is maximized.", "h": 6, "w": 80, "dr": ["0-2x Slime Ball", "1x Persim Berry 5%"]}, "cobblemon:p0579_reuniclus": {"n": 579, "d": "When Reuniclus shake hands, a network forms between their brains, increasing their psychic power.", "h": 10, "w": 201, "dr": ["0-3x Slime Ball", "1x Persim Berry 10%"]}, "cobblemon:p0580_ducklett": {"n": 580, "d": "They are better at swimming than flying, and they happily eat their favorite food, peat moss, as they dive underwater.", "h": 5, "w": 55, "dr": ["0-1x Feather", "1x Chicken", "1x Wacan Berry 2.5%"]}, "cobblemon:p0581_swanna": {"n": 581, "d": "Swanna start to dance at dusk. The one dancing in the middle is the leader of the flock.", "h": 13, "w": 242, "dr": ["0-2x Feather", "1x Chicken", "1x Sharp Beak 2.5%", "1x Wacan Berry 5%"]}, "cobblemon:p0582_vanillite": {"n": 582, "d": "This Pokémon formed from icicles bathed in energy from the morning sun. It sleeps buried in snow.", "h": 4, "w": 57, "dr": ["0-1x Snowball", "1x Never-Melt Ice 2.5%", "1x Aspear Berry 2.5%"]}, "cobblemon:p0583_vanillish": {"n": 583, "d": "Snowy mountains are this Pokémon's habitat. During an ancient ice age, they moved to southern areas.", "h": 11, "w": 410, "dr": ["0-2x Snowball", "1x Never-Melt Ice 5%", "1x Aspear Berry 5%"]}, "cobblemon:p0584_vanilluxe": {"n": 584, "d": "Swallowing large amounts of water, they make snow clouds inside their bodies and, when angry, cause violent blizzards.", "h": 13, "w": 575, "dr": ["0-3x Snowball", "1x Never-Melt Ice 10%", "1x Aspear Berry 10%"]}, "cobblemon:p0585_deerling": {"n": 585, "d": "The turning of the seasons changes the color and scent of this Pokémon's fur. People use it to mark the seasons.", "h": 6, "w": 195, "dr": ["0-1x Leather", "1x Yache Berry 2.5%"]}, "cobblemon:p0586_sawsbuck": {"n": 586, "d": "They migrate according to the seasons, so some people call Sawsbuck the harbingers of spring.", "h": 19, "w": 925, "dr": ["0-2x Leather", "1x Yache Berry 5%"]}, "cobblemon:p0587_emolga": {"n": 587, "d": "The energy made in its cheeks' electric pouches is stored inside its membrane and released while it is gliding.", "h": 4, "w": 50, "dr": ["1x Yache Berry 5%"]}, "cobblemon:p0588_karrablast": {"n": 588, "d": "For some reason they evolve when they receive electrical energy while they are attacking Shelmet.", "h": 5, "w": 59, "dr": ["1x Occa Berry 2.5%"]}, "cobblemon:p0589_escavalier": {"n": 589, "d": "These Pokémon evolve by wearing the shell covering of a Shelmet. The steel armor protects their whole body.", "h": 10, "w": 330, "dr": ["1x Iron Helmet 5%", "1x Occa Berry 5%"]}, "cobblemon:p0590_foongus": {"n": 590, "d": "It lures Pokémon with its pattern that looks just like a Poké Ball, then releases poison spores.", "h": 2, "w": 10, "dr": ["0-1x Red Mushroom", "1x Cheri Berry 2.5%"]}, "cobblemon:p0591_amoonguss": {"n": 591, "d": "It lures prey close by dancing and waving its arm caps, which resemble Poké Balls, in a swaying motion.", "h": 6, "w": 105, "dr": ["0-2x Red Mushroom", "1x Cheri Berry 5%"]}, "cobblemon:p0592_frillish": {"n": 592, "d": "If its veil-like arms stun and wrap a foe, that foe will be dragged miles below the surface, never to return.", "h": 12, "w": 330, "dr": ["0-1x Glow Ink Sac", "1x Kasib Berry 2.5%"]}, "cobblemon:p0593_jellicent": {"n": 593, "d": "The fate of the ships and crew that wander into Jellicent's habitat: all sunken, all lost, all vanished.", "h": 22, "w": 1350, "dr": ["0-2x Glow Ink Sac", "1x Kasib Berry 5%"]}, "cobblemon:p0594_alomomola": {"n": 594, "d": "It gently holds injured and weak Pokémon in its fins. Its special membrane heals their wounds.", "h": 12, "w": 316, "dr": ["1x Cod", "1x Bone Meal 5%", "1x Deep Sea Scale 5%"]}, "cobblemon:p0595_joltik": {"n": 595, "d": "They attach themselves to large-bodied Pokémon and absorb static electricity, which they store in an electric pouch.", "h": 1, "w": 6, "dr": ["0-1x String", "0-1x Spider Eye", "0-1x Rotten Flesh", "1x Nanab Berry 2.5%"]}, "cobblemon:p0596_galvantula": {"n": 596, "d": "When attacked, they create an electric barrier by spitting out many electrically charged threads.", "h": 8, "w": 143, "dr": ["0-2x String", "0-2x Spider Eye", "0-2x Rotten Flesh", "1x Nanab Berry 5%"]}, "cobblemon:p0597_ferroseed": {"n": 597, "d": "It absorbs the iron it finds in the rock while clinging to the ceiling. It shoots spikes when in danger.", "h": 6, "w": 188, "dr": ["0-1x Raw Iron", "1x Occa Berry 2.5%", "1x Sticky Barb 2.5%"]}, "cobblemon:p0598_ferrothorn": {"n": 598, "d": "They attach themselves to cave ceilings, firing steel spikes at targets passing beneath them.", "h": 10, "w": 1100, "dr": ["0-2x Raw Iron", "1x Occa Berry 5%", "1x Sticky Barb 5%"]}, "cobblemon:p0599_klink": {"n": 599, "d": "The two minigears that mesh together are predetermined. Each will rebound from other minigears without meshing.", "h": 3, "w": 210, "dr": ["0-1x Raw Iron"]}, "cobblemon:p0600_klang": {"n": 600, "d": "A minigear and big gear comprise its body. If the minigear it launches at a foe doesn't return, it will die.", "h": 6, "w": 510, "dr": ["0-2x Raw Iron"]}, "cobblemon:p0601_klinklang": {"n": 601, "d": "Its red core functions as an energy tank. It fires the charged energy through its spikes into an area.", "h": 6, "w": 810, "dr": ["0-3x Raw Iron"]}, "cobblemon:p0602_tynamo": {"n": 602, "d": "One alone can emit only a trickle of electricity, so a group of them gathers to unleash a powerful electric shock.", "h": 2, "w": 3, "dr": ["0-1x Slime Ball"]}, "cobblemon:p0603_eelektrik": {"n": 603, "d": "These Pokémon have a big appetite. When they spot their prey, they attack it and paralyze it with electricity.", "h": 12, "w": 220, "dr": ["0-2x Slime Ball"]}, "cobblemon:p0604_eelektross": {"n": 604, "d": "They crawl out of the ocean using their arms. They will attack prey on shore and immediately drag it into the ocean.", "h": 21, "w": 805, "dr": ["0-3x Slime Ball"]}, "cobblemon:p0605_elgyem": {"n": 605, "d": "Rumors of its origin are linked to a UFO crash site in the desert 50 years ago.", "h": 5, "w": 90, "dr": ["0-1x Ender Pearl", "1x Light Clay 2.5%", "1x Colbur Berry 2.5%"]}, "cobblemon:p0606_beheeyem": {"n": 606, "d": "It uses psychic power to control an opponent's brain and tamper with its memories.", "h": 10, "w": 345, "dr": ["0-2x Ender Pearl", "1x Light Clay 5%", "1x Colbur Berry 5%"]}, "cobblemon:p0607_litwick": {"n": 607, "d": "Litwick shines a light that absorbs the life energy of people and Pokémon, which becomes the fuel that it burns.", "h": 3, "w": 31, "dr": ["0-1x Candle", "1x Dusk Stone 2.5%", "1x Rawst Berry 2.5%"]}, "cobblemon:p0608_lampent": {"n": 608, "d": "It arrives near the moment of death and steals spirit from the body.", "h": 6, "w": 130, "dr": ["1x Candle", "1x Dusk Stone 5%", "1x Rawst Berry 5%"]}, "cobblemon:p0609_chandelure": {"n": 609, "d": "The spirits burned up in its ominous flame lose their way and wander this world forever.", "h": 10, "w": 343, "dr": ["1-3x Candle", "1x Dusk Stone 10%", "1x Rawst Berry 10%"]}, "cobblemon:p0610_axew": {"n": 610, "d": "They mark their territory by leaving gashes in trees with their tusks. If a tusk breaks, a new one grows in quickly.", "h": 6, "w": 180, "dr": ["1x Dragon Fang 2.5%", "1x Haban Berry 2.5%"]}, "cobblemon:p0611_fraxure": {"n": 611, "d": "A broken tusk will not grow back, so it diligently sharpens its tusks on river rocks after the end of a battle.", "h": 10, "w": 360, "dr": ["1x Dragon Fang 5%", "1x Haban Berry 5%"]}, "cobblemon:p0612_haxorus": {"n": 612, "d": "Their sturdy tusks will stay sharp even if used to cut steel beams. These Pokémon are covered in hard armor.", "h": 18, "w": 1055, "dr": ["1x Dragon Fang 10%", "1x Haban Berry 10%"]}, "cobblemon:p0613_cubchoo": {"n": 613, "d": "Their snot is a barometer of health. When healthy, their snot is sticky and the power of their ice moves increases.", "h": 5, "w": 85, "dr": ["0-1x Snowball", "0-1x Cod", "1x Aspear Berry 2.5%"]}, "cobblemon:p0614_beartic": {"n": 614, "d": "It freezes its breath to create fangs and claws of ice to fight with. Cold northern areas are its habitat.", "h": 26, "w": 2600, "dr": ["0-2x Snowball", "0-2x Cod", "1x Aspear Berry 5%"]}, "cobblemon:p0615_cryogonal": {"n": 615, "d": "They are composed of ice crystals. They capture prey with chains of ice, freezing the prey at -148 degrees Fahrenheit.", "h": 11, "w": 1480, "dr": ["1x Never-Melt Ice 5%", "1x Aspear Berry 5%"]}, "cobblemon:p0616_shelmet": {"n": 616, "d": "It evolves when bathed in an electric-like energy along with Karrablast. The reason is still unknown.", "h": 4, "w": 77, "dr": ["1x Iron Helmet 2.5%"]}, "cobblemon:p0617_accelgor": {"n": 617, "d": "When its body dries out, it weakens. So, to prevent dehydration, it wraps itself in many layers of thin membrane.", "h": 8, "w": 253, "dr": ["1x Shed Shell 5%"]}, "cobblemon:p0618_stunfisk": {"n": 618, "d": "It conceals itself in the mud of the seashore. Then it waits. When prey touch it, it delivers a jolt of electricity.", "h": 7, "w": 110, "dr": ["0-2x Mud", "1x Passho Berry 5%"]}, "cobblemon:p0619_mienfoo": {"n": 619, "d": "In fights, they dominate with onslaughts of flowing, continuous attacks. With their sharp claws, they cut enemies.", "h": 9, "w": 200, "dr": ["1x Payapa Berry 2.5%", "1x Expert Belt 2.5%"]}, "cobblemon:p0620_mienshao": {"n": 620, "d": "Using the long fur on its arms like whips, it launches into combo attacks that, once started, no one can stop.", "h": 14, "w": 355, "dr": ["1x Payapa Berry 5%", "1x Expert Belt 5%"]}, "cobblemon:p0621_druddigon": {"n": 621, "d": "It warms its body by absorbing sunlight with its wings. When its body temperature falls, it can no longer move.", "h": 16, "w": 1390, "dr": ["1x Dragon Fang 5%", "1x Haban Berry 5%"]}, "cobblemon:p0622_golett": {"n": 622, "d": "Ancient science fashioned this Pokémon from clay. It's been active for thousands of years.", "h": 10, "w": 920, "dr": ["0-1x Clay Ball", "1x Light Clay 2.5%", "1x Colbur Berry 2.5%"]}, "cobblemon:p0623_golurk": {"n": 623, "d": "It flies across the sky at Mach speeds. Removing the seal on its chest makes its internal energy go out of control.", "h": 28, "w": 3300, "dr": ["0-2x Clay Ball", "1x Light Clay 5%", "1x Colbur Berry 5%"]}, "cobblemon:p0624_pawniard": {"n": 624, "d": "Ignoring their injuries, groups attack by sinking the blades that cover their bodies into their prey.", "h": 5, "w": 102, "dr": ["1x Iron Helmet 2.5%", "1x Chople Berry 2.5%"]}, "cobblemon:p0625_bisharp": {"n": 625, "d": "Bisharp pursues prey in the company of a large group of Pawniard. Then Bisharp finishes off the prey.", "h": 16, "w": 700, "dr": ["1x Iron Helmet 5%", "1x Chople Berry 5%"]}, "cobblemon:p0626_bouffalant": {"n": 626, "d": "Their fluffy fur absorbs damage, even if they strike foes with a fierce headbutt.", "h": 16, "w": 946, "dr": ["0-2x Leather", "1-3x Beef", "1-2x Brown Wool", "1x Wepear Berry 5%"]}, "cobblemon:p0627_rufflet": {"n": 627, "d": "They will challenge anything, even strong opponents, without fear. Their frequent fights help them become stronger.", "h": 5, "w": 105, "dr": ["0-1x Feather", "1x Chicken", "1x Razz Berry 2.5%"]}, "cobblemon:p0628_braviary": {"n": 628, "d": "They fight for their friends without any thought about danger to themselves. One can carry a car while flying.", "h": 15, "w": 410, "dr": ["0-2x Feather", "1x Chicken", "1x Sharp Beak 2.5%", "1x Razz Berry 5%"]}, "cobblemon:p0631_heatmor": {"n": 631, "d": "It draws in air through its tail, transforms it into fire, and uses it like a tongue. It melts Durant and eats them.", "h": 14, "w": 580, "dr": ["1x Flame Orb 5%", "1x Blaze Powder 5%", "1x Rawst Berry 5%"]}, "cobblemon:p0632_durant": {"n": 632, "d": "They attack in groups, covering themselves in steel armor to protect themselves from Heatmor.", "h": 3, "w": 330, "dr": ["0-1x Raw Iron", "1x Occa Berry 2.5%"]}, "cobblemon:p0633_deino": {"n": 633, "d": "Lacking sight, it's unaware of its surroundings, so it bumps into things and eats anything that moves.", "h": 8, "w": 173, "dr": ["0-1x Dragon Breath", "1x Roseli Berry 2.5%"]}, "cobblemon:p0634_zweilous": {"n": 634, "d": "After it has eaten up all the food in its territory, it moves to another area. Its two heads do not get along.", "h": 14, "w": 500, "dr": ["0-2x Dragon Breath", "1x Roseli Berry 5%"]}, "cobblemon:p0635_hydreigon": {"n": 635, "d": "It responds to movement by attacking. This scary, three-headed Pokémon devours everything in its path!", "h": 18, "w": 1600, "dr": ["0-3x Dragon Breath", "1x Roseli Berry 10%"]}, "cobblemon:p0636_larvesta": {"n": 636, "d": "The base of volcanoes is where they make their homes. They shoot fire from their five horns to repel attacking enemies.", "h": 11, "w": 288, "dr": ["0-1x String", "1x Blaze Powder 2.5%", "1x Silver Powder 2.5%", "1x Charti Berry 2.5%"]}, "cobblemon:p0637_volcarona": {"n": 637, "d": "When volcanic ash darkened the atmosphere, it is said that Volcarona's fire provided a replacement for the sun.", "h": 16, "w": 460, "dr": ["1x Blaze Powder 5%", "1x Silver Powder 5%", "1x Charti Berry 5%"]}, "cobblemon:p0650_chespin": {"n": 650, "d": "Such a thick shell of wood covers its head and back that even a direct hit from a truck wouldn't faze it.", "h": 4, "w": 90, "dr": ["1x Miracle Seed 5%"]}, "cobblemon:p0651_quilladin": {"n": 651, "d": "They strengthen their lower bodies by running into one another. They are very kind and won't start fights.", "h": 7, "w": 290, "dr": ["1x Miracle Seed 10%"]}, "cobblemon:p0652_chesnaught": {"n": 652, "d": "When it takes a defensive posture with its fists guarding its face, it could withstand a bomb blast.", "h": 16, "w": 900, "dr": ["1x Miracle Seed 25%"]}, "cobblemon:p0653_fennekin": {"n": 653, "d": "As it walks, it munches on a twig in place of a snack. It intimidates opponents by puffing hot air out of its ears.", "h": 4, "w": 94, "dr": ["0-1x Blaze Powder", "1x Charcoal Stick 5%"]}, "cobblemon:p0654_braixen": {"n": 654, "d": "When the twig is plucked from its tail, friction sets the twig alight. The flame is used to send signals to its allies.", "h": 10, "w": 145, "dr": ["1x Stick", "0-2x Blaze Powder", "1x Charcoal Stick 10%"]}, "cobblemon:p0655_delphox": {"n": 655, "d": "Using psychic power, it generates a fiery vortex of 5,400 degrees Fahrenheit, incinerating foes swept into this whirl of flame.", "h": 15, "w": 390, "dr": ["1x Stick", "0-3x Blaze Powder", "1x Charcoal Stick 25%"]}, "cobblemon:p0656_froakie": {"n": 656, "d": "It protects its skin by covering its body in delicate bubbles. Beneath its happy-go-lucky air, it keeps a watchful eye on its surroundings.", "h": 3, "w": 70, "dr": ["0-1x Pearlescent Froglight", "1x Mystic Water 5%"]}, "cobblemon:p0657_frogadier": {"n": 657, "d": "Its swiftness is unparalleled. It can scale a tower of more than 2,000 feet in a minute's time.", "h": 6, "w": 109, "dr": ["0-2x Pearlescent Froglight", "1x Mystic Water 10%"]}, "cobblemon:p0658_greninja": {"n": 658, "d": "It appears and vanishes with a ninja's grace. It toys with its enemies using swift movements, while slicing them with throwing stars of sharpest water.", "h": 15, "w": 400, "dr": ["0-3x Pearlescent Froglight", "1x Mystic Water 25%"]}, "cobblemon:p0659_bunnelby": {"n": 659, "d": "It has ears like shovels. Digging holes strengthens its ears so much that they can sever thick roots effortlessly.", "h": 4, "w": 50, "dr": ["1x Rabbit", "0-1x Rabbit Hide", "1x Rabbit Foot 2.5%", "1x Carrot 2.5%", "1x Chilan Berry 2.5%"]}, "cobblemon:p0660_diggersby": {"n": 660, "d": "As powerful as an excavator, its ears can reduce dense bedrock to rubble. When it's finished digging, it lounges lazily.", "h": 10, "w": 424, "dr": ["1x Rabbit", "0-2x Rabbit Hide", "1x Rabbit Foot 5%", "1x Carrot 5%", "1x Chilan Berry 5%"]}, "cobblemon:p0661_fletchling": {"n": 661, "d": "Despite the beauty of its lilting voice, it's merciless to intruders that enter its territory.", "h": 3, "w": 17, "dr": ["0-1x Feather", "1x Chicken", "1x Rawst Berry 2.5%"]}, "cobblemon:p0662_fletchinder": {"n": 662, "d": "The hotter the flame sac on its belly, the faster it can fly, but it takes some time to get the fire going.", "h": 7, "w": 160, "dr": ["0-2x Feather", "1x Chicken", "1x Sharp Beak 2.5%", "1x Rawst Berry 5%"]}, "cobblemon:p0663_talonflame": {"n": 663, "d": "When attacking prey, it can reach speeds of up to 310 mph. It finishes its prey off with a colossal kick.", "h": 12, "w": 245, "dr": ["0-3x Feather", "1x Chicken", "1x Sharp Beak 5%", "1x Rawst Berry 10%"]}, "cobblemon:p0664_scatterbug": {"n": 664, "d": "The powder that covers its body regulates its temperature, so it can live in any region or climate.", "h": 3, "w": 25, "dr": ["0-1x String", "1x Bright Powder 2.5%", "1x Cheri Berry 2.5%"]}, "cobblemon:p0665_spewpa": {"n": 665, "d": "The beaks of bird Pokémon can't begin to scratch its stalwart body. To defend itself, it spews powder.", "h": 3, "w": 84, "dr": ["0-2x String", "1x Bright Powder 2.5%", "1x Cheri Berry 2.5%"]}, "cobblemon:p0666_vivillon": {"n": 666, "d": "The patterns on this Pokémon's wings depend on the climate and topography of its habitat. It scatters colorful scales.", "h": 12, "w": 170, "dr": ["1x Bright Powder 5%", "1x Shed Shell 5%", "1x Cheri Berry 5%"]}, "cobblemon:p0667_litleo": {"n": 667, "d": "They set off on their own from their pride and live by themselves to become stronger. These hot-blooded Pokémon are quick to fight.", "h": 6, "w": 135, "dr": ["0-1x Rotten Flesh", "1x Blaze Powder 2.5%", "1x Rawst Berry 2.5%"]}, "cobblemon:p0668_pyroar": {"n": 668, "d": "With fiery breath of more than 10,000 degrees Fahrenheit, they viciously threaten any challenger. The females protect the pride's cubs.", "h": 15, "w": 815, "dr": ["0-2x Rotten Flesh", "1x Blaze Powder 5%", "1x Rawst Berry 5%"]}, "cobblemon:p0669_flabebe": {"n": 669, "d": "This Pokémon can draw forth the power hidden within blooming wild flowers. It is particularly fond of red flowers.", "h": 1, "w": 1, "dr": ["1x Poppy", "1x Kebia Berry 2.5%"]}, "cobblemon:p0670_floette": {"n": 670, "d": "This Pokémon draws forth what power is left in withered flowers to make them healthy again. It holds a red flower.", "h": 2, "w": 9, "dr": ["1x Poppy", "1x Kebia Berry 5%"]}, "cobblemon:p0671_florges": {"n": 671, "d": "This Pokémon creates an impressive flower garden in its territory. It draws forth the power of the red flowers around its neck.", "h": 11, "w": 100, "dr": ["0-3x Poppy", "1x Kebia Berry 10%"]}, "cobblemon:p0672_skiddo": {"n": 672, "d": "If it has sunshine and water, it doesn't need to eat, because it can generate energy from the leaves on its back.", "h": 9, "w": 310, "dr": ["1-2x Mutton", "1x Oran Berry 2.5%"]}, "cobblemon:p0673_gogoat": {"n": 673, "d": "They inhabit mountainous regions. The leader of the herd is decided by a battle of clashing horns.", "h": 17, "w": 910, "dr": ["1-3x Mutton", "1x Oran Berry 5%"]}, "cobblemon:p0674_pancham": {"n": 674, "d": "It does its level best to glare and pull a scary face, but it can't help grinning if anyone pats its head.", "h": 6, "w": 80, "dr": ["0-1x Bamboo", "1x Mental Herb 2.5%", "1x Roseli Berry 2.5%"]}, "cobblemon:p0675_pangoro": {"n": 675, "d": "It charges ahead and bashes its opponents like a berserker, uncaring about any hits it might take. Its arms are mighty enough to snap a telephone pole.", "h": 21, "w": 1360, "dr": ["0-2x Bamboo", "1x Mental Herb 5%", "1x Roseli Berry 5%"]}, "cobblemon:p0676_furfrou": {"n": 676, "d": "Left alone, its fur will grow longer and longer, but it will only allow someone it trusts to cut it.", "h": 12, "w": 280, "dr": ["0-2x Bone", "1-2x White Wool", "1x Silk Scarf 5%"]}, "cobblemon:p0677_espurr": {"n": 677, "d": "It has enough psychic energy to blast everything within 300 feet of itself, but it has no control over its power.", "h": 3, "w": 35, "dr": ["1x Colbur Berry 2.5%"]}, "cobblemon:p0678_meowstic": {"n": 678, "d": "The eyeball patterns on the interior of its ears emit psychic energy. It keeps the patterns tightly covered because that power is too immense.", "h": 6, "w": 85, "dr": ["1x Colbur Berry 5%"]}, "cobblemon:p0679_honedge": {"n": 679, "d": "If anyone dares to grab its hilt, it wraps a blue cloth around that person's arm and drains that person's life energy completely.", "h": 8, "w": 20, "dr": ["0-1x Iron Nugget", "1x Iron Sword 2.5%", "1x Dusk Stone 2.5%"]}, "cobblemon:p0680_doublade": {"n": 680, "d": "The complex attack patterns of its two swords are unstoppable, even for an opponent greatly accomplished at swordplay.", "h": 8, "w": 45, "dr": ["0-2x Iron Nugget", "1x Iron Sword 5%", "1x Dusk Stone 5%"]}, "cobblemon:p0681_aegislash": {"n": 681, "d": "Apparently, it can detect the innate qualities of leadership. According to legend, whoever it recognizes is destined to become king.", "h": 17, "w": 530, "dr": ["0-3x Iron Nugget", "1x Iron Sword 10%", "1x Dusk Stone 10%", "1x Ability Shield 10%"]}, "cobblemon:p0682_spritzee": {"n": 682, "d": "In the past, rather than using perfume, royal ladies carried a Spritzee that would waft a fragrance they liked.", "h": 2, "w": 5, "dr": ["1x Kebia Berry 2.5%", "1x Fairy Feather 2.5%"]}, "cobblemon:p0683_aromatisse": {"n": 683, "d": "Its scent is so overpowering that, unless a Trainer happens to really enjoy the smell, he or she will have a hard time walking alongside it.", "h": 8, "w": 155, "dr": ["1x Kebia Berry 5%", "1x Fairy Feather 5%"]}, "cobblemon:p0684_swirlix": {"n": 684, "d": "Because it eats nothing but sweets, its fur is as sticky sweet as cotton candy.", "h": 4, "w": 35, "dr": ["0-1x Sugar", "1x Cake 2.5%", "1x Babiri Berry 2.5%"]}, "cobblemon:p0685_slurpuff": {"n": 685, "d": "Its sense of smell is 100 million times better than a human's, so even the faintest scent tells it about everything in the area. It's like it can see with its nose!", "h": 8, "w": 50, "dr": ["0-2x Sugar", "1x Cake 5%", "1x Babiri Berry 5%"]}, "cobblemon:p0686_inkay": {"n": 686, "d": "It flashes the light-emitting spots on its body, which drains its opponent's will to fight. It takes the opportunity to scuttle away and hide.", "h": 4, "w": 35, "dr": ["0-1x Ink Sac", "1x Tanga Berry 2.5%"]}, "cobblemon:p0687_malamar": {"n": 687, "d": "It lures its prey close with hypnotic motions, then wraps its tentacles around it before finishing it off with digestive fluids.", "h": 15, "w": 470, "dr": ["0-2x Ink Sac", "1x Tanga Berry 5%"]}, "cobblemon:p0688_binacle": {"n": 688, "d": "They stretch and then contract, yanking their rocks along with them in bold hops. They eat seaweed that washes up on the shoreline.", "h": 5, "w": 310, "dr": ["1x Rindo Berry 2.5%"]}, "cobblemon:p0689_barbaracle": {"n": 689, "d": "Barbaracle's legs and hands have minds of their own, and they will move independently. But they usually follow the head's orders.", "h": 13, "w": 960, "dr": ["1x Rindo Berry 5%"]}, "cobblemon:p0690_skrelp": {"n": 690, "d": "It looks just like rotten kelp. It hides from foes while storing up power for its evolution.", "h": 5, "w": 73, "dr": ["0-1x Kelp", "1x Pecha Berry 2.5%"]}, "cobblemon:p0691_dragalge": {"n": 691, "d": "Tales are told of ships that wander into seas where Dragalge live, never to return.", "h": 18, "w": 815, "dr": ["0-2x Kelp", "1x Pecha Berry 5%"]}, "cobblemon:p0692_clauncher": {"n": 692, "d": "Through controlled explosions of internal gas, it can expel water like a pistol shot. At close distances, it can shatter rock.", "h": 5, "w": 83, "dr": []}, "cobblemon:p0693_clawitzer": {"n": 693, "d": "By expelling water from the nozzle in the back of its claw, it can move at a speed of 60 knots.", "h": 13, "w": 353, "dr": []}, "cobblemon:p0694_helioptile": {"n": 694, "d": "The frills on either side of its head have cells that generate electricity when exposed to sunlight.", "h": 5, "w": 60, "dr": []}, "cobblemon:p0695_heliolisk": {"n": 695, "d": "It stimulates its muscles with electricity, boosting the strength in its legs and enabling it to run 100 yards in five seconds.", "h": 10, "w": 210, "dr": []}, "cobblemon:p0696_tyrunt": {"n": 696, "d": "Its immense jaws have enough destructive force that it can chew up an automobile. It lived 100 million years ago.", "h": 8, "w": 260, "dr": ["1x Razor Fang 5%"]}, "cobblemon:p0697_tyrantrum": {"n": 697, "d": "Nothing could stop this Pokémon 100 million years ago, so it behaved like a king.", "h": 25, "w": 2700, "dr": ["1x Razor Fang 10%"]}, "cobblemon:p0698_amaura": {"n": 698, "d": "This calm Pokémon lived in a cold land where there were no violent predators like Tyrantrum.", "h": 13, "w": 252, "dr": ["1x Never-Melt Ice 5%"]}, "cobblemon:p0699_aurorus": {"n": 699, "d": "Using its diamond-shaped crystals, it can instantly create a wall of ice to block an opponent's attack.", "h": 27, "w": 2250, "dr": ["1x Never-Melt Ice 10%"]}, "cobblemon:p0700_sylveon": {"n": 700, "d": "It wraps its ribbonlike feelers around the arm of its beloved Trainer and walks with him or her.", "h": 10, "w": 235, "dr": ["1x Shiny Stone 25%", "1x Fairy Feather 10%"]}, "cobblemon:p0701_hawlucha": {"n": 701, "d": "With its wings, it controls its position in the air. It likes to attack from above, a maneuver that is difficult to defend against.", "h": 8, "w": 215, "dr": ["1x King's Rock 5%", "1x Coba Berry 5%", "1x Expert Belt 5%"]}, "cobblemon:p0702_dedenne": {"n": 702, "d": "It uses its tail to absorb electricity from power plants or from outlets in houses, and then it fires the electricity from its whiskers.", "h": 2, "w": 22, "dr": ["1x Cheri Berry 5%"]}, "cobblemon:p0703_carbink": {"n": 703, "d": "It has slept underground for hundreds of millions of years since its birth. It's occasionally found during the excavation of caves.", "h": 3, "w": 57, "dr": ["1x Diamond 5%", "1x Babiri Berry 5%", "1x Float Stone 5%"]}, "cobblemon:p0704_goomy": {"n": 704, "d": "It's covered in a slimy membrane that makes any punches or kicks slide off it harmlessly.", "h": 3, "w": 28, "dr": ["0-1x Slime Ball", "1x Shed Shell 2.5%", "1x Haban Berry 2.5%"]}, "cobblemon:p0705_sliggoo": {"n": 705, "d": "Its four horns are a high-performance radar system. It uses them to sense sounds and smells, rather than using ears or a nose.", "h": 8, "w": 175, "dr": ["0-2x Slime Ball", "1x Shed Shell 5%", "1x Haban Berry 5%"]}, "cobblemon:p0706_goodra": {"n": 706, "d": "It attacks with retractable horns. It throws a punch that's the equivalent of the force of a hundred pro boxers.", "h": 20, "w": 1505, "dr": ["0-3x Slime Ball", "1x Shed Shell 10%", "1x Haban Berry 10%"]}, "cobblemon:p0707_klefki": {"n": 707, "d": "It never lets go of a key that it likes, so people give it the keys to vaults and safes as a way to prevent crime.", "h": 2, "w": 30, "dr": ["1x Name Tag 5%"]}, "cobblemon:p0708_phantump": {"n": 708, "d": "According to old tales, these Pokémon are stumps possessed by the spirits of children who died while lost in the forest.", "h": 4, "w": 70, "dr": ["0-1x Jack O Lantern", "1x Spell Tag 2.5%", "1x Rawst Berry 2.5%"]}, "cobblemon:p0709_trevenant": {"n": 709, "d": "Using its roots as a nervous system, it controls the trees in the forest. It's kind to the Pokémon that reside in its body.", "h": 15, "w": 710, "dr": ["1x Jack O Lantern", "1x Spell Tag 5%", "1x Rawst Berry 5%"]}, "cobblemon:p0710_pumpkaboo": {"n": 710, "d": "It was recently discovered that the different varieties of Pumpkaboo vary not only in size but also in the size of the souls they collect.", "h": 4, "w": 50, "dr": ["0-1x Pumpkin Seeds", "1x Miracle Seed 2.5%", "1x Kasib Berry 2.5%"]}, "cobblemon:p0711_gourgeist": {"n": 711, "d": "Singing in eerie voices, they wander town streets on the night of the new moon. Anyone who hears their song is cursed.", "h": 9, "w": 125, "dr": ["0-2x Pumpkin Seeds", "1x Miracle Seed 5%", "1x Kasib Berry 5%"]}, "cobblemon:p0712_bergmite": {"n": 712, "d": "Using air of -150 degrees Fahrenheit, they freeze opponents solid. They live in herds above the snow line on mountains.", "h": 10, "w": 995, "dr": ["1x Never-Melt Ice 2.5%", "1x Aspear Berry 2.5%"]}, "cobblemon:p0713_avalugg": {"n": 713, "d": "The way several Bergmite huddle on its back makes it look like an aircraft carrier made of ice.", "h": 20, "w": 5050, "dr": ["1x Never-Melt Ice 5%", "1x Aspear Berry 5%"]}, "cobblemon:p0714_noibat": {"n": 714, "d": "Even a robust wrestler will become dizzy and unable to stand when exposed to its 200,000-hertz ultrasonic waves.", "h": 5, "w": 80, "dr": ["1x Phantom Membrane 2.5%", "1x Yache Berry 2.5%"]}, "cobblemon:p0715_noivern": {"n": 715, "d": "The ultrasonic waves it emits from its ears can reduce a large boulder to pebbles. It swoops out of the dark to attack.", "h": 15, "w": 850, "dr": ["1x Phantom Membrane 5%", "1x Yache Berry 5%"]}, "cobblemon:p0716_xerneas": {"n": 716, "d": "When the horns on its head shine in seven colors, it is said to be sharing everlasting life.", "h": 30, "w": 2150, "dr": []}, "cobblemon:p0722_rowlet": {"n": 722, "d": "It feels relaxed in tight, dark places and has been known to use its Trainer's pocket or bag as a nest.", "h": 3, "w": 15, "dr": ["0-1x Feather", "1x Chicken", "1x Miracle Seed 5%"]}, "cobblemon:p0723_dartrix": {"n": 723, "d": "Supremely sensitive to the presence of others, it can detect opponents standing behind it, flinging its sharp feathers to take them out.", "h": 7, "w": 160, "dr": ["0-2x Feather", "1x Chicken", "1x Miracle Seed 10%"]}, "cobblemon:p0724_decidueye": {"n": 724, "d": "Decidueye can nock and fire an arrow at an enemy in a tenth of a second, so its battles are decided in the blink of an eye.", "h": 16, "w": 366, "dr": ["0-3x Feather", "1x Chicken", "1x Miracle Seed 25%"]}, "cobblemon:p0725_litten": {"n": 725, "d": "Its coat regrows twice a year. When the time comes, Litten sets its own body on fire and burns away the old fur.", "h": 4, "w": 43, "dr": ["1x Charcoal Stick 5%", "1x Expert Belt 5%"]}, "cobblemon:p0726_torracat": {"n": 726, "d": "When its mane is standing on end, you can tell it's feeling good. When it isn't feeling well, its fur will lie down flat.", "h": 7, "w": 250, "dr": ["1x Charcoal Stick 10%", "1x Expert Belt 10%"]}, "cobblemon:p0727_incineroar": {"n": 727, "d": "When its fighting spirit is set alight, the flames around its waist become especially intense.", "h": 18, "w": 830, "dr": ["1x Charcoal Stick 25%", "1x Expert Belt 25%"]}, "cobblemon:p0728_popplio": {"n": 728, "d": "Popplio gets on top of its bouncy water balloons to jump higher. It's quite the acrobatic fighter!", "h": 4, "w": 75, "dr": ["1x Mystic Water 5%", "1x Throat Spray 5%"]}, "cobblemon:p0729_brionne": {"n": 729, "d": "It attacks by smacking its enemies with the exploding water balloons that it creates.", "h": 6, "w": 175, "dr": ["1x Mystic Water 10%", "1x Throat Spray 10%"]}, "cobblemon:p0730_primarina": {"n": 730, "d": "Also known as a songstress, it has a fantastical look on moonlit nights when it leads its colony in song.", "h": 18, "w": 440, "dr": ["1x Mystic Water 25%", "1x Throat Spray 25%"]}, "cobblemon:p0731_pikipek": {"n": 731, "d": "It may look spindly, but its neck muscles are heavy-duty. It can peck at a tree 16 times per second!", "h": 3, "w": 12, "dr": ["0-1x Feather", "1x Chicken"]}, "cobblemon:p0732_trumbeak": {"n": 732, "d": "From its mouth, it fires the seeds of berries it has eaten. The scattered seeds give rise to new plants.", "h": 6, "w": 148, "dr": ["0-2x Feather", "1x Chicken", "1x Sharp Beak 2.5%"]}, "cobblemon:p0733_toucannon": {"n": 733, "d": "Known for forming harmonious couples, this Pokémon is brought to wedding ceremonies as a good luck charm.", "h": 11, "w": 260, "dr": ["0-3x Feather", "1x Chicken", "1x Sharp Beak 5%"]}, "cobblemon:p0734_yungoos": {"n": 734, "d": "Although it will eat anything, it prefers fresh living things, so it marches down streets in search of prey.", "h": 4, "w": 60, "dr": ["1x Pecha Berry 2.5%"]}, "cobblemon:p0735_gumshoos": {"n": 735, "d": "Patient by nature, this Pokémon loses control of itself and pounces when it spots its favorite meal—Rattata!", "h": 7, "w": 142, "dr": ["1x Pecha Berry 5%"]}, "cobblemon:p0736_grubbin": {"n": 736, "d": "It spits a sticky thread to stop opponents in their tracks, and then it grabs them in its sharp, sturdy mandibles to take them down.", "h": 4, "w": 44, "dr": ["0-1x String", "1x Wepear Berry 2.5%", "1x Cell Battery 2.5%"]}, "cobblemon:p0737_charjabug": {"n": 737, "d": "Its stout shell provides excellent defense from attacks. It uses electricity on persistent opponents.", "h": 5, "w": 105, "dr": ["0-2x String", "1x Wepear Berry 5%", "1x Cell Battery 5%"]}, "cobblemon:p0738_vikavolt": {"n": 738, "d": "Vikavolt flusters opponents with acrobatic flying maneuvers. This creates an opening for it to deliver an electric beam attack.", "h": 15, "w": 450, "dr": ["1x Wepear Berry 10%", "1x Cell Battery 10%"]}, "cobblemon:p0739_crabrawler": {"n": 739, "d": "Crabrawler has been known to mistake Exeggutor for a coconut tree and climb it. The enraged Exeggutor shakes it off and stomps it.", "h": 6, "w": 70, "dr": ["1x Aspear Berry 2.5%"]}, "cobblemon:p0740_crabominable": {"n": 740, "d": "Before it stops to think, it just starts pummeling. There are records of its turning back avalanches with a flurry of punches.", "h": 17, "w": 1800, "dr": ["1x Aspear Berry 5%"]}, "cobblemon:p0742_cutiefly": {"n": 742, "d": "Cutiefly can pick up the auras of living things. It skillfully reads those auras to predict its foes' movements and make fools of them.", "h": 1, "w": 2, "dr": ["0-1x Honey Bottle", "1x Cheri Berry 2.5%"]}, "cobblemon:p0743_ribombee": {"n": 743, "d": "It can predict the weather from moisture levels and wind direction. Ribombee only reveals itself when there are a few clear days in a row.", "h": 2, "w": 5, "dr": ["0-2x Honey Bottle", "1x Cheri Berry 5%"]}, "cobblemon:p0744_rockruff": {"n": 744, "d": "When it rubs the rocks on its neck against you, that's proof of its love for you. However, the rocks are sharp, so the gesture is quite painful!", "h": 5, "w": 92, "dr": ["0-1x Bone", "0-1x Rotten Flesh", "1x Hard Stone 2.5%", "1x Babiri Berry 2.5%"]}, "cobblemon:p0745_lycanroc": {"n": 745, "d": "The rocks in its mane are sharper than a knife. Fragments that break off are treasured as good luck charms.", "h": 8, "w": 250, "dr": ["0-2x Bone", "0-2x Rotten Flesh", "1x Hard Stone 5%", "1x Babiri Berry 5%"]}, "cobblemon:p0746_wishiwashi": {"n": 746, "d": "When it's in a jam, its shining eyes attract others of its kind. The light from its eyes is visible almost 25 miles away.", "h": 2, "w": 3, "dr": ["1x Cod", "1x Bone Meal 5%"]}, "cobblemon:p0747_mareanie": {"n": 747, "d": "Aside from its head, its body parts regenerate quickly if they're cut off. After a good night's sleep, Mareanie is back to normal.", "h": 4, "w": 80, "dr": ["0-1x Slime Ball", "1x Poison Barb 2.5%", "1x Pecha Berry 2.5%"]}, "cobblemon:p0748_toxapex": {"n": 748, "d": "With its 12 legs, it creates a dome to shelter within. The flow of the tides doesn't affect Toxapex in there, so it's very comfortable.", "h": 7, "w": 145, "dr": ["0-2x Slime Ball", "1x Poison Barb 5%", "1x Pecha Berry 5%"]}, "cobblemon:p0749_mudbray": {"n": 749, "d": "Possessing mighty power, Mudbray can be loaded with 50 times its own body weight and will be totally fine.", "h": 10, "w": 1100, "dr": ["0-1x Leather", "0-1x Clay Ball", "1x Light Clay 2.5%", "1x Passho Berry 2.5%"]}, "cobblemon:p0750_mudsdale": {"n": 750, "d": "It can trudge mountain roads without rest for three days and three nights, all the while dragging a 10-ton load.", "h": 25, "w": 9200, "dr": ["0-2x Leather", "0-2x Clay Ball", "1x Light Clay 5%", "1x Passho Berry 5%"]}, "cobblemon:p0751_dewpider": {"n": 751, "d": "It can only breathe oxygen that has dissolved in water, so it wears a water bubble on its head when it walks around on land.", "h": 3, "w": 40, "dr": ["1x Mystic Water 2.5%", "1x Wepear Berry 2.5%"]}, "cobblemon:p0752_araquanid": {"n": 752, "d": "It has a habit of storing things it values in its water bubble. If its Trainer doesn't watch out, Araquanid will try to put them in its bubble!", "h": 18, "w": 820, "dr": ["1x Mystic Water 5%", "1x Wepear Berry 5%"]}, "cobblemon:p0753_fomantis": {"n": 753, "d": "It loves the sunshine. When it basks in the sunlight regularly, it grows up with vivid coloration.", "h": 3, "w": 15, "dr": ["1x Miracle Seed 2.5%", "1x Tanga Berry 2.5%"]}, "cobblemon:p0754_lurantis": {"n": 754, "d": "As it slashes into its enemies, it looks like it's dancing. Its elegant appearance has led some to call it the most glamorous Grass Pokémon.", "h": 9, "w": 185, "dr": ["1x Miracle Seed 5%", "1x Tanga Berry 5%"]}, "cobblemon:p0755_morelull": {"n": 755, "d": "It likes damp dark places. When night falls, the spores filling the caps of its mushrooms glow.", "h": 2, "w": 15, "dr": ["0-1x Brown Mushroom", "1x Luminous Moss 2.5%", "1x Bright Powder 2.5%", "1x Kebia Berry 2.5%"]}, "cobblemon:p0756_shiinotic": {"n": 756, "d": "When it starts fighting for territory with Parasect, the entire area gets completely coated in spores!", "h": 10, "w": 115, "dr": ["0-2x Brown Mushroom", "1x Luminous Moss 5%", "1x Bright Powder 5%", "1x Kebia Berry 5%"]}, "cobblemon:p0757_salandit": {"n": 757, "d": "It weakens opponents and sends them reeling with its poisonous gas. Salandit doesn't deal well with Spinda, since it's always reeling.", "h": 6, "w": 48, "dr": ["0-1x Rotten Flesh", "1x Shuca Berry 2.5%", "1x Smoke Ball 2.5%"]}, "cobblemon:p0758_salazzle": {"n": 758, "d": "It punishes Salandit that couldn't bring it food with a fierce slap of its flame-spewing palm.", "h": 12, "w": 222, "dr": ["0-2x Rotten Flesh", "1x Shuca Berry 5%", "1x Smoke Ball 5%"]}, "cobblemon:p0759_stufful": {"n": 759, "d": "Stufful hates to be hugged or touched in any way. It will squirm, thrash, and resist with amazing power.", "h": 5, "w": 68, "dr": ["1x Chople Berry 2.5%"]}, "cobblemon:p0760_bewear": {"n": 760, "d": "It waves its hands wildly in intimidation and warning. Life is over for anyone who doesn't run away as fast as possible.", "h": 21, "w": 1350, "dr": ["1x Chople Berry 5%"]}, "cobblemon:p0761_bounsweet": {"n": 761, "d": "It tries to resist being swallowed by a bird Pokémon by spinning the sepals on its head. It's usually a fruitless attempt.", "h": 3, "w": 32, "dr": ["1x Grassy Seed 2.5%", "1x Persim Berry 2.5%"]}, "cobblemon:p0762_steenee": {"n": 762, "d": "It bounces around, swinging the sepals on its head with abandon. They're quite painful when they smack you!", "h": 7, "w": 82, "dr": ["1x Grassy Seed 5%", "1x Persim Berry 5%"]}, "cobblemon:p0763_tsareena": {"n": 763, "d": "A Pokémon with an aggressive personality and a mastery of kicking, it cackles every time it kicks an opponent.", "h": 12, "w": 214, "dr": ["1x Grassy Seed 10%", "1x Persim Berry 10%"]}, "cobblemon:p0764_comfey": {"n": 764, "d": "It picks flowers and sticks them to its body with fluids it produces. The aroma that wafts from its petals has a healing effect.", "h": 1, "w": 3, "dr": ["1x Misty Seed 5%", "1x Kebia Berry 5%"]}, "cobblemon:p0767_wimpod": {"n": 767, "d": "An astonishingly cowardly Pokémon, Wimpod will whir its legs at high speeds to run away if anything comes near it.", "h": 5, "w": 120, "dr": ["1x Bluk Berry 2.5%"]}, "cobblemon:p0768_golisopod": {"n": 768, "d": "Its claws, which it can extend and retract at will, are its greatest weapons. Golisopod is sometimes accompanied by Wimpod.", "h": 20, "w": 1080, "dr": ["1x Bluk Berry 5%"]}, "cobblemon:p0769_sandygast": {"n": 769, "d": "If you build sand mounds when you're playing, destroy them before you go home, or they may get possessed and become Sandygast.", "h": 5, "w": 700, "dr": ["0-1x Sand", "1x Soft Sand 2.5%", "1x Passho Berry 2.5%"]}, "cobblemon:p0770_palossand": {"n": 770, "d": "Once it has whipped up a sandstorm to halt its opponents in their tracks, this terrifying Pokémon snatches away their vitality.", "h": 13, "w": 2500, "dr": ["0-2x Sand", "1x Soft Sand 5%", "1x Passho Berry 5%"]}, "cobblemon:p0771_pyukumuku": {"n": 771, "d": "Its entire body is covered in its own slime. If you accidentally step on one, you'll slip, and it will get mad and smack you!", "h": 3, "w": 12, "dr": ["0-2x Slime Ball"]}, "cobblemon:p0775_komala": {"n": 775, "d": "It remains asleep from birth to death as a result of the sedative properties of the leaves that form its diet.", "h": 4, "w": 199, "dr": ["1x Acacia Log", "1x Chesto Berry 5%"]}, "cobblemon:p0776_turtonator": {"n": 776, "d": "Its exploding shell poses a real danger but is sensitive to moisture. On rainy days, Turtonator takes silent refuge in caves.", "h": 20, "w": 2120, "dr": ["0-2x Turtle Scute", "1x Charcoal 5%", "1x Haban Berry 5%"]}, "cobblemon:p0777_togedemaru": {"n": 777, "d": "Its capacity to produce electricity is somewhat limited, so it gets charged up by letting lightning strike it!", "h": 3, "w": 33, "dr": ["1x Electric Seed 5%", "1x Shuca Berry 5%"]}, "cobblemon:p0778_mimikyu": {"n": 778, "d": "A gust of wind revealed what hides under this Pokémon's rag to a passing Trainer, who went home and died painfully that very night.", "h": 2, "w": 7, "dr": ["1x Spell Tag 5%", "1x Chesto Berry 5%"]}, "cobblemon:p0779_bruxish": {"n": 779, "d": "Its skin is thick enough to fend off Mareanie's spikes. With its robust teeth, Bruxish crunches up the spikes and eats them.", "h": 9, "w": 190, "dr": ["1x Cod", "1x Bone Meal 5%", "1x Razor Fang 5%"]}, "cobblemon:p0780_drampa": {"n": 780, "d": "It appears in towns and plays with the children. Drampa will protect kids when they're in danger, so their moms don't have to worry.", "h": 30, "w": 1850, "dr": ["1x Dragon Breath 5%", "1x Persim Berry 5%"]}, "cobblemon:p0781_dhelmise": {"n": 781, "d": "Its chain-like green seaweed can stretch outward for hundreds of yards. For some reason, it gets along well with Skrelp.", "h": 39, "w": 2100, "dr": ["0-2x Kelp", "0-2x Raw Iron"]}, "cobblemon:p0782_jangmoo": {"n": 782, "d": "It will never show an enemy its back in battle. Ancient warriors liked Jangmo-o for its valiant disposition and made it one of their own.", "h": 6, "w": 297, "dr": ["0-1x Dragon Scale", "1x Razor Claw 2.5%", "1x Roseli Berry 2.5%"]}, "cobblemon:p0783_hakamoo": {"n": 783, "d": "The scales it sheds can be molded and processed to make pots and pans. They conduct heat well, so they're a popular item.", "h": 12, "w": 470, "dr": ["0-2x Dragon Scale", "1x Razor Claw 5%", "1x Roseli Berry 2.5%"]}, "cobblemon:p0784_kommoo": {"n": 784, "d": "It battles valiantly with its fists, which are armored in steel scales. Kommo-o specializes in uppercuts.", "h": 16, "w": 782, "dr": ["0-3x Dragon Scale", "1x Razor Claw 10%", "1x Roseli Berry 2.5%"]}, "cobblemon:p0803_poipole": {"n": 803, "d": "An Ultra Beast that lives in a different world, it cackles wildly as it sprays its opponents with poison from the needles on its head.", "h": 6, "w": 18, "dr": ["1-2x Echo Shard"]}, "cobblemon:p0804_naganadel": {"n": 804, "d": "It stores hundreds of liters of poisonous liquid inside its body. It is one of the organisms known as UBs.", "h": 36, "w": 1500, "dr": ["1-3x Echo Shard"]}, "cobblemon:p0810_grookey": {"n": 810, "d": "When it uses its special stick to strike up a beat, the sound waves produced carry revitalizing energy to the plants and flowers in the area.", "h": 3, "w": 50, "dr": ["0-1x Stick", "1x Miracle Seed 5%"]}, "cobblemon:p0811_thwackey": {"n": 811, "d": "The faster a Thwackey can beat out a rhythm with its two sticks, the more respect it wins from its peers.", "h": 7, "w": 140, "dr": ["0-2x Stick", "1x Miracle Seed 10%"]}, "cobblemon:p0812_rillaboom": {"n": 812, "d": "By drumming, it taps into the power of its special tree stump. The roots of the stump follow its direction in battle.", "h": 21, "w": 900, "dr": ["1-2x Stick", "1x Miracle Seed 25%"]}, "cobblemon:p0813_scorbunny": {"n": 813, "d": "A warm-up of running around gets fire energy coursing through this Pokémon's body. Once that happens, it's ready to fight at full power.", "h": 3, "w": 45, "dr": ["0-1x Rabbit Hide", "1x Rabbit", "1x Rabbit Foot 5%", "1x Charcoal Stick 5%"]}, "cobblemon:p0814_raboot": {"n": 814, "d": "Its thick and fluffy fur protects it from the cold and enables it to use hotter fire moves.", "h": 6, "w": 90, "dr": ["0-2x Rabbit Hide", "1x Rabbit", "1x Rabbit Foot 10%", "1x Charcoal Stick 10%"]}, "cobblemon:p0815_cinderace": {"n": 815, "d": "It juggles a pebble with its feet, turning it into a burning soccer ball. Its shots strike opponents hard and leave them scorched.", "h": 14, "w": 330, "dr": ["0-3x Rabbit Hide", "1x Rabbit", "1x Rabbit Foot 25%", "1x Charcoal Stick 25%"]}, "cobblemon:p0816_sobble": {"n": 816, "d": "When scared, this Pokémon cries. Its tears pack the chemical punch of 100 onions, and attackers won't be able to resist weeping.", "h": 3, "w": 40, "dr": ["1x Mystic Water 5%"]}, "cobblemon:p0817_drizzile": {"n": 817, "d": "A clever combatant, this Pokémon battles using water balloons created with moisture secreted from its palms.", "h": 7, "w": 115, "dr": ["1x Mystic Water 10%"]}, "cobblemon:p0818_inteleon": {"n": 818, "d": "It has many hidden capabilities, such as fingertips that can shoot water and a membrane on its back that it can use to glide through the air.", "h": 19, "w": 452, "dr": ["1x Mystic Water 25%"]}, "cobblemon:p0819_skwovet": {"n": 819, "d": "It stores berries in its cheeks. When there are no berries to be found, Skwovet will stuff pebbles into its cheeks to stave off its cravings.", "h": 3, "w": 25, "dr": ["0-1x Oran Berry"]}, "cobblemon:p0820_greedent": {"n": 820, "d": "It stashes berries in its tail—so many berries that they fall out constantly. But this Pokémon is a bit slow-witted, so it doesn't notice the loss.", "h": 6, "w": 60, "dr": ["0-2x Oran Berry"]}, "cobblemon:p0821_rookidee": {"n": 821, "d": "It will bravely challenge any opponent, no matter how powerful. This Pokémon benefits from every battle—even a defeat increases its strength a bit.", "h": 2, "w": 18, "dr": ["0-1x Feather", "1x Chicken", "1x Wacan Berry 2.5%"]}, "cobblemon:p0822_corvisquire": {"n": 822, "d": "Smart enough to use tools in battle, these Pokémon have been seen picking up rocks and flinging them or using ropes to wrap up enemies.", "h": 8, "w": 160, "dr": ["0-2x Feather", "1x Chicken", "1x Sharp Beak 2.5%", "1x Wacan Berry 5%"]}, "cobblemon:p0823_corviknight": {"n": 823, "d": "Although its wings have partly turned to steel and become heavy as a result, this Pokémon flies through the skies with ease.", "h": 22, "w": 750, "dr": ["0-3x Feather", "1x Chicken", "1x Metal Coat 10%", "1x Wacan Berry 10%"]}, "cobblemon:p0827_nickit": {"n": 827, "d": "Aided by the soft pads on its feet, it silently raids the food stores of other Pokémon. It survives off its ill-gotten gains.", "h": 6, "w": 89, "dr": ["1-3x Sweet Berries", "1x Emerald 2.5%", "1x Roseli Berry 2.5%"]}, "cobblemon:p0828_thievul": {"n": 828, "d": "It secretly marks potential targets with a scent. By following the scent, it stalks its targets and steals from them when they least expect it.", "h": 12, "w": 199, "dr": ["2-4x Sweet Berries", "1x Emerald 5%", "1x Roseli Berry 5%"]}, "cobblemon:p0829_gossifleur": {"n": 829, "d": "It anchors itself in the ground with its single leg, then basks in the sun. After absorbing enough sunlight, its petals spread as it blooms brilliantly.", "h": 4, "w": 22, "dr": ["1x Coba Berry 2.5%"]}, "cobblemon:p0830_eldegoss": {"n": 830, "d": "The seeds attached to its cotton fluff are full of nutrients. It spreads them on the wind so that plants and other Pokémon can benefit from them.", "h": 5, "w": 25, "dr": ["1-2x White Wool", "1x Coba Berry 5%"]}, "cobblemon:p0831_wooloo": {"n": 831, "d": "Its curly fleece is such an effective cushion that this Pokémon could fall off a cliff and stand right back up at the bottom, unharmed.", "h": 6, "w": 60, "dr": ["1-2x Mutton", "1x White Wool"]}, "cobblemon:p0832_dubwool": {"n": 832, "d": "Weave a carpet from its springy wool, and you end up with something closer to a trampoline. You'll start to bounce the moment you set foot on it.", "h": 13, "w": 430, "dr": ["1-3x Mutton", "1-2x White Wool"]}, "cobblemon:p0833_chewtle": {"n": 833, "d": "Apparently the itch of its teething impels it to snap its jaws at anything in front of it.", "h": 3, "w": 85, "dr": ["0-1x Turtle Scute", "1x Rindo Berry 2.5%"]}, "cobblemon:p0834_drednaw": {"n": 834, "d": "With jaws that can shear through steel rods, this highly aggressive Pokémon chomps down on its unfortunate prey.", "h": 10, "w": 1155, "dr": ["0-2x Turtle Scute", "1x Rindo Berry 5%"]}, "cobblemon:p0835_yamper": {"n": 835, "d": "This gluttonous Pokémon only assists people with their work because it wants treats. As it runs, it crackles with electricity.", "h": 3, "w": 135, "dr": ["0-1x Bone", "1x Wepear Berry 2.5%"]}, "cobblemon:p0836_boltund": {"n": 836, "d": "This Pokémon generates electricity and channels it into its legs to keep them going strong. Boltund can run nonstop for three full days.", "h": 10, "w": 340, "dr": ["0-2x Bone", "1x Wepear Berry 5%"]}, "cobblemon:p0837_rolycoly": {"n": 837, "d": "Most of its body has the same composition as coal. Fittingly, this Pokémon was first discovered in coal mines about 400 years ago.", "h": 3, "w": 120, "dr": ["0-1x Coal", "1x Black Augurite 2.5%", "1x Passho Berry 2.5%"]}, "cobblemon:p0838_carkol": {"n": 838, "d": "The temperature inside its body increases when it experiences strong emotions. It rolls around frantically while spewing flames.", "h": 11, "w": 780, "dr": ["0-2x Coal", "1x Black Augurite 5%", "1x Passho Berry 5%"]}, "cobblemon:p0839_coalossal": {"n": 839, "d": "It's usually peaceful, but the vandalism of mines enrages it. Offenders will be incinerated with flames that reach 2,700 degrees Fahrenheit.", "h": 28, "w": 3105, "dr": ["0-3x Coal", "1x Black Augurite 10%", "1x Passho Berry 10%"]}, "cobblemon:p0840_applin": {"n": 840, "d": "It spends its entire life inside an apple. It hides from its natural enemies, bird Pokémon, by pretending it's just an apple and nothing more.", "h": 2, "w": 5, "dr": ["1x Apple", "1x Yache Berry 2.5%"]}, "cobblemon:p0841_flapple": {"n": 841, "d": "It ate a sour apple, and that induced its evolution. In its cheeks, it stores an acid capable of causing chemical burns.", "h": 3, "w": 10, "dr": ["1x Apple", "1x Yache Berry 5%"]}, "cobblemon:p0842_appletun": {"n": 842, "d": "Eating a sweet apple caused its evolution. A nectarous scent wafts from its body, luring in the bug Pokémon it preys on.", "h": 4, "w": 130, "dr": ["1x Apple", "1x Yache Berry 10%"]}, "cobblemon:p0843_silicobra": {"n": 843, "d": "As it digs, it swallows sand and stores it in its neck pouch. The pouch can hold more than 17 pounds of sand.", "h": 22, "w": 76, "dr": ["1x Soft Sand 2.5%"]}, "cobblemon:p0844_sandaconda": {"n": 844, "d": "When it contracts its body, over 220 pounds of sand sprays from its nose. If it ever runs out of sand, it becomes disheartened.", "h": 38, "w": 655, "dr": ["1x Soft Sand 5%"]}, "cobblemon:p0845_cramorant": {"n": 845, "d": "It's so strong that it can knock out some opponents in a single hit, but it also may forget what it's battling midfight.", "h": 8, "w": 180, "dr": ["0-2x Feather", "1x Chicken", "0-2x Cod", "1x Wacan Berry 5%"]}, "cobblemon:p0846_arrokuda": {"n": 846, "d": "If it sees any movement around it, this Pokémon charges for it straightaway, leading with its sharply pointed jaw. It's very proud of that jaw.", "h": 5, "w": 10, "dr": ["1x Salmon", "1x Bone Meal 5%"]}, "cobblemon:p0847_barraskewda": {"n": 847, "d": "This Pokémon has a jaw that's as sharp as a spear and as strong as steel. Apparently Barraskewda's flesh is surprisingly tasty, too.", "h": 13, "w": 300, "dr": ["1x Salmon", "1x Bone Meal 10%"]}, "cobblemon:p0848_toxel": {"n": 848, "d": "It stores poison in an internal poison sac and secretes that poison through its skin. If you touch this Pokémon, a tingling sensation follows.", "h": 4, "w": 110, "dr": ["1x Shuca Berry 2.5%"]}, "cobblemon:p0849_toxtricity": {"n": 849, "d": "When this Pokémon sounds as if it's strumming a guitar, it's actually clawing at the protrusions on its chest to generate electricity.", "h": 16, "w": 400, "dr": ["1x Shuca Berry 5%"]}, "cobblemon:p0850_sizzlipede": {"n": 850, "d": "It stores flammable gas in its body and uses it to generate heat. The yellow sections on its belly get particularly hot.", "h": 7, "w": 10, "dr": ["1x Blaze Powder 2.5%", "1x Charti Berry 2.5%"]}, "cobblemon:p0851_centiskorch": {"n": 851, "d": "When it heats up, its body temperature reaches about 1,500 degrees Fahrenheit. It lashes its body like a whip and launches itself at enemies.", "h": 30, "w": 1200, "dr": ["1x Blaze Powder 5%", "1x Charti Berry 5%"]}, "cobblemon:p0852_clobbopus": {"n": 852, "d": "It's very curious, but its means of investigating things is to try to punch them with its tentacles. The search for food is what brings it onto land.", "h": 6, "w": 40, "dr": ["1-3x Ink Sac", "1x Pinap Berry 2.5%"]}, "cobblemon:p0853_grapploct": {"n": 853, "d": "A body made up of nothing but muscle makes the grappling moves this Pokémon performs with its tentacles tremendously powerful.", "h": 16, "w": 390, "dr": ["2-4x Ink Sac", "1x Pinap Berry 5%"]}, "cobblemon:p0854_sinistea": {"n": 854, "d": "This Pokémon is said to have been born when a lonely spirit possessed a cold, leftover cup of tea.", "h": 1, "w": 2, "dr": ["1x Spell Tag 2.5%"]}, "cobblemon:p0855_polteageist": {"n": 855, "d": "This species lives in antique teapots. Most pots are forgeries, but on rare occasions, an authentic work is found.", "h": 2, "w": 4, "dr": ["1x Spell Tag 5%"]}, "cobblemon:p0856_hatenna": {"n": 856, "d": "Via the protrusion on its head, it senses other creatures' emotions. If you don't have a calm disposition, it will never warm up to you.", "h": 4, "w": 34, "dr": ["1x Babiri Berry 2.5%"]}, "cobblemon:p0857_hattrem": {"n": 857, "d": "No matter who you are, if you bring strong emotions near this Pokémon, it will silence you violently.", "h": 6, "w": 48, "dr": ["1x Babiri Berry 5%"]}, "cobblemon:p0858_hatterene": {"n": 858, "d": "It emits psychic power strong enough to cause headaches as a deterrent to the approach of others.", "h": 21, "w": 51, "dr": ["1x Babiri Berry 10%"]}, "cobblemon:p0859_impidimp": {"n": 859, "d": "Through its nose, it sucks in the emanations produced by people and Pokémon when they feel annoyed. It thrives off this negative energy.", "h": 4, "w": 55, "dr": ["1x Roseli Berry 2.5%"]}, "cobblemon:p0860_morgrem": {"n": 860, "d": "When it gets down on all fours as if to beg for forgiveness, it's trying to lure opponents in so that it can stab them with its spear-like hair.", "h": 8, "w": 125, "dr": ["1x Roseli Berry 5%"]}, "cobblemon:p0861_grimmsnarl": {"n": 861, "d": "With the hair wrapped around its body helping to enhance its muscles, this Pokémon can overwhelm even Machamp.", "h": 15, "w": 610, "dr": ["1x Roseli Berry 10%"]}, "cobblemon:p0862_obstagoon": {"n": 862, "d": "Its voice is staggering in volume. Obstagoon has a tendency to take on a threatening posture and shout—this move is known as Obstruct.", "h": 16, "w": 460, "dr": ["1x Chople Berry 10%"]}, "cobblemon:p0863_perrserker": {"n": 863, "d": "What appears to be an iron helmet is actually hardened hair. This Pokémon lives for the thrill of battle.", "h": 8, "w": 280, "dr": ["1x Razor Claw 5%", "1x Wepear Berry 5%"]}, "cobblemon:p0864_cursola": {"n": 864, "d": "Its shell is overflowing with its heightened otherworldly energy. The ectoplasm serves as protection for this Pokémon's core spirit.", "h": 10, "w": 4, "dr": ["1x Kasib Berry 5%"]}, "cobblemon:p0865_sirfetchd": {"n": 865, "d": "Only Farfetch'd that have survived many battles can attain this evolution. When this Pokémon's leek withers, it will retire from combat.", "h": 8, "w": 1170, "dr": ["0-2x Feather", "1x Chicken", "1x Medicinal Leek", "1x Coba Berry 5%"]}, "cobblemon:p0866_mrrime": {"n": 866, "d": "It's highly skilled at tap-dancing. It waves its cane of ice in time with its graceful movements.", "h": 15, "w": 582, "dr": ["1x Aspear Berry 10%"]}, "cobblemon:p0867_runerigus": {"n": 867, "d": "A powerful curse was woven into an ancient painting. After absorbing the spirit of a Yamask, the painting began to move.", "h": 16, "w": 666, "dr": ["1x Kasib Berry 5%"]}, "cobblemon:p0868_milcery": {"n": 868, "d": "This Pokémon was born from sweet-smelling particles in the air. Its body is made of cream.", "h": 2, "w": 3, "dr": ["0-1x Sugar"]}, "cobblemon:p0869_alcremie": {"n": 869, "d": "When it trusts a Trainer, it will treat them to berries it's decorated with cream.", "h": 3, "w": 5, "dr": ["0-2x Sugar", "1x Cake 5%"]}, "cobblemon:p0870_falinks": {"n": 870, "d": "Five of them are troopers, and one is the brass. The brass's orders are absolute.", "h": 30, "w": 620, "dr": ["1x Golden Helmet 5%", "1x Nanab Berry 5%"]}, "cobblemon:p0871_pincurchin": {"n": 871, "d": "It feeds on seaweed, using its teeth to scrape it off rocks. Electric current flows from the tips of its spines.", "h": 3, "w": 10, "dr": []}, "cobblemon:p0872_snom": {"n": 872, "d": "It spits out thread imbued with a frigid sort of energy and uses it to tie its body to branches, disguising itself as an icicle while it sleeps.", "h": 3, "w": 38, "dr": ["0-1x Snowball", "1x Silver Powder 2.5%", "1x Charti Berry 2.5%"]}, "cobblemon:p0873_frosmoth": {"n": 873, "d": "Icy scales fall from its wings like snow as it flies over fields and mountains. The temperature of its wings is less than −290 degrees Fahrenheit.", "h": 13, "w": 420, "dr": ["0-2x Snowball", "1x Silver Powder 5%", "1x Charti Berry 5%"]}, "cobblemon:p0874_stonjourner": {"n": 874, "d": "It stands in grasslands, watching the sun's descent from zenith to horizon. This Pokémon has a talent for delivering dynamic kicks.", "h": 25, "w": 5200, "dr": ["2x Stone", "1x Luminous Moss 5%"]}, "cobblemon:p0875_eiscue": {"n": 875, "d": "It drifted in on the flow of ocean waters from a frigid place. It keeps its head iced constantly to make sure it stays nice and cold.", "h": 14, "w": 890, "dr": ["0-1x Feather", "1x Chicken", "0-1x Cod", "1x Blue Ice", "1x Aspear Berry 5%"]}, "cobblemon:p0876_indeedee": {"n": 876, "d": "It uses the horns on its head to sense the emotions of others. Males will act as valets for those they serve, looking after their every need.", "h": 9, "w": 280, "dr": ["1x Room Service 5%", "1x Bluk Berry 5%"]}, "cobblemon:p0877_morpeko": {"n": 877, "d": "As it eats the seeds stored up in its pocket-like pouches, this Pokémon is not just satisfying its constant hunger. It's also generating electricity.", "h": 3, "w": 30, "dr": ["1x Roseli Berry 5%"]}, "cobblemon:p0878_cufant": {"n": 878, "d": "It digs up the ground with its trunk. It's also very strong, being able to carry loads of over five tons without any problem at all.", "h": 12, "w": 1000, "dr": ["0-1x Raw Copper", "1x Lagging Tail 2.5%", "1x Nanab Berry 2.5%"]}, "cobblemon:p0879_copperajah": {"n": 879, "d": "They came over from another region long ago and worked together with humans. Their green skin is resistant to water.", "h": 30, "w": 6500, "dr": ["0-2x Raw Copper", "1x Lagging Tail 5%", "1x Nanab Berry 5%"]}, "cobblemon:p0880_dracozolt": {"n": 880, "d": "In ancient times, it was unbeatable thanks to its powerful lower body, but it went extinct anyway after it depleted all its plant-based food sources.", "h": 18, "w": 1900, "dr": ["0-2x Bone", "0-2x Feather"]}, "cobblemon:p0881_arctozolt": {"n": 881, "d": "The shaking of its freezing upper half is what generates its electricity. It has a hard time walking around.", "h": 23, "w": 1500, "dr": ["0-2x Bone", "0-2x Feather"]}, "cobblemon:p0882_dracovish": {"n": 882, "d": "Powerful legs and jaws made it the apex predator of its time. Its own overhunting of its prey was what drove it to extinction.", "h": 23, "w": 2150, "dr": ["0-2x Bone", "1x Cod"]}, "cobblemon:p0883_arctovish": {"n": 883, "d": "Though it's able to capture prey by freezing its surroundings, it has trouble eating the prey afterward because its mouth is on top of its head.", "h": 20, "w": 1750, "dr": ["0-2x Bone", "1x Cod"]}, "cobblemon:p0884_duraludon": {"n": 884, "d": "Its body resembles polished metal, and it's both lightweight and strong. The only drawback is that it rusts easily.", "h": 18, "w": 400, "dr": ["0-1x Iron Ingot"]}, "cobblemon:p0885_dreepy": {"n": 885, "d": "After being reborn as a ghost Pokémon, Dreepy wanders the areas it used to inhabit back when it was alive in prehistoric seas.", "h": 5, "w": 20, "dr": ["1x Phantom Membrane 2.5%", "1x Haban Berry 2.5%"]}, "cobblemon:p0886_drakloak": {"n": 886, "d": "It's capable of flying faster than 120 mph. It battles alongside Dreepy and dotes on them until they successfully evolve.", "h": 14, "w": 110, "dr": ["1x Phantom Membrane 5%", "1x Haban Berry 5%"]}, "cobblemon:p0887_dragapult": {"n": 887, "d": "When it isn't battling, it keeps Dreepy in the holes on its horns. Once a fight starts, it launches the Dreepy like supersonic missiles.", "h": 30, "w": 500, "dr": ["1x Phantom Membrane 10%", "1x Haban Berry 10%"]}, "cobblemon:p0890_eternatus": {"n": 890, "d": "It was inside a meteorite that fell 20,000 years ago. There seems to be a connection between this Pokémon and the Dynamax phenomenon.", "h": 200, "w": 9500, "dr": []}, "cobblemon:p0893_zarude": {"n": 893, "d": "Within dense forests, this Pokémon lives in a pack with others of its kind. It's incredibly aggressive, and the other Pokémon of the forest fear it.", "h": 18, "w": 700, "dr": []}, "cobblemon:p0894_regieleki": {"n": 894, "d": "This Pokémon is a cluster of electrical energy. It's said that removing the rings on Regieleki's body will unleash the Pokémon's latent power.", "h": 12, "w": 1450, "dr": []}, "cobblemon:p0895_regidrago": {"n": 895, "d": "An academic theory proposes that Regidrago's arms were once the head of an ancient dragon Pokémon. The theory remains unproven.", "h": 21, "w": 2000, "dr": []}, "cobblemon:p0899_wyrdeer": {"n": 899, "d": "The black orbs shine with an uncanny light when the Pokémon is erecting invisible barriers. The fur shed from its beard retains heat well and is a highly useful material for winter clothing.", "h": 18, "w": 951, "dr": ["0-2x Leather", "1x Persim Berry 5%"]}, "cobblemon:p0900_kleavor": {"n": 900, "d": "Parts of its body turned to stone when it evolved thanks to an extremely rare ore found in volcanic areas.", "h": 18, "w": 890, "dr": ["0-2x Stone Axe", "1x Wepear Berry 5%"]}, "cobblemon:p0901_ursaluna": {"n": 901, "d": "I believe it was Hisui's swampy terrain that gave Ursaluna its burly physique and newfound capacity to manipulate peat at will.", "h": 24, "w": 2900, "dr": ["3-5x Sweet Berries", "1x Honey Bottle 10%", "1x Peat Block 10%", "1x Oran Berry 10%"]}, "cobblemon:p0902_basculegion": {"n": 902, "d": "This Pokémon is cloaked in the souls of its comrades who perished during a punishing journey to the river of their birth.", "h": 30, "w": 1100, "dr": ["1x Salmon", "1x Bone Meal 5%"]}, "cobblemon:p0903_sneasler": {"n": 903, "d": "Because of Sneasler's virulent poison and daunting physical prowess, no other species could hope to best it on the frozen highlands. Preferring solitude, this species does not form packs.", "h": 13, "w": 430, "dr": ["1x Razor Claw 5%", "1x Poison Barb 5%", "1x Payapa Berry 5%"]}, "cobblemon:p0904_overqwil": {"n": 904, "d": "Overqwil's poisonous spikes will reflexively react even while Overqwil sleeps, stabbing any moving thing that approaches.", "h": 25, "w": 605, "dr": ["1x Pufferfish", "0-2x Prismarine Shard", "1x Poison Barb 5%"]}, "cobblemon:p0906_sprigatito": {"n": 906, "d": "Its fluffy fur is similar in composition to plants. This Pokémon frequently washes its face to keep it from drying out.", "h": 4, "w": 41, "dr": ["1x Miracle Seed 5%"]}, "cobblemon:p0907_floragato": {"n": 907, "d": "Floragato deftly wields the vine hidden beneath its long fur, slamming the hard flower bud against its opponents.", "h": 9, "w": 122, "dr": ["1x Miracle Seed 10%"]}, "cobblemon:p0908_meowscarada": {"n": 908, "d": "This Pokémon uses the reflective fur lining its cape to camouflage the stem of its flower, creating the illusion that the flower is floating.", "h": 15, "w": 312, "dr": ["1x Miracle Seed 25%"]}, "cobblemon:p0909_fuecoco": {"n": 909, "d": "It lies on warm rocks and uses the heat absorbed by its square-shaped scales to create fire energy.", "h": 4, "w": 98, "dr": ["1x Charcoal Stick 5%"]}, "cobblemon:p0910_crocalor": {"n": 910, "d": "The combination of Crocalor's fire energy and overflowing vitality has caused an egg-shaped fireball to appear on the Pokémon's head.", "h": 10, "w": 307, "dr": ["1x Charcoal Stick 10%"]}, "cobblemon:p0911_skeledirge": {"n": 911, "d": "The fiery bird changes shape when Skeledirge sings. Rumor has it that the bird was born when the fireball on Skeledirge's head gained a soul.", "h": 16, "w": 3265, "dr": ["1x Charcoal Stick 25%"]}, "cobblemon:p0912_quaxly": {"n": 912, "d": "Its strong legs let it easily swim around in even fast-flowing rivers. It likes to keep things tidy and is prone to overthinking things.", "h": 5, "w": 61, "dr": ["1x Mystic Water 5%"]}, "cobblemon:p0913_quaxwell": {"n": 913, "d": "These Pokémon constantly run through shallow waters to train their legs, then compete with each other to see which of them kicks most gracefully.", "h": 12, "w": 215, "dr": ["1x Mystic Water 10%"]}, "cobblemon:p0914_quaquaval": {"n": 914, "d": "A single kick from a Quaquaval can send a truck rolling. This Pokémon uses its powerful legs to perform striking dances from far-off lands.", "h": 18, "w": 619, "dr": ["1x Mystic Water 25%"]}, "cobblemon:p0915_lechonk": {"n": 915, "d": "It searches for food all day. It possesses a keen sense of smell but doesn't use it for anything other than foraging.", "h": 5, "w": 102, "dr": ["1-2x Porkchop", "1x Oran Berry 2.5%"]}, "cobblemon:p0916_oinkologne": {"n": 916, "d": "Oinkologne is proud of its fine, glossy skin. It emits a concentrated scent from the tip of its tail.", "h": 10, "w": 1200, "dr": ["1-3x Porkchop", "1x Oran Berry 5%"]}, "cobblemon:p0917_tarountula": {"n": 917, "d": "The ball of threads wrapped around its body is elastic enough to deflect the scythes of Scyther, this Pokémon's natural enemy.", "h": 3, "w": 40, "dr": ["0-1x String", "0-1x Spider Eye"]}, "cobblemon:p0918_spidops": {"n": 918, "d": "It clings to branches and ceilings using its threads and moves without a sound. It takes out its prey before the prey even notices it.", "h": 10, "w": 165, "dr": ["0-2x String", "0-2x Spider Eye"]}, "cobblemon:p0919_nymble": {"n": 919, "d": "It has its third set of legs folded up. When it's in a tough spot, this Pokémon jumps over 30 feet using the strength of its legs.", "h": 2, "w": 10, "dr": ["1x Coba Berry 2.5%"]}, "cobblemon:p0920_lokix": {"n": 920, "d": "When it decides to fight all out, it stands on its previously folded legs to enter Showdown Mode. It neutralizes its enemies in short order.", "h": 10, "w": 175, "dr": ["1x Coba Berry 5%"]}, "cobblemon:p0924_tandemaus": {"n": 924, "d": "Exhibiting great teamwork, they use their incisors to cut pieces out of any material that might be useful for a nest, then make off with them.", "h": 3, "w": 18, "dr": ["0-1x Wheat Seeds", "1x Chilan Berry 2.5%"]}, "cobblemon:p0925_maushold": {"n": 925, "d": "They build huge nests with many rooms that are used for different purposes, such as eating and sleeping.", "h": 3, "w": 23, "dr": ["0-2x Wheat Seeds", "1x Chilan Berry 5%"]}, "cobblemon:p0926_fidough": {"n": 926, "d": "This Pokémon is smooth and moist to the touch. Yeast in Fidough's breath induces fermentation in the Pokémon's vicinity.", "h": 3, "w": 109, "dr": ["0-1x Bread", "1x Nanab Berry 2.5%"]}, "cobblemon:p0927_dachsbun": {"n": 927, "d": "The pleasant aroma that emanates from this Pokémon's body helps wheat grow, so Dachsbun has been treasured by farming villages.", "h": 5, "w": 149, "dr": ["0-2x Bread", "1x Nanab Berry 5%"]}, "cobblemon:p0928_smoliv": {"n": 928, "d": "It protects itself from enemies by emitting oil from the fruit on its head. This oil is bitter and astringent enough to make someone flinch.", "h": 3, "w": 65, "dr": ["1x Big Root 2.5%", "1x Kebia Berry 2.5%"]}, "cobblemon:p0929_dolliv": {"n": 929, "d": "Dolliv shares its tasty, fresh-scented oil with others. This species has coexisted with humans since times long gone.", "h": 6, "w": 119, "dr": ["1x Big Root 5%", "1x Kebia Berry 5%"]}, "cobblemon:p0930_arboliva": {"n": 930, "d": "This calm Pokémon is very compassionate. It will share its delicious, nutrient-rich oil with weakened Pokémon.", "h": 14, "w": 482, "dr": ["1x Big Root 10%", "1x Kebia Berry 10%"]}, "cobblemon:p0931_squawkabilly": {"n": 931, "d": "These Pokémon prefer to live in cities. They form flocks based on the color of their feathers, and they fight over territory.", "h": 6, "w": 24, "dr": ["0-2x Feather", "1x Chicken", "1x Chilan Berry 5%"]}, "cobblemon:p0932_nacli": {"n": 932, "d": "It was born in a layer of rock salt deep under the earth. This species was particularly treasured in the old days, as they would share precious salt.", "h": 4, "w": 160, "dr": ["0-1x Calcite", "1x Passho Berry 2.5%"]}, "cobblemon:p0933_naclstack": {"n": 933, "d": "This Pokémon dry cures its prey by spraying salt over them. The curing process steals away the water in the prey's body.", "h": 6, "w": 1050, "dr": ["0-2x Calcite", "1x Passho Berry 5%"]}, "cobblemon:p0934_garganacl": {"n": 934, "d": "Garganacl will rub its fingertips together and sprinkle injured Pokémon with salt. Even severe wounds will promptly heal afterward.", "h": 23, "w": 2400, "dr": ["0-3x Calcite", "1x Passho Berry 10%"]}, "cobblemon:p0935_charcadet": {"n": 935, "d": "Burnt charcoal came to life and became a Pokémon. Possessing a fiery fighting spirit, Charcadet will battle even tough opponents.", "h": 6, "w": 105, "dr": ["0-2x Charcoal", "1x Charcoal Stick 2.5%", "1x Rawst Berry 2.5%"]}, "cobblemon:p0936_armarouge": {"n": 936, "d": "Armarouge evolved through the use of a set of armor that belonged to a distinguished warrior. This Pokémon is incredibly loyal.", "h": 15, "w": 850, "dr": ["0-2x Charcoal", "1x Charcoal Stick 5%", "1x Auspicious Armor 5%", "1x Rawst Berry 5%"]}, "cobblemon:p0937_ceruledge": {"n": 937, "d": "The fiery blades on its arms burn fiercely with the lingering resentment of a sword wielder who fell before accomplishing their goal.", "h": 16, "w": 620, "dr": ["0-2x Charcoal", "1x Charcoal Stick 5%", "1x Malicious Armor 5%", "1x Rawst Berry 5%"]}, "cobblemon:p0938_tadbulb": {"n": 938, "d": "Tadbulb shakes its tail to generate electricity. If it senses danger, it will make its head blink on and off to alert its allies.", "h": 3, "w": 4, "dr": ["1x Ochre Froglight 2.5%", "1x Wepear Berry 2.5%"]}, "cobblemon:p0939_bellibolt": {"n": 939, "d": "When this Pokémon expands and contracts its wobbly body, the belly-button dynamo in its stomach produces a huge amount of electricity.", "h": 12, "w": 1130, "dr": ["1x Ochre Froglight 5%", "1x Wepear Berry 5%"]}, "cobblemon:p0940_wattrel": {"n": 940, "d": "When its wings catch the wind, the bones within produce electricity. This Pokémon dives into the ocean, catching prey by electrocuting them.", "h": 4, "w": 36, "dr": ["0-1x Feather", "1x Chicken", "1x Razz Berry 2.5%"]}, "cobblemon:p0941_kilowattrel": {"n": 941, "d": "Kilowattrel inflates its throat sac to amplify its electricity. By riding the wind, this Pokémon can fly over 430 miles in a day.", "h": 14, "w": 386, "dr": ["0-2x Feather", "1x Chicken", "1x Sharp Beak 2.5%", "1x Razz Berry 5%"]}, "cobblemon:p0942_maschiff": {"n": 942, "d": "It always scowls in an attempt to make opponents take it seriously, but even crying children will burst into laughter when they see Maschiff's face.", "h": 5, "w": 160, "dr": ["0-1x Bone", "0-1x Rotten Flesh", "1x Tanga Berry 2.5%"]}, "cobblemon:p0943_mabosstiff": {"n": 943, "d": "This Pokémon can store energy in its large dewlap. Mabosstiff unleashes this energy all at once to blow away enemies.", "h": 11, "w": 610, "dr": ["0-2x Bone", "0-2x Rotten Flesh", "1x Tanga Berry 5%"]}, "cobblemon:p0944_shroodle": {"n": 944, "d": "Though usually a mellow Pokémon, it will sink its sharp, poison-soaked front teeth into any that anger it, causing paralysis in the object of its ire.", "h": 2, "w": 7, "dr": ["1x Nanab Berry 2.5%"]}, "cobblemon:p0945_grafaiai": {"n": 945, "d": "The color of the poisonous saliva depends on what the Pokémon eats. Grafaiai covers its fingers in its saliva and draws patterns on trees in forests.", "h": 7, "w": 272, "dr": ["1x Nanab Berry 5%"]}, "cobblemon:p0946_bramblin": {"n": 946, "d": "A soul unable to move on to the afterlife was blown around by the wind until it got tangled up with dried grass and became a Pokémon.", "h": 6, "w": 6, "dr": ["0-1x Dead Bush", "0-1x Stick", "1x Kasib Berry 2.5%"]}, "cobblemon:p0947_brambleghast": {"n": 947, "d": "It will open the branches of its head to envelop its prey. Once it absorbs all the life energy it needs, it expels the prey and discards it.", "h": 12, "w": 60, "dr": ["0-2x Dead Bush", "0-2x Stick", "1x Kasib Berry 5%"]}, "cobblemon:p0948_toedscool": {"n": 948, "d": "Toedscool lives in muggy forests. The flaps that fall from its body are chewy and very delicious.", "h": 9, "w": 330, "dr": ["0-1x Brown Mushroom", "1x Yache Berry 2.5%"]}, "cobblemon:p0949_toedscruel": {"n": 949, "d": "These Pokémon gather into groups and form colonies deep within forests. They absolutely hate it when strangers approach.", "h": 19, "w": 580, "dr": ["0-2x Brown Mushroom", "1x Yache Berry 5%"]}, "cobblemon:p0950_klawf": {"n": 950, "d": "Klawf hangs upside-down from cliffs, waiting for prey. But Klawf can't remain in this position for long because its blood rushes to its head.", "h": 13, "w": 790, "dr": ["1x Pinap Berry 5%"]}, "cobblemon:p0951_capsakid": {"n": 951, "d": "The more sunlight this Pokémon bathes in, the more spicy chemicals are produced by its body, and thus the spicier its moves become.", "h": 3, "w": 30, "dr": ["0-1x Roasted Leek", "1x Rawst Berry 2.5%"]}, "cobblemon:p0952_scovillain": {"n": 952, "d": "The red head converts spicy chemicals into fire energy and blasts the surrounding area with a super spicy stream of flame.", "h": 9, "w": 150, "dr": ["0-2x Roasted Leek", "1x Rawst Berry 5%"]}, "cobblemon:p0953_rellor": {"n": 953, "d": "This Pokémon creates a mud ball by mixing sand and dirt with psychic energy. It treasures its mud ball more than its own life.", "h": 2, "w": 10, "dr": ["1x Mud"]}, "cobblemon:p0954_rabsca": {"n": 954, "d": "The body that supports the ball barely moves. Therefore, it is thought that the true body of this Pokémon is actually inside the ball.", "h": 3, "w": 35, "dr": ["1x Ender Pearl"]}, "cobblemon:p0955_flittle": {"n": 955, "d": "Flittle's toes levitate about half an inch above the ground because of the psychic power emitted from the frills on the Pokémon's belly.", "h": 2, "w": 15, "dr": ["1x Chicken", "1x Tanga Berry 2.5%"]}, "cobblemon:p0956_espathra": {"n": 956, "d": "It immobilizes opponents by bathing them in psychic power from its large eyes. Despite its appearance, it has a vicious temperament.", "h": 19, "w": 900, "dr": ["1x Chicken", "1x Tanga Berry 5%"]}, "cobblemon:p0957_tinkatink": {"n": 957, "d": "It swings its handmade hammer around to protect itself, but the hammer is often stolen by Pokémon that eat metal.", "h": 4, "w": 89, "dr": ["0-1x Raw Iron", "1x Razz Berry 2.5%"]}, "cobblemon:p0958_tinkatuff": {"n": 958, "d": "This Pokémon will attack groups of Pawniard and Bisharp, gathering metal from them in order to create a large and sturdy hammer.", "h": 7, "w": 591, "dr": ["0-2x Raw Iron", "1x Razz Berry 5%"]}, "cobblemon:p0959_tinkaton": {"n": 959, "d": "This intelligent Pokémon has a very daring disposition. It knocks rocks into the sky with its hammer, aiming for flying Corviknight.", "h": 7, "w": 1128, "dr": ["0-3x Raw Iron", "1x Razz Berry 10%"]}, "cobblemon:p0960_wiglett": {"n": 960, "d": "This Pokémon can pick up the scent of a Veluza just over 65 feet away and will hide itself in the sand.", "h": 12, "w": 18, "dr": []}, "cobblemon:p0961_wugtrio": {"n": 961, "d": "It has a vicious temperament, contrary to what its appearance may suggest. It wraps its long bodies around prey, then drags the prey into its den.", "h": 12, "w": 54, "dr": []}, "cobblemon:p0963_finizen": {"n": 963, "d": "It likes playing with others of its kind using the water ring on its tail. It uses ultrasonic waves to sense the emotions of other living creatures.", "h": 13, "w": 602, "dr": ["0-1x Cod"]}, "cobblemon:p0964_palafin": {"n": 964, "d": "This Pokémon changes its appearance if it hears its allies calling for help. Palafin will never show anybody its moment of transformation.", "h": 13, "w": 602, "dr": ["0-2x Cod"]}, "cobblemon:p0965_varoom": {"n": 965, "d": "It is said that this Pokémon was born when an unknown poison Pokémon entered and inspirited an engine left at a scrap-processing factory.", "h": 10, "w": 350, "dr": ["0-1x Iron Nugget", "1x Black Sludge 2.5%", "1x Shuca Berry 2.5%"]}, "cobblemon:p0966_revavroom": {"n": 966, "d": "It creates a gas out of poison and minerals from rocks. It then detonates the gas in its cylinders— now numbering eight—to generate energy.", "h": 18, "w": 1200, "dr": ["0-2x Iron Nugget", "1x Black Sludge 5%", "1x Shuca Berry 5%"]}, "cobblemon:p0967_cyclizar": {"n": 967, "d": "Apparently Cyclizar has been allowing people to ride on its back since ancient times. Depictions of this have been found in 10,000-year-old murals.", "h": 16, "w": 630, "dr": ["1x Haban Berry 5%"]}, "cobblemon:p0968_orthworm": {"n": 968, "d": "When attacked, this Pokémon will wield the tendrils on its body like fists and pelt the opponent with a storm of punches.", "h": 25, "w": 3100, "dr": ["0-2x Iron Nugget", "1x Shuca Berry 5%"]}, "cobblemon:p0969_glimmet": {"n": 969, "d": "It absorbs nutrients from cave walls. The petals it wears are made of crystallized poison.", "h": 7, "w": 80, "dr": ["0-1x Amethyst Shard", "1x Shuca Berry 2.5%", "1x Float Stone 2.5%"]}, "cobblemon:p0970_glimmora": {"n": 970, "d": "When this Pokémon detects danger, it will open up its crystalline petals and fire beams from its conical body.", "h": 15, "w": 450, "dr": ["0-2x Amethyst Shard", "1x Shuca Berry 5%", "1x Float Stone 5%"]}, "cobblemon:p0971_greavard": {"n": 971, "d": "It is said that a dog Pokémon that died in the wild without ever interacting with a human was reborn as this Pokémon.", "h": 6, "w": 350, "dr": ["1-2x Bone", "0-1x Rotten Flesh", "1x Candle 2.5%", "1x Kasib Berry 2.5%"]}, "cobblemon:p0972_houndstone": {"n": 972, "d": "Houndstone spends most of its time sleeping in graveyards. Among all the dog Pokémon, this one is most loyal to its master.", "h": 20, "w": 150, "dr": ["1-3x Bone", "0-2x Rotten Flesh", "1x Kasib Berry 5%"]}, "cobblemon:p0973_flamigo": {"n": 973, "d": "This Pokémon apparently ties the base of its neck into a knot so that energy stored in its belly does not escape from its beak.", "h": 16, "w": 370, "dr": ["0-2x Feather", "1x Chicken", "1x Payapa Berry 5%", "1x Fairy Feather 5%"]}, "cobblemon:p0974_cetoddle": {"n": 974, "d": "This species left the ocean and began living on land a very long time ago. It seems to be closely related to Wailmer.", "h": 12, "w": 450, "dr": ["0-1x Bone Block", "1x Aspear Berry 2.5%"]}, "cobblemon:p0975_cetitan": {"n": 975, "d": "This Pokémon wanders around snowy, icy areas. It protects its body with powerful muscles and a thick layer of fat under its skin.", "h": 45, "w": 7000, "dr": ["0-2x Bone Block", "1x Aspear Berry 5%"]}, "cobblemon:p0976_veluza": {"n": 976, "d": "When Veluza discards unnecessary flesh, its mind becomes honed and its psychic power increases. The spare flesh has a mild but delicious flavor.", "h": 25, "w": 900, "dr": ["1-3x Cod", "1x Bone Meal 5%"]}, "cobblemon:p0977_dondozo": {"n": 977, "d": "This Pokémon is a glutton, but it's bad at getting food. It teams up with a Tatsugiri to catch prey.", "h": 120, "w": 2200, "dr": ["1x Salmon", "1x Bone Meal 5%"]}, "cobblemon:p0978_tatsugiri": {"n": 978, "d": "This is a small dragon Pokémon. It lives inside the mouth of Dondozo to protect itself from enemies on the outside.", "h": 3, "w": 80, "dr": ["1x Salmon", "1x Bone Meal 5%", "1x Haban Berry 5%"]}, "cobblemon:p0979_annihilape": {"n": 979, "d": "When its anger rose beyond a critical point, this Pokémon gained power that is unfettered by the limits of its physical body.", "h": 12, "w": 560, "dr": ["1x Muscle Band 10%", "1x Payapa Berry 10%"]}, "cobblemon:p0980_clodsire": {"n": 980, "d": "When attacked, this Pokémon will retaliate by sticking thick spines out from its body. It's a risky move that puts everything on the line.", "h": 18, "w": 2230, "dr": ["0-2x Clay Ball", "1x Pecha Berry 5%"]}, "cobblemon:p0981_farigiraf": {"n": 981, "d": "Now that the brain waves from the head and tail are synced up, the psychic power of this Pokémon is 10 times stronger than Girafarig's.", "h": 32, "w": 1600, "dr": ["0-2x Leather", "1x Razor Fang 5%", "1x Persim Berry 5%"]}, "cobblemon:p0982_dudunsparce": {"n": 982, "d": "This Pokémon uses its hard tail to make its nest by boring holes into bedrock deep underground. The nest can reach lengths of over six miles.", "h": 36, "w": 392, "dr": ["1x Rocky Helmet 5%", "1x Cheri Berry 5%"]}, "cobblemon:p0983_kingambit": {"n": 983, "d": "Only a Bisharp that stands above all others in its vast army can evolve into Kingambit.", "h": 20, "w": 1200, "dr": ["1x Rocky Helmet 5%", "1x Cheri Berry 5%"]}, "cobblemon:p0999_gimmighoul": {"n": 999, "d": "This Pokémon was born inside a treasure chest about 1,500 years ago. It sucks the life-force out of scoundrels who try to steal the treasure.", "h": 3, "w": 50, "dr": ["24-48x Relic Coin"]}, "cobblemon:p1000_gholdengo": {"n": 1000, "d": "Its body seems to be made up of 1,000 coins. This Pokémon gets along well with others and is quick to make friends with anybody.", "h": 12, "w": 300, "dr": ["24-48x Relic Coin"]}, "cobblemon:p1009_walkingwake": {"n": 1009, "d": "It resembles an illustration published in a paranormal magazine, said to be a depiction of a super-ancient Suicune.", "h": 35, "w": 2800, "dr": []}, "cobblemon:p1010_ironleaves": {"n": 1010, "d": "Many of its physical characteristics match those of a Virizion from the future that was covered in a paranormal magazine.", "h": 15, "w": 1250, "dr": []}, "cobblemon:p1011_dipplin": {"n": 1011, "d": "Dipplin is two creatures in one Pokémon. Its evolution was triggered by a special apple grown only in one place.", "h": 4, "w": 44, "dr": []}, "cobblemon:p1012_poltchageist": {"n": 1012, "d": "Supposedly, the regrets of a tea ceremony master who died before perfecting his craft lingered in some matcha and became a Pokémon.", "h": 1, "w": 11, "dr": ["1x Rawst Berry 2.5%"]}, "cobblemon:p1013_sinistcha": {"n": 1013, "d": "It pretends to be tea, trying to fool people into drinking it so it can drain their life-force. Its ruse is generally unsuccessful.", "h": 2, "w": 22, "dr": ["1x Rawst Berry 5%"]}, "cobblemon:p1018_archaludon": {"n": 1018, "d": "It gathers static electricity from its surroundings. The beams it launches when down on all fours are tremendously powerful.", "h": 20, "w": 600, "dr": []}, "cobblemon:p1019_hydrapple": {"n": 1019, "d": "Seven syrpents live inside an apple made of syrup. The syrpent in the center is the commander.", "h": 18, "w": 930, "dr": []}};
